{
  "name": "PAD - Personal Accessibility DNA",
  "description": "A transformative platform that adapts the digital and physical world to individual accessibility needs through a dynamic Personal Accessibility DNA (PAD) profile, AI companionship, and career growth tools.",
  "requestFramePermissions": [
    "camera",
    "microphone",
    "geolocation"
  ]
}

export enum VisionNeed {
  Standard = 'standard',
  LowVision = 'low-vision',
  Blind = 'blind'
}

export enum HearingNeed {
  Standard = 'standard',
  HardOfHearing = 'hard-of-hearing',
  Deaf = 'deaf'
}

export enum MobilityNeed {
  Standard = 'standard',
  LimitedRange = 'limited-range',
  Wheelchair = 'wheelchair'
}

export enum CognitiveMode {
  Standard = 'standard',
  Simplified = 'simplified',
  HighFocus = 'high-focus'
}

export enum FatigueTolerance {
  High = 'high',
  Medium = 'medium',
  Low = 'low'
}

export interface PAD {
  vision: VisionNeed;
  hearing: HearingNeed;
  mobility: MobilityNeed;
  cognitive: CognitiveMode;
  fatigue: FatigueTolerance;
  communicationStyle: string;
  learningPreferences: string[];
}

export interface LocationSimulation {
  id: string;
  name: string;
  type: string;
  description: string;
  baseAccessibilityScore: number;
  noiseLevel: 'low' | 'medium' | 'high';
  lighting: 'dim' | 'bright' | 'harsh';
  crowdLevel: 'empty' | 'steady' | 'busy';
  terrain: 'flat' | 'sloped' | 'stairs';
}

export interface CareerPath {
  title: string;
  compatibility: number;
  description: string;
  skills: string[];
  remoteFriendly: boolean;
}

export interface Message {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  timestamp: number;
}

import { GoogleGenAI, Type } from "@google/genai";
import { PAD, CareerPath } from "../types";

const genAI = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const getCareerGuidance = async (pad: PAD, interests: string): Promise<CareerPath[]> => {
  const model = genAI.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Based on this Personal Accessibility DNA (PAD): ${JSON.stringify(pad)} and user interests: "${interests}", suggest 3 career paths. 
    Focus on abilities and adaptive growth. Return a JSON array of objects with title, compatibility (0-100), description, skills (array), and remoteFriendly (boolean).`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            compatibility: { type: Type.NUMBER },
            description: { type: Type.STRING },
            skills: { 
              type: Type.ARRAY, 
              items: { type: Type.STRING } 
            },
            remoteFriendly: { type: Type.BOOLEAN }
          },
          required: ["title", "compatibility", "description", "skills", "remoteFriendly"]
        }
      }
    }
  });

  const response = await model;
  try {
    return JSON.parse(response.text);
  } catch (e) {
    console.error("Failed to parse career guidance", e);
    return [];
  }
};

export const analyzeSurroundings = async (imageData: string): Promise<string> => {
  const model = genAI.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [
        { inlineData: { data: imageData.split(',')[1], mimeType: 'image/jpeg' } },
        { text: "Describe the immediate surroundings for a person with disabilities. Identify obstacles, signage, and accessibility features like ramps or elevators. Keep it concise." }
      ]
    }
  });
  const response = await model;
  return response.text;
};

export const simplifyDocument = async (text: string): Promise<string> => {
  const model = genAI.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Please simplify the following complex text or form content for someone with cognitive processing needs. Use clear, direct language and bullet points if necessary: \n\n${text}`,
    config: {
      systemInstruction: "You are an accessibility expert specializing in Plain Language and cognitive support."
    }
  });
  const response = await model;
  return response.text;
};

export const getSimulationAnalysis = async (pad: PAD, location: any): Promise<string> => {
  const model = genAI.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Analyze how this user would experience this location. 
    PAD: ${JSON.stringify(pad)}
    Location: ${JSON.stringify(location)}
    Predict physical effort, fatigue risk, and environmental stressors (lighting/noise). Provide a summary.`,
  });
  const response = await model;
  return response.text;
};

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { PAD, VisionNeed, CognitiveMode, FatigueTolerance } from '../types';
import { DEFAULT_PAD } from '../constants';

interface AccessibilityContextType {
  pad: PAD;
  updatePAD: (updates: Partial<PAD>) => void;
  isHighContrast: boolean;
  toggleHighContrast: () => void;
  uiIntensity: 'standard' | 'low-stim';
}

const AccessibilityContext = createContext<AccessibilityContextType | undefined>(undefined);

export const AccessibilityProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [pad, setPad] = useState<PAD>(DEFAULT_PAD);
  const [isHighContrast, setIsHighContrast] = useState(false);

  const updatePAD = (updates: Partial<PAD>) => {
    setPad(prev => ({ ...prev, ...updates }));
  };

  const toggleHighContrast = () => setIsHighContrast(!isHighContrast);

  const uiIntensity = pad.cognitive === CognitiveMode.HighFocus ? 'low-stim' : 'standard';

  // Apply global UI changes based on PAD
  useEffect(() => {
    const root = document.documentElement;

    // Vision Adjustments
    if (pad.vision === VisionNeed.LowVision) {
      root.style.fontSize = '120%';
    } else if (pad.vision === VisionNeed.Blind) {
      root.style.fontSize = '110%'; // Focus on screen readers
    } else {
      root.style.fontSize = '100%';
    }

    // High Contrast Application
    if (isHighContrast) {
      root.classList.add('dark');
    } else {
      root.classList.remove('dark');
    }
  }, [pad, isHighContrast]);

  return (
    <AccessibilityContext.Provider value={{ pad, updatePAD, isHighContrast, toggleHighContrast, uiIntensity }}>
      <div className={`min-h-screen ${isHighContrast ? 'bg-black text-white' : 'bg-slate-50 text-slate-900'}`}>
        {children}
      </div>
    </AccessibilityContext.Provider>
  );
};

export const useAccessibility = () => {
  const context = useContext(AccessibilityContext);
  if (!context) throw new Error('useAccessibility must be used within AccessibilityProvider');
  return context;
};

import React from 'react';
import { useAccessibility } from '../context/AccessibilityContext';
import { CognitiveMode } from '../types';

interface NavigationProps {
  activeTab: string;
  setActiveTab: (tab: string) => void;
}

const Navigation: React.FC<NavigationProps> = ({ activeTab, setActiveTab }) => {
  const { pad, toggleHighContrast, isHighContrast } = useAccessibility();
  const isSimplified = pad.cognitive === CognitiveMode.Simplified;

  const tabs = [
    { id: 'dashboard', label: 'Dashboard', icon: '🏠' },
    { id: 'map', label: isSimplified ? 'Travel Map' : 'Accessibility Map', icon: '🗺️' },
    { id: 'companion', label: isSimplified ? 'AI Friend' : 'AI Companion', icon: '🤖' },
    { id: 'career', label: isSimplified ? 'Jobs & Skills' : 'Career Hub', icon: '💼' },
    { id: 'dna', label: 'My DNA', icon: '🧬' },
  ];

  return (
    <nav className="sticky top-0 z-50 w-full bg-white/80 dark:bg-slate-900/80 backdrop-blur-md border-b border-slate-200 dark:border-slate-800 px-4 py-3">
      <div className="max-w-7xl mx-auto flex items-center justify-between">
        <div className="flex items-center space-x-2">
          <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white font-bold text-xl shadow-lg">P</div>
          {!isSimplified && <span className="text-xl font-bold tracking-tight">PAD Platform</span>}
        </div>

        <div className="flex space-x-1 md:space-x-4">
          {tabs.map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`flex items-center space-x-2 px-3 py-2 rounded-lg transition-all ${
                activeTab === tab.id 
                  ? 'bg-indigo-50 dark:bg-indigo-900/40 text-indigo-600 dark:text-indigo-400 font-semibold' 
                  : 'hover:bg-slate-100 dark:hover:bg-slate-800'
              }`}
            >
              <span className="text-lg">{tab.icon}</span>
              <span className={`${isSimplified ? 'hidden md:inline' : 'inline'}`}>{tab.label}</span>
            </button>
          ))}
        </div>

        <div className="flex items-center space-x-2">
          <button 
            onClick={toggleHighContrast}
            className="p-2 rounded-full hover:bg-slate-100 dark:hover:bg-slate-800 border border-slate-200 dark:border-slate-700"
            title="Toggle High Contrast"
          >
            {isHighContrast ? '☀️' : '🌙'}
          </button>
          <button className="bg-red-500 hover:bg-red-600 text-white px-4 py-2 rounded-lg font-bold shadow-lg animate-pulse">
            SOS
          </button>
        </div>
      </div>
    </nav>
  );
};

export default Navigation;

