import React, { useState } from 'react';
import { useAccessibility } from '../context/AccessibilityContext';
import { MOCK_LOCATIONS } from '../constants';
import { LocationSimulation, MobilityNeed, FatigueTolerance } from '../types';
import { getSimulationAnalysis } from '../services/geminiService';

const MapModule: React.FC = () => {
  const { pad } = useAccessibility();
  const [selectedLoc, setSelectedLoc] = useState<LocationSimulation | null>(null);
  const [analysis, setAnalysis] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const simulateLocation = async (loc: LocationSimulation) => {
    setSelectedLoc(loc);
    setLoading(true);
    setAnalysis(null);
    try {
      const result = await getSimulationAnalysis(pad, loc);
      setAnalysis(result);
    } catch (e) {
      setAnalysis("Simulation failed. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const getPersonalScore = (loc: LocationSimulation) => {
    let score = loc.baseAccessibilityScore;
    if (pad.mobility === MobilityNeed.Wheelchair && loc.terrain === 'stairs') score -= 50;
    if (pad.fatigue === FatigueTolerance.Low && loc.crowdLevel === 'busy') score -= 20;
    return Math.max(0, score);
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
      <div className="lg:col-span-1 space-y-4">
        <h2 className="text-2xl font-bold mb-4">Location Preview</h2>
        {MOCK_LOCATIONS.map(loc => {
          const score = getPersonalScore(loc);
          return (
            <button
              key={loc.id}
              onClick={() => simulateLocation(loc)}
              className={`w-full text-left p-4 rounded-2xl border transition-all ${
                selectedLoc?.id === loc.id ? 'border-indigo-500 bg-indigo-50 dark:bg-indigo-900/20' : 'bg-white dark:bg-slate-900 border-slate-200 dark:border-slate-800'
              }`}
            >
              <div className="flex justify-between items-start mb-2">
                <span className="font-bold text-lg">{loc.name}</span>
                <span className={`px-2 py-1 rounded-full text-xs font-bold ${
                  score > 80 ? 'bg-green-100 text-green-700' : score > 50 ? 'bg-yellow-100 text-yellow-700' : 'bg-red-100 text-red-700'
                }`}>
                  {score}% Compatible
                </span>
              </div>
              <p className="text-sm text-slate-500 dark:text-slate-400 mb-2">{loc.type}</p>
              <div className="flex space-x-2 text-xs">
                <span className="bg-slate-100 dark:bg-slate-800 px-2 py-1 rounded">Noise: {loc.noiseLevel}</span>
                <span className="bg-slate-100 dark:bg-slate-800 px-2 py-1 rounded">Terrain: {loc.terrain}</span>
              </div>
            </button>
          );
        })}
      </div>

      <div className="lg:col-span-2 bg-white dark:bg-slate-900 rounded-3xl p-6 shadow-xl border border-slate-200 dark:border-slate-800 min-h-[500px] flex flex-col">
        {selectedLoc ? (
          <div className="flex-1 flex flex-col">
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-2xl font-bold">{selectedLoc.name} Simulation</h3>
              <div className="flex space-x-2">
                 <span className="p-2 bg-indigo-100 text-indigo-700 rounded-lg">Real-world Preview</span>
              </div>
            </div>

            <div className="grid grid-cols-3 gap-4 mb-8">
              <div className="p-4 bg-slate-50 dark:bg-slate-800 rounded-2xl border border-slate-100 dark:border-slate-700">
                <p className="text-sm text-slate-500 mb-1">Fatigue Risk</p>
                <div className="h-2 w-full bg-slate-200 rounded-full overflow-hidden">
                  <div className={`h-full ${pad.fatigue === FatigueTolerance.Low ? 'w-4/5 bg-red-500' : 'w-1/4 bg-green-500'}`}></div>
                </div>
              </div>
              <div className="p-4 bg-slate-50 dark:bg-slate-800 rounded-2xl border border-slate-100 dark:border-slate-700">
                <p className="text-sm text-slate-500 mb-1">Sensory Load</p>
                <div className="h-2 w-full bg-slate-200 rounded-full overflow-hidden">
                  <div className={`h-full ${selectedLoc.noiseLevel === 'high' ? 'w-3/4 bg-orange-500' : 'w-1/5 bg-green-500'}`}></div>
                </div>
              </div>
              <div className="p-4 bg-slate-50 dark:bg-slate-800 rounded-2xl border border-slate-100 dark:border-slate-700">
                <p className="text-sm text-slate-500 mb-1">Time to Access</p>
                <p className="font-bold">{pad.mobility === MobilityNeed.Wheelchair ? '12 mins' : '5 mins'}</p>
              </div>
            </div>

            <div className="flex-1 bg-slate-50 dark:bg-slate-800/50 rounded-2xl p-6 border-2 border-dashed border-slate-200 dark:border-slate-700 relative">
              {loading ? (
                <div className="absolute inset-0 flex items-center justify-center bg-white/50 dark:bg-slate-900/50">
                  <div className="flex flex-col items-center">
                    <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
                    <p className="mt-4 font-semibold">Generating DNA Simulation...</p>
                  </div>
                </div>
              ) : analysis ? (
                <div className="prose dark:prose-invert max-w-none">
                  <h4 className="text-lg font-bold mb-4">AI Experience Prediction:</h4>
                  <div className="whitespace-pre-wrap text-slate-700 dark:text-slate-300">
                    {analysis}
                  </div>
                </div>
              ) : (
                <div className="h-full flex items-center justify-center text-slate-400">
                  Select a location to start the accessibility simulation
                </div>
              )}
            </div>
          </div>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center text-center p-12">
            <div className="text-6xl mb-6">🛰️</div>
            <h3 className="text-2xl font-bold mb-2">Welcome to the PAD Map</h3>
            <p className="text-slate-500 max-w-md">We analyze real-world data through the lens of your unique Accessibility DNA to predict your experience before you leave home.</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default MapModule;

import React, { useState, useRef } from 'react';
import { useAccessibility } from '../context/AccessibilityContext';
import { VisionNeed, CognitiveMode, Message } from '../types';
import { analyzeSurroundings, simplifyDocument } from '../services/geminiService';

const AICompanion: React.FC = () => {
  const { pad } = useAccessibility();
  const [messages, setMessages] = useState<Message[]>([
    { id: '1', role: 'assistant', content: "Hello! I'm your PAD companion. How can I help you navigate or understand your world today?", timestamp: Date.now() }
  ]);
  const [inputText, setInputText] = useState('');
  const [isCapturing, setIsCapturing] = useState(false);
  const [loading, setLoading] = useState(false);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const sendMessage = (text: string) => {
    if (!text.trim()) return;
    const userMsg: Message = { id: Date.now().toString(), role: 'user', content: text, timestamp: Date.now() };
    setMessages(prev => [...prev, userMsg]);
    setInputText('');

    // Simple mock response for standard chat
    setTimeout(() => {
      const botMsg: Message = { id: (Date.now() + 1).toString(), role: 'assistant', content: "I'm processing that request based on your DNA profile. I've noted your preference for " + pad.communicationStyle + ".", timestamp: Date.now() };
      setMessages(prev => [...prev, botMsg]);
    }, 1000);
  };

  const startCamera = async () => {
    setIsCapturing(true);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: true });
      if (videoRef.current) videoRef.current.srcObject = stream;
    } catch (err) {
      console.error("Camera access denied", err);
      setIsCapturing(false);
    }
  };

  const stopCamera = () => {
    const stream = videoRef.current?.srcObject as MediaStream;
    stream?.getTracks().forEach(track => track.stop());
    setIsCapturing(false);
  };

  const captureAndAnalyze = async () => {
    if (!canvasRef.current || !videoRef.current) return;
    setLoading(true);
    const canvas = canvasRef.current;
    const video = videoRef.current;
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    canvas.getContext('2d')?.drawImage(video, 0, 0);
    const imageData = canvas.toDataURL('image/jpeg');

    try {
      const description = await analyzeSurroundings(imageData);
      setMessages(prev => [...prev, { id: Date.now().toString(), role: 'assistant', content: `[Vision Analysis]: ${description}`, timestamp: Date.now() }]);
      stopCamera();
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex flex-col h-[70vh] bg-white dark:bg-slate-900 rounded-3xl shadow-2xl border border-slate-200 dark:border-slate-800 overflow-hidden">
      <div className="bg-indigo-600 p-4 text-white flex justify-between items-center">
        <div className="flex items-center space-x-3">
          <div className="w-10 h-10 bg-white/20 rounded-full flex items-center justify-center text-xl">🤖</div>
          <div>
            <h3 className="font-bold">AI Companion</h3>
            <p className="text-xs text-indigo-100">Optimized for {pad.cognitive} mode</p>
          </div>
        </div>
        <div className="flex space-x-2">
           <button onClick={isCapturing ? stopCamera : startCamera} className="p-2 hover:bg-white/20 rounded-lg">
             {isCapturing ? '❌ Close Cam' : '📷 Eye'}
           </button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-50 dark:bg-slate-900">
        {isCapturing && (
          <div className="relative rounded-2xl overflow-hidden shadow-xl mb-4">
            <video ref={videoRef} autoPlay playsInline className="w-full bg-black h-64 object-cover" />
            <canvas ref={canvasRef} className="hidden" />
            <div className="absolute bottom-4 left-0 right-0 flex justify-center">
              <button 
                onClick={captureAndAnalyze}
                disabled={loading}
                className="bg-white text-indigo-600 px-6 py-2 rounded-full font-bold shadow-lg flex items-center"
              >
                {loading ? <span className="animate-spin mr-2">⏳</span> : 'Analyze Scene'}
              </button>
            </div>
          </div>
        )}

        {messages.map(msg => (
          <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[80%] p-4 rounded-2xl ${
              msg.role === 'user' 
                ? 'bg-indigo-600 text-white rounded-tr-none' 
                : 'bg-white dark:bg-slate-800 text-slate-800 dark:text-slate-100 shadow-sm border border-slate-200 dark:border-slate-700 rounded-tl-none'
            }`}>
              <p className="text-sm md:text-base whitespace-pre-wrap">{msg.content}</p>
              <p className="text-[10px] mt-2 opacity-50">{new Date(msg.timestamp).toLocaleTimeString()}</p>
            </div>
          </div>
        ))}
        {loading && <div className="text-slate-400 text-sm italic">AI is thinking...</div>}
      </div>

      <form 
        onSubmit={(e) => { e.preventDefault(); sendMessage(inputText); }}
        className="p-4 bg-white dark:bg-slate-800 border-t border-slate-200 dark:border-slate-700 flex space-x-3"
      >
        <input 
          type="text"
          value={inputText}
          onChange={(e) => setInputText(e.target.value)}
          placeholder={pad.cognitive === CognitiveMode.Simplified ? "Type here..." : "How can I help you with your surroundings?"}
          className="flex-1 bg-slate-100 dark:bg-slate-900 border-none rounded-xl px-4 py-3 focus:ring-2 focus:ring-indigo-500 transition-all"
        />
        <button 
          type="submit"
          className="bg-indigo-600 text-white p-3 rounded-xl hover:bg-indigo-700 transition-all active:scale-90"
        >
          ➔
        </button>
      </form>
    </div>
  );
};

