export enum VisionNeed {
  Standard = 'standard',
  LowVision = 'low-vision',
  Blind = 'blind'
}

export enum HearingNeed {
  Standard = 'standard',
  HardOfHearing = 'hard-of-hearing',
  Deaf = 'deaf'
}

export enum MobilityNeed {
  Standard = 'standard',
  LimitedRange = 'limited-range',
  Wheelchair = 'wheelchair'
}

export enum CognitiveMode {
  Standard = 'standard',
  Simplified = 'simplified',
  HighFocus = 'high-focus'
}

export enum FatigueTolerance {
  High = 'high',
  Medium = 'medium',
  Low = 'low'
}

export interface PAD {
  vision: VisionNeed;
  hearing: HearingNeed;
  mobility: MobilityNeed;
  cognitive: CognitiveMode;
  fatigue: FatigueTolerance;
  communicationStyle: string;
  learningPreferences: string[];
  signLanguagePreferred: boolean;
}

export interface LocationSimulation {
  id: string;
