  baseAccessibilityScore: number;
  noiseLevel: 'low' | 'medium' | 'high';
  lighting: 'dim' | 'bright' | 'harsh';
  crowdLevel: 'empty' | 'steady' | 'busy';
  terrain: 'flat' | 'sloped' | 'stairs';
}

export interface CareerPath {
  title: string;
  compatibility: number;
  description: string;
  skills: string[];
  remoteFriendly: boolean;
}

export interface Message {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  timestamp: number;
}

export interface Friend {
  id: string;
  name: string;
  status: 'online' | 'offline' | 'nearby';
