            <button 
              onClick={nextStep}
              disabled={!name.trim()}
              className="w-full bg-indigo-600 hover:bg-indigo-700 disabled:opacity-50 text-white py-5 rounded-2xl font-bold text-xl transition-all active:scale-95 shadow-lg shadow-indigo-100 dark:shadow-none"
