                    <button 
                      key={v}
                      onClick={() => updatePAD({ vision: v })}
                      className={`py-3 rounded-xl border-2 transition-all text-sm font-bold ${pad.vision === v ? 'border-indigo-600 bg-indigo-50 text-indigo-600' : 'border-slate-100 text-slate-400'}`}
