                </div>
              </div>
              <div>
                <label className="text-sm font-bold text-slate-400 uppercase tracking-widest mb-2 block">Hearing</label>
                <div className="grid grid-cols-3 gap-2">
                  {[HearingNeed.Standard, HearingNeed.HardOfHearing, HearingNeed.Deaf].map(h => (
                    <button 
                      key={h}
                      onClick={() => updatePAD({ hearing: h })}
                      className={`py-3 rounded-xl border-2 transition-all text-sm font-bold ${pad.hearing === h ? 'border-indigo-600 bg-indigo-50 text-indigo-600' : 'border-slate-100 text-slate-400'}`}
