                className="flex-1 py-4 rounded-2xl bg-indigo-600 text-white font-bold shadow-lg shadow-indigo-100 dark:shadow-none transition-all active:scale-95"
              >
                Complete DNA
              </button>
            </div>
          </div>
        )}

        <div className="flex justify-center space-x-2">
          {[1, 2, 3].map(i => (
            <div key={i} className={`h-1.5 rounded-full transition-all ${step === i ? 'w-8 bg-indigo-600' : 'w-2 bg-slate-200'}`}></div>
          ))}
        </div>
      </div>
    </div>
  );
};

