import React, { useState, useEffect } from 'react';
import { AccessibilityProvider } from './context/AccessibilityContext';
import Navigation from './components/Navigation';
import Dashboard from './components/Dashboard';
import PADForm from './components/PADForm';
import MapModule from './components/MapModule';
import AICompanion from './components/AICompanion';
import CareerHub from './components/CareerHub';
import SocialHub from './components/SocialHub';
import EmergencySystem from './components/EmergencySystem';
import SignLanguageAvatar from './components/SignLanguageAvatar';
import Onboarding from './components/Onboarding';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [showEmergency, setShowEmergency] = useState(false);
  const [hasOnboarded, setHasOnboarded] = useState(false);

  // Check if user has already onboarded in this session
  useEffect(() => {
    const status = localStorage.getItem('adaptia_onboarded');
    if (status === 'true') {
      setHasOnboarded(true);
    }
  }, []);

  const handleOnboardingComplete = () => {
    setHasOnboarded(true);
    localStorage.setItem('adaptia_onboarded', 'true');
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard': return <Dashboard />;
      case 'dna': return <PADForm />;
      case 'map': return <MapModule />;
      case 'companion': return <AICompanion />;
      case 'career': return <CareerHub />;
      case 'social': return <SocialHub />;
      default: return <Dashboard />;
    }
  };

  if (!hasOnboarded) {
    return (
      <AccessibilityProvider>
        <Onboarding onComplete={handleOnboardingComplete} />
      </AccessibilityProvider>
    );
  }

  return (
    <AccessibilityProvider>
      <div className="min-h-screen pb-20 selection:bg-indigo-100 selection:text-indigo-700 bg-slate-50 dark:bg-slate-950 transition-colors duration-500">
        <Navigation 
          activeTab={activeTab} 
          setActiveTab={setActiveTab} 
          onEmergency={() => setShowEmergency(true)} 
        />

        <main className="max-w-7xl mx-auto px-4 py-8">
          <div className="transition-all duration-500">
            {renderContent()}
          </div>
        </main>

        <SignLanguageAvatar 
          active={activeTab === 'companion' || activeTab === 'map'} 
          message={activeTab === 'companion' ? "I'm ready to translate our conversation." : "I can sign directions as we explore."} 
        />

        {showEmergency && (
          <EmergencySystem onClose={() => setShowEmergency(false)} />
        )}
      </div>
    </AccessibilityProvider>
  );
};

export default App;

