import { GoogleGenAI } from '@google/genai';

// Helper for Base64 (Manual implementation as per rules)
function encode(bytes: Uint8Array) {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const AICompanion: React.FC = () => {
  const { pad } = useAccessibility();
  const [messages, setMessages] = useState<Message[]>([
    { id: '1', role: 'assistant', content: "Hello! I'm your PAD companion. Press the microphone to speak with me in real-time.", timestamp: Date.now() }
  ]);
  const [isActive, setIsActive] = useState(false);
  const [transcription, setTranscription] = useState('');
  const [isListening, setIsListening] = useState(false);

  // Live API Refs
  const audioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef(new Set<AudioBufferSourceNode>());
  const sessionRef = useRef<any>(null);

  const startVoiceSession = async () => {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }
      const outputCtx = audioContextRef.current;
      const inputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });

      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setIsListening(true);
            const source = inputCtx.createMediaStreamSource(stream);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(inputData.length);
              for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;
              const pcmBlob = {
                data: encode(new Uint8Array(int16.buffer)),
                mimeType: 'audio/pcm;rate=16000',
              };
              sessionPromise.then(session => session.sendRealtimeInput({ media: pcmBlob }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);
          },
          onmessage: async (msg: any) => {
            // Audio output
            const audioData = msg.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audioData) {
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              const buffer = await decodeAudioData(decode(audioData), outputCtx, 24000, 1);
              const source = outputCtx.createBufferSource();
              source.buffer = buffer;
              source.connect(outputCtx.destination);
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
            }

            // Transcription
            if (msg.serverContent?.outputTranscription) {
              setTranscription(prev => prev + msg.serverContent.outputTranscription.text);
            }
            if (msg.serverContent?.turnComplete) {
              setMessages(prev => [...prev, { id: Date.now().toString(), role: 'assistant', content: transcription, timestamp: Date.now() }]);
              setTranscription('');
            }
          },
          onclose: () => setIsListening(false),
          onerror: () => setIsListening(false),
        },
        config: {
          responseModalities: ['AUDIO'],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } } },
          outputAudioTranscription: {},
          inputAudioTranscription: {},
          systemInstruction: `You are Adaptia AI, a companion for disabled people. Use the user's DNA profile: ${JSON.stringify(pad)}. Be helpful, clear, and supportive. Use their preferred communication style: ${pad.communicationStyle}.`
        }
      });

      sessionRef.current = await sessionPromise;
      setIsActive(true);
    } catch (e) {
      console.error("Failed to start voice session", e);
    }
  };

  const stopVoiceSession = () => {
    if (sessionRef.current) sessionRef.current.close();
    setIsActive(false);
    setIsListening(false);
  };

  return (
    <div className="flex flex-col h-[75vh] bg-white dark:bg-slate-900 rounded-[3rem] shadow-2xl border border-slate-100 dark:border-slate-800 overflow-hidden animate-in fade-in duration-700">
      <div className="bg-indigo-600 p-8 text-white flex justify-between items-center">
        <div className="flex items-center space-x-6">
          <div className={`w-16 h-16 rounded-full flex items-center justify-center text-3xl shadow-lg ${isListening ? 'bg-rose-500 animate-pulse' : 'bg-white/20'}`}>
            {isListening ? '🎙️' : '🤖'}
          </div>
          <div>
            <h3 className="text-2xl font-black">Voice Companion</h3>
            <p className="text-sm font-bold text-indigo-100 opacity-80 uppercase tracking-widest">Powered by Adaptia Live</p>
          </div>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-8 space-y-6 bg-slate-50/50 dark:bg-slate-900/50">
        {messages.map(msg => (
          <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] p-6 rounded-[2rem] text-lg font-medium shadow-sm transition-all ${
              msg.role === 'user' 
                ? 'bg-indigo-600 text-white rounded-tr-none' 
                : 'bg-white dark:bg-slate-800 text-slate-800 dark:text-slate-100 border border-slate-100 dark:border-slate-700 rounded-tl-none'
            }`}>
              {msg.content}
            </div>
          </div>
        ))}
        {transcription && (
          <div className="flex justify-start">
             <div className="max-w-[85%] p-6 rounded-[2rem] bg-indigo-50 dark:bg-indigo-900/20 text-indigo-600 dark:text-indigo-400 italic text-lg font-medium border border-indigo-100 dark:border-indigo-800 animate-pulse">
               {transcription}...
             </div>
          </div>
        )}
      </div>

      <div className="p-8 bg-white dark:bg-slate-800 border-t border-slate-50 dark:border-slate-700 flex flex-col items-center space-y-6">
        <button 
          onClick={isActive ? stopVoiceSession : startVoiceSession}
          className={`w-24 h-24 rounded-full flex items-center justify-center text-4xl shadow-2xl transition-all active:scale-90 ${isActive ? 'bg-rose-500 text-white hover:bg-rose-600' : 'bg-indigo-600 text-white hover:bg-indigo-700'}`}
        >
          {isActive ? '⏹️' : '🎤'}
        </button>
        <p className="text-xs font-black text-slate-400 uppercase tracking-widest">{isActive ? 'Session Active • Speak Now' : 'Tap to Start Voice Assistant'}</p>
      </div>
    </div>
  );
};

