import Shop from './components/Shop';
import EmergencySystem from './components/EmergencySystem';
import SignLanguageAvatar from './components/SignLanguageAvatar';
import Onboarding from './components/Onboarding';
import { UserRole } from './types';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [showEmergency, setShowEmergency] = useState(false);
  const [userRole, setUserRole] = useState<UserRole | null>(null);

  useEffect(() => {
    const savedRole = localStorage.getItem('adaptia_role');
    if (savedRole) {
      setUserRole(savedRole as UserRole);
    }
  }, []);

  const handleOnboardingComplete = (role: UserRole) => {
    setUserRole(role);
    localStorage.setItem('adaptia_onboarded', 'true');
    localStorage.setItem('adaptia_role', role);
  };

  const renderContent = () => {
    // Basic role-based access control
    if (userRole !== UserRole.User && activeTab !== 'dashboard' && activeTab !== 'dna') {
      return (
        <div className="flex flex-col items-center justify-center py-20 text-center space-y-4">
          <div className="text-6xl">🔒</div>
          <h2 className="text-3xl font-black">Expert Access Restricted</h2>
          <p className="text-slate-500 max-w-md">As a {userRole}, your profile is currently live in the Adaptia Marketplace. Use the DNA tab to manage your professional accessibility credentials.</p>
          <button onClick={() => setActiveTab('dashboard')} className="text-indigo-600 font-bold hover:underline">Back to Dashboard</button>
        </div>
      );
    }

    switch (activeTab) {
      case 'dashboard': return <Dashboard role={userRole!} />;
      case 'dna': return <PADForm />;
      case 'map': return <MapModule />;
      case 'companion': return <AICompanion />;
      case 'career': return <CareerHub />;
      case 'social': return <SocialHub />;
      case 'shop': return <Shop />;
      default: return <Dashboard role={userRole!} />;
    }
  };

  if (!userRole) {
    return (
      <AccessibilityProvider>
        <Onboarding onComplete={handleOnboardingComplete} />
      </AccessibilityProvider>
    );
  }

  return (
    <AccessibilityProvider>
      <div className="min-h-screen pb-20 selection:bg-indigo-100 selection:text-indigo-700 bg-slate-50 dark:bg-slate-950 transition-colors duration-500">
        <Navigation 
          activeTab={activeTab} 
          setActiveTab={setActiveTab} 
          onEmergency={() => setShowEmergency(true)} 
        />

        <main className="max-w-7xl mx-auto px-6 py-12">
          <div className="transition-all duration-500">
            {renderContent()}
          </div>
        </main>

        <SignLanguageAvatar 
          active={activeTab === 'companion' || activeTab === 'map'} 
          message={activeTab === 'companion' ? "I'm translating your conversation into signs." : "I'm ready to guide your physical movement."} 
        />

        {showEmergency && (
          <EmergencySystem onClose={() => setShowEmergency(false)} />
        )}
      </div>
    </AccessibilityProvider>
  );
};

