// Helper for Base64 (Manual implementation as per rules)
function encode(bytes: Uint8Array) {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const AICompanion: React.FC = () => {
  const { pad } = useAccessibility();
  const [messages, setMessages] = useState<Message[]>([
    { id: '1', role: 'assistant', content: "Hello! I'm your PAD companion. Speak to me, and I'll adapt the world for you.", timestamp: Date.now() }
  ]);
  const [isActive, setIsActive] = useState(false);
  const [userTranscription, setUserTranscription] = useState('');
  const [aiTranscription, setAiTranscription] = useState('');
  const [isSpeaking, setIsSpeaking] = useState(false);

  // Live API Refs
  const audioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef(new Set<AudioBufferSourceNode>());
  const sessionRef = useRef<any>(null);

  const userTranscriptionRef = useRef('');
  const aiTranscriptionRef = useRef('');

  const startVoiceSession = async () => {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }
      const outputCtx = audioContextRef.current;
      const inputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });

      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setIsActive(true);
            const source = inputCtx.createMediaStreamSource(stream);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(inputData.length);
              for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;
              const pcmBlob = {
                data: encode(new Uint8Array(int16.buffer)),
                mimeType: 'audio/pcm;rate=16000',
              };
              sessionPromise.then(session => session.sendRealtimeInput({ media: pcmBlob }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            // Interruption
            const interrupted = message.serverContent?.interrupted;
            if (interrupted) {
              for (const source of sourcesRef.current.values()) {
                source.stop();
                sourcesRef.current.delete(source);
              }
              nextStartTimeRef.current = 0;
              setIsSpeaking(false);
            }

            // User Transcription
            if (message.serverContent?.inputTranscription) {
              const text = message.serverContent.inputTranscription.text;
              userTranscriptionRef.current += text;
              setUserTranscription(userTranscriptionRef.current);
            }

            // AI Transcription
            if (message.serverContent?.outputTranscription) {
              const text = message.serverContent.outputTranscription.text;
              aiTranscriptionRef.current += text;
              setAiTranscription(aiTranscriptionRef.current);
            }

            // Audio Output
            const audioData = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
            if (audioData) {
              setIsSpeaking(true);
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              const buffer = await decodeAudioData(decode(audioData), outputCtx, 24000, 1);
              const source = outputCtx.createBufferSource();
              source.buffer = buffer;
              source.connect(outputCtx.destination);

              source.addEventListener('ended', () => {
                sourcesRef.current.delete(source);
                if (sourcesRef.current.size === 0) setIsSpeaking(false);
              });

              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              sourcesRef.current.add(source);
            }

            // Turn Complete
            if (message.serverContent?.turnComplete) {
              if (userTranscriptionRef.current) {
                setMessages(prev => [...prev, { id: Date.now().toString() + '-u', role: 'user', content: userTranscriptionRef.current, timestamp: Date.now() }]);
              }
              if (aiTranscriptionRef.current) {
                setMessages(prev => [...prev, { id: Date.now().toString() + '-a', role: 'assistant', content: aiTranscriptionRef.current, timestamp: Date.now() }]);
              }
              userTranscriptionRef.current = '';
              aiTranscriptionRef.current = '';
              setUserTranscription('');
              setAiTranscription('');
            }
          },
          onclose: () => setIsActive(false),
          onerror: (err) => {
            console.error("AI Session Error:", err);
            setIsActive(false);
          },
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } } },
          outputAudioTranscription: {},
          inputAudioTranscription: {},
          systemInstruction: `You are Adaptia AI, a core component of the Adaptia platform (Creators: Naksh & Lakshita). Your purpose is to help disabled people adapt the world. 
          Use the user's Accessibility DNA: ${JSON.stringify(pad)}. 
          Be conversational, provide step-by-step assistance, and read out visual information if the user is blind. 
          Respond naturally to commands like 'Analyze this document' or 'How is the crowd at the park?'.`
        }
      });

      sessionRef.current = await sessionPromise;
    } catch (e) {
      console.error("Failed to start voice session", e);
    }
  };

  const stopVoiceSession = () => {
    if (sessionRef.current) {
      sessionRef.current.close();
      sessionRef.current = null;
    }
    setIsActive(false);
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-4 gap-8 h-full max-h-[85vh]">
      <div className="lg:col-span-3 flex flex-col bg-white dark:bg-slate-900 rounded-[3rem] shadow-2xl border border-slate-100 dark:border-slate-800 overflow-hidden">
        <div className="bg-indigo-600 p-8 text-white flex justify-between items-center shadow-lg">
          <div className="flex items-center space-x-6">
            <div className={`w-14 h-14 rounded-2xl flex items-center justify-center text-3xl transition-all ${isActive ? 'bg-rose-500 animate-pulse' : 'bg-white/20'}`}>
              {isActive ? '🎙️' : '🤖'}
            </div>
            <div>
              <h3 className="text-2xl font-black">Live Companion</h3>
              <p className="text-xs font-bold text-indigo-100 opacity-80 uppercase tracking-widest">{isActive ? 'Active & Listening' : 'Standby Mode'}</p>
            </div>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-10 space-y-8 bg-slate-50/30 dark:bg-slate-900/50">
          {messages.map(msg => (
            <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-in slide-in-from-bottom-2`}>
              <div className={`max-w-[80%] p-6 rounded-[2.5rem] text-lg font-medium shadow-sm border ${
                msg.role === 'user' 
                  ? 'bg-indigo-600 text-white border-indigo-500 rounded-tr-none' 
                  : 'bg-white dark:bg-slate-800 text-slate-800 dark:text-slate-100 border-slate-100 dark:border-slate-700 rounded-tl-none'
              }`}>
                {msg.content}
              </div>
            </div>
          ))}

          {userTranscription && (
            <div className="flex justify-end opacity-70 italic animate-pulse">
              <div className="max-w-[80%] p-6 rounded-[2.5rem] bg-slate-200 dark:bg-slate-800 text-slate-600 dark:text-slate-400 text-lg rounded-tr-none">
                {userTranscription}...
              </div>
            </div>
          )}

          {aiTranscription && (
            <div className="flex justify-start opacity-90 animate-pulse">
               <div className="max-w-[80%] p-6 rounded-[2.5rem] bg-indigo-50 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 text-lg rounded-tl-none border border-indigo-100/50">
                 {aiTranscription}
               </div>
            </div>
          )}
        </div>

        <div className="p-10 bg-white dark:bg-slate-800 border-t border-slate-50 dark:border-slate-700 flex flex-col items-center">
          <button 
            onClick={isActive ? stopVoiceSession : startVoiceSession}
            className={`w-28 h-28 rounded-full flex items-center justify-center text-5xl shadow-2xl transition-all active:scale-90 ${isActive ? 'bg-rose-500 text-white hover:bg-rose-600' : 'bg-indigo-600 text-white hover:bg-indigo-700 hover:shadow-indigo-500/40'}`}
          >
            {isActive ? '⏹️' : '🎤'}
          </button>
          <p className="mt-6 text-xs font-black text-slate-400 uppercase tracking-widest">
            {isActive ? 'Command active • Tap to end' : 'Tap to start voice command'}
          </p>
        </div>
      </div>

      <div className="lg:col-span-1 space-y-6">
        <div className="bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] border border-slate-100 dark:border-slate-800 shadow-xl h-full flex flex-col items-center justify-center text-center">
          <h4 className="font-black text-slate-400 uppercase text-[10px] tracking-widest mb-4">Sign Language Monitor</h4>
          <SignLanguageAvatar 
            message={aiTranscription || messages[messages.length-1]?.content} 
            active={isSpeaking} 
          />
          <p className="mt-6 text-sm text-slate-500 font-medium px-4">
            Translating spoken response into visual signs for real-time clarity.
          </p>
        </div>
      </div>
    </div>
  );
