        {MOCK_LOCATIONS.map(loc => (
          <button
            key={loc.id}
            onClick={() => simulateLocation(loc)}
            className={`w-full text-left p-6 rounded-[2rem] border-2 transition-all ${
              selectedLoc?.id === loc.id ? 'border-indigo-600 bg-indigo-50 dark:bg-indigo-900/20' : 'bg-white dark:bg-slate-900 border-slate-100 dark:border-slate-800'
            }`}
          >
            <div className="flex justify-between items-start mb-2">
              <span className="font-black text-lg">{loc.name}</span>
            </div>
            <p className="text-xs text-slate-500 font-bold uppercase tracking-widest">{loc.type}</p>
          </button>
        ))}

        <div className="bg-slate-900 p-8 rounded-[2.5rem] text-white space-y-6">
           <h4 className="font-black text-xs uppercase tracking-[0.3em] text-indigo-400">Live DNA Radar</h4>
           <div className="flex items-center space-x-4">
             <div className="w-3 h-3 bg-emerald-500 rounded-full animate-ping"></div>
             <p className="text-sm font-bold">{coords ? `${coords.lat.toFixed(4)}, ${coords.lng.toFixed(4)}` : 'Scanning for location...'}</p>
           </div>
           <p className="text-xs text-slate-400 leading-relaxed font-medium">Your location is being shared with your assigned mentor 'Marcus' for navigation support.</p>
        </div>
      </div>

      <div className="lg:col-span-2 space-y-8">
        <div className="bg-slate-100 dark:bg-slate-800/50 rounded-[3rem] h-80 relative overflow-hidden border-2 border-slate-200 dark:border-slate-700 shadow-inner group">
           {/* High-tech Radar Map Background */}
           <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-from)_0%,_transparent_70%)] from-indigo-500/10"></div>
           <div className="absolute inset-0 opacity-20" style={{backgroundImage: 'radial-gradient(#6366f1 0.5px, transparent 0.5px)', backgroundSize: '24px 24px'}}></div>

           {/* Center Point (User) */}
           <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2">
              <div className="w-12 h-12 bg-indigo-600/20 rounded-full animate-ping"></div>
              <div className="w-6 h-6 bg-indigo-600 rounded-full border-4 border-white dark:border-slate-900 absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 shadow-lg"></div>
           </div>

           {/* Nearby Pins */}
