// Helper for Base64 (Manual implementation as per rules)
function encode(bytes: Uint8Array) {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const AICompanion: React.FC = () => {
  const { pad } = useAccessibility();
  const [messages, setMessages] = useState<Message[]>([
    { id: '1', role: 'assistant', content: "Hello! I'm your PAD companion. I'm trained to be pause-aware and repeat-tolerant. Speak freely, or use 'Speak-for-me'.", timestamp: Date.now() }
  ]);
  const [isActive, setIsActive] = useState(false);
  const [userTranscription, setUserTranscription] = useState('');
  const [aiTranscription, setAiTranscription] = useState('');
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [isVisionActive, setIsVisionActive] = useState(false);
  const [speakForMeText, setSpeakForMeText] = useState('');

  // Live API Refs
  const audioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef(new Set<AudioBufferSourceNode>());
  const sessionRef = useRef<any>(null);
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const frameIntervalRef = useRef<number | null>(null);

  const userTranscriptionRef = useRef('');
  const aiTranscriptionRef = useRef('');

  const stopVoiceSession = () => {
    if (sessionRef.current) {
      sessionRef.current.close();
      sessionRef.current = null;
    }
    if (frameIntervalRef.current) {
      window.clearInterval(frameIntervalRef.current);
      frameIntervalRef.current = null;
    }
    setIsActive(false);
    setIsVisionActive(false);
    if (videoRef.current?.srcObject) {
      const stream = videoRef.current.srcObject as MediaStream;
      stream.getTracks().forEach(track => track.stop());
    }
  };

  const startVoiceSession = async () => {
    try {
      // Fix: Use process.env.API_KEY directly as per guidelines
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }
      const outputCtx = audioContextRef.current;
      const inputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });

      const stream = await navigator.mediaDevices.getUserMedia({ audio: true, video: isVisionActive });

      if (isVisionActive && videoRef.current) {
        videoRef.current.srcObject = stream;
      }

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setIsActive(true);
            const source = inputCtx.createMediaStreamSource(stream);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(inputData.length);
              for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;
              const pcmBlob = {
                data: encode(new Uint8Array(int16.buffer)),
                mimeType: 'audio/pcm;rate=16000',
              };
              // Use sessionPromise to ensure session is resolved before sending data
              sessionPromise.then(session => session.sendRealtimeInput({ media: pcmBlob }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);

            if (isVisionActive) {
              frameIntervalRef.current = window.setInterval(() => {
                if (canvasRef.current && videoRef.current) {
                  const ctx = canvasRef.current.getContext('2d');
                  if (ctx) {
                    canvasRef.current.width = videoRef.current.videoWidth || 640;
                    canvasRef.current.height = videoRef.current.videoHeight || 480;
                    ctx.drawImage(videoRef.current, 0, 0);
                    const base64Data = canvasRef.current.toDataURL('image/jpeg', 0.6).split(',')[1];
                    sessionPromise.then(session => {
                      session.sendRealtimeInput({
                        media: { data: base64Data, mimeType: 'image/jpeg' }
                      });
                    });
                  }
                }
              }, 1000);
            }
          },
          onmessage: async (message: LiveServerMessage) => {
            const interrupted = message.serverContent?.interrupted;
            if (interrupted) {
              for (const source of sourcesRef.current.values()) {
                source.stop();
                sourcesRef.current.delete(source);
              }
              nextStartTimeRef.current = 0;
              setIsSpeaking(false);
            }

            if (message.serverContent?.inputTranscription) {
              userTranscriptionRef.current += message.serverContent.inputTranscription.text;
              setUserTranscription(userTranscriptionRef.current);
            }

            if (message.serverContent?.outputTranscription) {
              aiTranscriptionRef.current += message.serverContent.outputTranscription.text;
              setAiTranscription(aiTranscriptionRef.current);
            }

            const audioData = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
            if (audioData) {
              setIsSpeaking(true);
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              const buffer = await decodeAudioData(decode(audioData), outputCtx, 24000, 1);
              const source = outputCtx.createBufferSource();
              source.buffer = buffer;
              source.connect(outputCtx.destination);
              source.addEventListener('ended', () => {
                sourcesRef.current.delete(source);
                if (sourcesRef.current.size === 0) setIsSpeaking(false);
              });
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              sourcesRef.current.add(source);
            }

            if (message.serverContent?.turnComplete) {
              if (userTranscriptionRef.current) {
                setMessages(prev => [...prev, { id: Date.now() + '-u', role: 'user', content: userTranscriptionRef.current, timestamp: Date.now() }]);
              }
              if (aiTranscriptionRef.current) {
                setMessages(prev => [...prev, { id: Date.now() + '-a', role: 'assistant', content: aiTranscriptionRef.current, timestamp: Date.now() }]);
              }
              userTranscriptionRef.current = '';
              aiTranscriptionRef.current = '';
              setUserTranscription('');
              setAiTranscription('');
            }
          },
          onclose: () => stopVoiceSession(),
          onerror: (err) => {
            console.error("AI Session Error:", err);
            stopVoiceSession();
          },
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } } },
          outputAudioTranscription: {},
          inputAudioTranscription: {},
          systemInstruction: `You are Adaptia AI. You have access to the user's Accessibility DNA: ${JSON.stringify(pad)}. 
          The user has a speech style of: ${pad.speechStyle}. Be extremely patient, repeat-tolerant, and pause-aware. 
          If they have difficulty speaking, encourage them and wait longer. 
          ${isVisionActive ? 'You can see the camera feed. Describe obstacles, people, or items in front of the user.' : 'You are in audio-only mode.'}
          Creators: Naksh and Lakshita.`
        }
      });

      sessionRef.current = await sessionPromise;
    } catch (e) {
      console.error("Failed to start session", e);
    }
  };

  const handleSpeakForMe = async () => {
    if (!speakForMeText || !isActive || !sessionRef.current) return;
    // We send a text input as if the user typed it, but instructing the AI to "Speak for me"
    sessionRef.current.sendRealtimeInput({
      text: `SPEAK THIS FOR ME CLEARLY: ${speakForMeText}`
    });
    setSpeakForMeText('');
  };

  return (
    <div className="flex flex-col lg:flex-row gap-6 h-[80vh]">
      <div className="flex-1 flex flex-col bg-white dark:bg-slate-900 rounded-[3rem] shadow-2xl border border-slate-100 dark:border-slate-800 overflow-hidden">
        <div className="bg-indigo-600 p-6 text-white flex justify-between items-center shadow-md">
          <div className="flex items-center space-x-4">
            <div className={`w-12 h-12 rounded-xl flex items-center justify-center text-2xl transition-all ${isActive ? 'bg-rose-500 animate-pulse' : 'bg-white/20'}`}>
              {isActive ? '🎙️' : '🤖'}
            </div>
            <div>
              <h3 className="text-xl font-black">Live Companion</h3>
              <p className="text-[10px] font-bold text-indigo-100 opacity-80 uppercase tracking-widest">{isActive ? 'AI Active • Ready to Listen' : 'Standby'}</p>
            </div>
          </div>
          <button 
            onClick={() => setIsVisionActive(!isVisionActive)}
            disabled={isActive}
            className={`px-4 py-2 rounded-xl text-xs font-black transition-all ${isVisionActive ? 'bg-white text-indigo-600' : 'bg-indigo-500 text-white hover:bg-indigo-400'} disabled:opacity-50`}
          >
            {isVisionActive ? '📷 VISION ON' : '📷 VISION OFF'}
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-8 space-y-6 bg-slate-50/30 dark:bg-slate-900/50 scrollbar-hide">
          {messages.map(msg => (
            <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div className={`max-w-[85%] p-5 rounded-[2rem] text-md font-medium shadow-sm border ${
                msg.role === 'user' ? 'bg-indigo-600 text-white rounded-tr-none' : 'bg-white dark:bg-slate-800 text-slate-800 dark:text-slate-100 rounded-tl-none border-slate-100 dark:border-slate-700'
              }`}>
                {msg.content}
              </div>
            </div>
          ))}
          {userTranscription && <div className="text-right text-slate-400 italic text-sm px-4">Detecting: {userTranscription}...</div>}
          {aiTranscription && <div className="text-left text-indigo-500 font-bold italic text-sm px-4">AI: {aiTranscription}...</div>}
        </div>

        <div className="p-8 bg-white dark:bg-slate-800 border-t border-slate-100 dark:border-slate-700 space-y-6">
          <div className="flex items-center space-x-3">
            <input 
              type="text" 
              placeholder="Speak for me: Type what you want to say..." 
              value={speakForMeText}
              onChange={(e) => setSpeakForMeText(e.target.value)}
              className="flex-1 bg-slate-50 dark:bg-slate-700 px-6 py-4 rounded-2xl border border-slate-100 dark:border-slate-600 text-sm font-bold"
            />
            <button 
              onClick={handleSpeakForMe}
              className="bg-indigo-600 text-white px-6 py-4 rounded-2xl font-black text-sm uppercase tracking-widest hover:bg-indigo-700 transition-all shadow-xl"
            >
              Speak
            </button>
          </div>

          <div className="flex flex-col items-center">
            <button 
              onClick={isActive ? stopVoiceSession : startVoiceSession}
              className={`w-20 h-20 rounded-full flex items-center justify-center text-3xl shadow-2xl transition-all active:scale-90 ${isActive ? 'bg-rose-500 text-white' : 'bg-indigo-600 text-white'}`}
            >
              {isActive ? '⏹️' : '🎤'}
            </button>
            <p className="mt-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">{isActive ? 'Listening • Pause Tolerant Active' : 'Start Interaction'}</p>
          </div>
        </div>
      </div>

      <div className="w-full lg:w-[320px] space-y-6">
        {isVisionActive && (
          <div className="bg-slate-900 rounded-[2.5rem] overflow-hidden shadow-2xl relative border-4 border-indigo-500/20 aspect-video lg:aspect-square flex items-center justify-center">
            <video ref={videoRef} autoPlay playsInline muted className="w-full h-full object-cover" />
            <canvas ref={canvasRef} className="hidden" />
            <div className="absolute top-4 left-4 bg-rose-600 px-3 py-1 rounded-full text-[10px] font-black text-white">LIVE FEED</div>
          </div>
        )}
        <div className="bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] shadow-xl border border-slate-100 dark:border-slate-800">
          <SignLanguageAvatar active={isSpeaking} message={aiTranscription || messages[messages.length-1]?.content} />
        </div>
      </div>
    </div>
  );
};

