        {activeTab !== 'companion' && (
          <div className="fixed bottom-8 right-8 w-48 hidden lg:block z-40">
            <SignLanguageAvatar 
              active={false} 
              message="Adaptia is standing by." 
            />
          </div>
        )}

        {showEmergency && (
          <EmergencySystem onClose={() => setShowEmergency(false)} />
        )}
      </div>
    </AccessibilityProvider>
  );
};

