        {/* Conversation Area */}
        <div className="z-10 flex-1 overflow-y-auto p-8 space-y-6 bg-transparent scrollbar-hide">
          {messages.map(msg => (
            <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-in slide-in-from-bottom-2`}>
