        ) : (
          <div className="flex-1 bg-indigo-50 dark:bg-indigo-900/10 rounded-[3rem] border border-dashed border-indigo-200 dark:border-indigo-800 flex flex-col items-center justify-center p-12 text-center space-y-6 animate-in fade-in duration-500">
             <div className="text-6xl grayscale opacity-30">📷</div>
             <p className="text-indigo-600/60 dark:text-indigo-400 font-black text-xs uppercase tracking-widest leading-relaxed">
