        )}

        {/* Translation Hub */}
        <div className="h-[400px] bg-white dark:bg-slate-900 p-8 rounded-[3rem] shadow-2xl border border-slate-100 dark:border-slate-800 flex flex-col items-center">
          <SignLanguageAvatar active={isSpeaking} message={aiTranscription || messages[messages.length-1]?.content} />
        </div>
