import React, { useState, useRef, useEffect } from 'react';
import { useAccessibility } from '../context/AccessibilityContext';
import { Message, SpeechStyle } from '../types';
import { GoogleGenAI, LiveServerMessage, Modality } from '@google/genai';
import SignLanguageAvatar from './SignLanguageAvatar';

function encode(bytes: Uint8Array) {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const AICompanion: React.FC = () => {
  const { pad } = useAccessibility();
  const [messages, setMessages] = useState<Message[]>([
    { id: '1', role: 'assistant', content: "Vision Mode is ready. Share your view with me or a mentor for real-time guidance.", timestamp: Date.now() }
  ]);
  const [isActive, setIsActive] = useState(false);
  const [userTranscription, setUserTranscription] = useState('');
  const [aiTranscription, setAiTranscription] = useState('');
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [isVisionActive, setIsVisionActive] = useState(false);
  const [speakForMeText, setSpeakForMeText] = useState('');
  const [showMentorView, setShowMentorView] = useState(false);

  const audioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef(new Set<AudioBufferSourceNode>());
  const sessionRef = useRef<any>(null);
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const frameIntervalRef = useRef<number | null>(null);

  const userTranscriptionRef = useRef('');
  const aiTranscriptionRef = useRef('');

  const stopVoiceSession = () => {
    if (sessionRef.current) {
      sessionRef.current.close();
      sessionRef.current = null;
    }
    if (frameIntervalRef.current) {
      window.clearInterval(frameIntervalRef.current);
      frameIntervalRef.current = null;
    }
    setIsActive(false);
    setIsVisionActive(false);
    if (videoRef.current?.srcObject) {
      const stream = videoRef.current.srcObject as MediaStream;
      stream.getTracks().forEach(track => track.stop());
      videoRef.current.srcObject = null;
    }
  };

  const startVoiceSession = async () => {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }
      const outputCtx = audioContextRef.current;
      const inputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });

      // Request both audio and video
      const stream = await navigator.mediaDevices.getUserMedia({ 
        audio: true, 
        video: isVisionActive ? { 
          width: { ideal: 1280 }, 
          height: { ideal: 720 },
          facingMode: 'environment' 
        } : false 
      });

      if (isVisionActive && videoRef.current) {
        videoRef.current.srcObject = stream;
      }

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setIsActive(true);
            const source = inputCtx.createMediaStreamSource(stream);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(inputData.length);
              for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;
              const pcmBlob = {
                data: encode(new Uint8Array(int16.buffer)),
                mimeType: 'audio/pcm;rate=16000',
              };
              sessionPromise.then(session => session.sendRealtimeInput({ media: pcmBlob }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);

            if (isVisionActive) {
              frameIntervalRef.current = window.setInterval(() => {
                if (canvasRef.current && videoRef.current && videoRef.current.readyState >= 2) {
                  const ctx = canvasRef.current.getContext('2d');
                  if (ctx) {
                    canvasRef.current.width = videoRef.current.videoWidth || 640;
                    canvasRef.current.height = videoRef.current.videoHeight || 480;
                    ctx.drawImage(videoRef.current, 0, 0);
                    const base64Data = canvasRef.current.toDataURL('image/jpeg', 0.5).split(',')[1];
                    sessionPromise.then(session => {
                      session.sendRealtimeInput({
                        media: { data: base64Data, mimeType: 'image/jpeg' }
                      });
                    });
                  }
                }
              }, 1500);
            }
          },
          onmessage: async (message: LiveServerMessage) => {
            const interrupted = message.serverContent?.interrupted;
            if (interrupted) {
              for (const source of sourcesRef.current.values()) {
                source.stop();
                sourcesRef.current.delete(source);
              }
              nextStartTimeRef.current = 0;
              setIsSpeaking(false);
            }

            if (message.serverContent?.inputTranscription) {
              userTranscriptionRef.current += message.serverContent.inputTranscription.text;
              setUserTranscription(userTranscriptionRef.current);
            }

            if (message.serverContent?.outputTranscription) {
              aiTranscriptionRef.current += message.serverContent.outputTranscription.text;
              setAiTranscription(aiTranscriptionRef.current);
            }

            const audioData = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
            if (audioData) {
              setIsSpeaking(true);
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              const buffer = await decodeAudioData(decode(audioData), outputCtx, 24000, 1);
              const source = outputCtx.createBufferSource();
              source.buffer = buffer;
              source.connect(outputCtx.destination);
              source.addEventListener('ended', () => {
                sourcesRef.current.delete(source);
                if (sourcesRef.current.size === 0) setIsSpeaking(false);
              });
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              sourcesRef.current.add(source);
            }

            if (message.serverContent?.turnComplete) {
              if (userTranscriptionRef.current) {
                setMessages(prev => [...prev, { id: Date.now() + '-u', role: 'user', content: userTranscriptionRef.current, timestamp: Date.now() }]);
              }
              if (aiTranscriptionRef.current) {
                setMessages(prev => [...prev, { id: Date.now() + '-a', role: 'assistant', content: aiTranscriptionRef.current, timestamp: Date.now() }]);
              }
              userTranscriptionRef.current = '';
              aiTranscriptionRef.current = '';
              setUserTranscription('');
              setAiTranscription('');
            }
          },
          onclose: () => stopVoiceSession(),
          onerror: (err) => {
            console.error("AI Session Error:", err);
            stopVoiceSession();
          },
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } } },
          outputAudioTranscription: {},
          inputAudioTranscription: {},
          systemInstruction: `You are Adaptia AI. Context: User DNA is ${JSON.stringify(pad)}. 
          Speech Style: ${pad.speechStyle}. Language: ${pad.primaryLanguage}.
          Analyze surroundings to identify ramps, elevators, and obstacles. 
          Respond in a calm, clear voice suitable for high accessibility. 
          If the user is blind, be extremely descriptive about the spatial layout.`
        }
      });

      sessionRef.current = await sessionPromise;
    } catch (e) {
      console.error("Failed to start session", e);
    }
  };

  const handleSpeakForMe = () => {
    if (!speakForMeText || !isActive || !sessionRef.current) return;
    sessionRef.current.sendRealtimeInput({
      text: `SPEAK THIS FOR ME CLEARLY: ${speakForMeText}`
    });
    setSpeakForMeText('');
  };

  return (
    <div className="flex flex-col lg:flex-row gap-6 h-full min-h-[80vh] max-h-[90vh] overflow-hidden">
      {/* Immersive Main Display */}
      <div className="flex-[3] flex flex-col bg-white dark:bg-slate-900 rounded-[3rem] shadow-2xl border border-slate-100 dark:border-slate-800 overflow-hidden relative">

        {/* Full Screen Camera Background if Vision Active */}
        {isVisionActive && (
          <div className="absolute inset-0 z-0">
             <video ref={videoRef} autoPlay playsInline muted className="w-full h-full object-cover" />
             <div className="absolute inset-0 bg-gradient-to-b from-indigo-900/40 via-transparent to-slate-950/80"></div>
          </div>
        )}

        {/* Floating Header */}
        <div className="z-10 p-6 flex justify-between items-center pointer-events-auto">
          <div className="flex items-center space-x-4 bg-black/40 backdrop-blur-xl p-4 rounded-[2rem] border border-white/20">
            <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-2xl transition-all shadow-xl ${isActive ? 'bg-rose-500 animate-pulse' : 'bg-white/20'}`}>
              {isActive ? '🎙️' : '🤖'}
            </div>
            <div>
              <h3 className="text-xl font-black text-white tracking-tight">Adaptia Live</h3>
              <p className="text-[9px] font-black text-white/60 uppercase tracking-widest">{isActive ? 'Bi-Directional Feed Active' : 'Waiting for activation'}</p>
            </div>
          </div>

          <div className="flex items-center space-x-3 bg-black/40 backdrop-blur-xl p-3 rounded-[2rem] border border-white/20">
             <button 
               onClick={() => setIsVisionActive(!isVisionActive)}
               disabled={isActive}
               className={`px-5 py-2.5 rounded-2xl text-[10px] font-black tracking-widest transition-all ${isVisionActive ? 'bg-white text-indigo-600' : 'bg-white/10 text-white hover:bg-white/20'} disabled:opacity-50`}
             >
               {isVisionActive ? '📷 VISION ACTIVE' : '📷 VISION OFF'}
             </button>
             {isVisionActive && (
                <button 
                  onClick={() => setShowMentorView(!showMentorView)}
                  className={`px-5 py-2.5 rounded-2xl text-[10px] font-black tracking-widest transition-all ${showMentorView ? 'bg-emerald-500 text-white' : 'bg-white/10 text-white hover:bg-white/20'}`}
                >
                  {showMentorView ? 'MENTOR WATCHING' : 'SHARE VIEW'}
                </button>
             )}
          </div>
        </div>

        {/* Chat / Transcript Overlay */}
        <div className="z-10 flex-1 overflow-y-auto p-8 space-y-4 scrollbar-hide flex flex-col justify-end">
          <div className="space-y-4 max-w-2xl">
            {messages.slice(-4).map(msg => (
              <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-2`}>
                <div className={`p-5 rounded-[2rem] text-lg font-semibold shadow-2xl border backdrop-blur-xl ${
                  msg.role === 'user' 
                    ? 'bg-indigo-600/90 text-white border-indigo-400 rounded-tr-none' 
                    : 'bg-white/90 dark:bg-slate-800/90 text-slate-800 dark:text-slate-100 border-white/20 dark:border-slate-700 rounded-tl-none'
                }`}>
                  {msg.content}
                </div>
              </div>
            ))}
            {userTranscription && <div className="text-white/80 italic font-bold text-sm px-6 bg-black/20 backdrop-blur-md py-2 rounded-full w-fit">Detecting: {userTranscription}...</div>}
            {aiTranscription && (
               <div className="flex justify-start animate-in fade-in">
                 <div className="p-5 rounded-[2rem] bg-indigo-50/90 dark:bg-indigo-900/60 text-indigo-700 dark:text-indigo-400 border border-indigo-200 dark:border-indigo-800 italic font-bold text-lg rounded-tl-none shadow-2xl">
                   {aiTranscription}...
                 </div>
               </div>
            )}
          </div>
        </div>

        {/* Control Footer */}
        <div className="z-10 p-8 bg-gradient-to-t from-slate-950/80 to-transparent border-t border-white/10 backdrop-blur-md space-y-6">
          <div className="flex items-center space-x-4 max-w-4xl mx-auto">
            <input 
              type="text" 
              placeholder="Speak-for-me: Type phrase..." 
              value={speakForMeText}
              onChange={(e) => setSpeakForMeText(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSpeakForMe()}
              className="flex-1 bg-white/10 backdrop-blur-xl px-8 py-5 rounded-3xl border border-white/20 text-white text-lg font-bold outline-none focus:ring-4 focus:ring-indigo-500/50 transition-all placeholder:text-white/40"
            />
            <button 
              onClick={handleSpeakForMe}
              className="bg-indigo-600 text-white h-16 px-10 rounded-3xl font-black text-sm uppercase tracking-widest hover:bg-indigo-500 transition-all active:scale-95 shadow-2xl"
            >
              SPEAK
            </button>
          </div>

          <div className="flex flex-col items-center">
            <button 
              onClick={isActive ? stopVoiceSession : startVoiceSession}
              className={`w-24 h-24 rounded-full flex items-center justify-center text-4xl shadow-2xl transition-all active:scale-90 ring-8 ${isActive ? 'bg-rose-500 text-white ring-rose-500/20' : 'bg-indigo-600 text-white ring-indigo-500/20 hover:scale-105'}`}
            >
              {isActive ? '⏹️' : '🎤'}
            </button>
            <p className="mt-4 text-[10px] font-black text-white/60 uppercase tracking-[0.4em]">{isActive ? 'System Live • Voice Aware' : 'Press to Activate Companion'}</p>
          </div>
        </div>
        <canvas ref={canvasRef} className="hidden" />
      </div>

      {/* Side HUD for Metadata and Signing */}
      <div className="flex-1 flex flex-col gap-6">
        {/* Mentor View / Status HUD */}
        <div className="bg-slate-900 rounded-[3rem] p-8 shadow-2xl border border-slate-800 flex flex-col items-center justify-center text-center space-y-6">
           <h4 className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">Mentor Status Console</h4>
           {showMentorView ? (
             <div className="animate-in zoom-in duration-500 space-y-4">
                <div className="w-16 h-16 bg-emerald-500/20 rounded-2xl flex items-center justify-center text-emerald-500 mx-auto border border-emerald-500/30">👁️</div>
                <p className="text-white font-black text-lg">Marcus is active</p>
                <p className="text-slate-400 text-xs font-bold leading-relaxed px-4">Your mentor can see your surroundings and is helping you navigate to the station.</p>
             </div>
           ) : (
             <div className="opacity-40 space-y-4">
                <div className="w-16 h-16 bg-slate-800 rounded-2xl flex items-center justify-center text-slate-400 mx-auto">🕶️</div>
                <p className="text-slate-500 font-bold">Privacy Mode Active</p>
                <p className="text-slate-600 text-[10px] font-black uppercase">Click Share View to Connect</p>
             </div>
           )}
        </div>

        {/* Translation Hub (Sign Language) */}
        <div className="flex-1 bg-white dark:bg-slate-900 p-8 rounded-[3rem] shadow-2xl border border-slate-100 dark:border-slate-800 flex flex-col items-center">
