import { Message, SpeechStyle } from '../types';
import { GoogleGenAI, LiveServerMessage, Modality, Blob } from '@google/genai';
import SignLanguageAvatar from './SignLanguageAvatar';

// Rules: Implement encode and decode manually for Base64 handling.
function encode(bytes: Uint8Array): string {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

function decode(base64: string): Uint8Array {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

// Rules: Implement PCM raw decoding logic manually.
async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const AICompanion: React.FC = () => {
  const { pad } = useAccessibility();
  const [messages, setMessages] = useState<Message[]>([
    { id: '1', role: 'assistant', content: "Companion initialized. Activate 'Vision Mode' to share your view, or speak naturally for assistance.", timestamp: Date.now() }
  ]);
  const [isActive, setIsActive] = useState(false);
  const [isVisionActive, setIsVisionActive] = useState(false);
  const [userTranscription, setUserTranscription] = useState('');
  const [aiTranscription, setAiTranscription] = useState('');
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [speakForMeText, setSpeakForMeText] = useState('');
  const [showMentorView, setShowMentorView] = useState(false);

  // Audio Processing Refs
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef(new Set<AudioBufferSourceNode>());
  const sessionPromiseRef = useRef<Promise<any> | null>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null);

  // UI Refs
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const frameIntervalRef = useRef<number | null>(null);

  // Transcription Buffers
  const userTranscriptionRef = useRef('');
  const aiTranscriptionRef = useRef('');

  const cleanup = () => {
    if (frameIntervalRef.current) window.clearInterval(frameIntervalRef.current);
    if (mediaStreamRef.current) {
      mediaStreamRef.current.getTracks().forEach(track => track.stop());
      mediaStreamRef.current = null;
    }
    if (sessionPromiseRef.current) {
      sessionPromiseRef.current.then(session => session.close());
      sessionPromiseRef.current = null;
    }
    sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
    sourcesRef.current.clear();
    setIsActive(false);
    setIsSpeaking(false);
  };

  const startSession = async () => {
    try {
      cleanup();
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      // Initialize Contexts
      if (!outputAudioContextRef.current) {
        outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }
      if (outputAudioContextRef.current.state === 'suspended') {
        await outputAudioContextRef.current.resume();
      }

      inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });

      // Request User Media
      const stream = await navigator.mediaDevices.getUserMedia({ 
        audio: true, 
        video: isVisionActive ? { facingMode: 'environment', width: 640, height: 480 } : false 
      });
      mediaStreamRef.current = stream;

      if (isVisionActive && videoRef.current) {
        videoRef.current.srcObject = stream;
      }

      // Establish Live Connection
      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setIsActive(true);

            // Microphone Streaming
            const source = inputAudioContextRef.current!.createMediaStreamSource(stream);
            const processor = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);
            processor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(inputData.length);
              for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;

              const pcmBlob: Blob = {
                data: encode(new Uint8Array(int16.buffer)),
                mimeType: 'audio/pcm;rate=16000',
              };

              sessionPromise.then(session => session.sendRealtimeInput({ media: pcmBlob }));
            };
            source.connect(processor);
            processor.connect(inputAudioContextRef.current!.destination);

            // Vision Streaming
            if (isVisionActive && canvasRef.current && videoRef.current) {
              frameIntervalRef.current = window.setInterval(() => {
                if (!videoRef.current || videoRef.current.readyState < 2) return;
                const ctx = canvasRef.current!.getContext('2d');
                if (ctx) {
                  canvasRef.current!.width = videoRef.current!.videoWidth;
                  canvasRef.current!.height = videoRef.current!.videoHeight;
                  ctx.drawImage(videoRef.current!, 0, 0);
                  const base64Data = canvasRef.current!.toDataURL('image/jpeg', 0.6).split(',')[1];
                  sessionPromise.then(session => session.sendRealtimeInput({
                    media: { data: base64Data, mimeType: 'image/jpeg' }
                  }));
                }
              }, 1500);
            }
          },
          onmessage: async (message: LiveServerMessage) => {
            // Interruption handling
            if (message.serverContent?.interrupted) {
              sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
              sourcesRef.current.clear();
              nextStartTimeRef.current = 0;
              setIsSpeaking(false);
            }

            // Transcription handling
            if (message.serverContent?.inputTranscription) {
              userTranscriptionRef.current += message.serverContent.inputTranscription.text;
              setUserTranscription(userTranscriptionRef.current);
            }
            if (message.serverContent?.outputTranscription) {
              aiTranscriptionRef.current += message.serverContent.outputTranscription.text;
              setAiTranscription(aiTranscriptionRef.current);
            }

            // Audio Playback logic
            const base64Audio = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
            if (base64Audio && outputAudioContextRef.current) {
              setIsSpeaking(true);
              const ctx = outputAudioContextRef.current;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);

              const buffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = buffer;
              source.connect(ctx.destination);

              source.addEventListener('ended', () => {
                sourcesRef.current.delete(source);
                if (sourcesRef.current.size === 0) setIsSpeaking(false);
              });

              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              sourcesRef.current.add(source);
            }

            // Turn completion
            if (message.serverContent?.turnComplete) {
              if (userTranscriptionRef.current) {
                setMessages(prev => [...prev, { id: Date.now() + '-u', role: 'user', content: userTranscriptionRef.current, timestamp: Date.now() }]);
              }
              if (aiTranscriptionRef.current) {
                setMessages(prev => [...prev, { id: Date.now() + '-a', role: 'assistant', content: aiTranscriptionRef.current, timestamp: Date.now() }]);
              }
              userTranscriptionRef.current = '';
              aiTranscriptionRef.current = '';
              setUserTranscription('');
              setAiTranscription('');
            }
          },
          onclose: () => cleanup(),
          onerror: (e) => {
            console.error("Live API Error:", e);
            cleanup();
          }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } } },
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          systemInstruction: `You are Adaptia AI. Context: ${JSON.stringify(pad)}. 
          Instructions: Patient, supportive, aware of speech style: ${pad.speechStyle}. 
          Describe surroundings if vision is active. Assist in navigation. 
          If user asks you to "Speak for me", repeat their typed text verbatim in a clear voice.`
        }
      });
      sessionPromiseRef.current = sessionPromise;

    } catch (err) {
      console.error("Mic/Cam Access Denied or Session Failed:", err);
      cleanup();
    }
  };

  const handleSpeakForMe = () => {
    if (!speakForMeText || !sessionPromiseRef.current) return;
    sessionPromiseRef.current.then(session => {
      session.sendRealtimeInput({ text: `SPEAK THIS FOR ME: ${speakForMeText}` });
      setSpeakForMeText('');
    });
  };

  useEffect(() => {
    return () => cleanup();
  }, []);

  return (
    <div className="fixed inset-0 top-[88px] flex flex-col xl:flex-row bg-slate-50 dark:bg-slate-950 overflow-hidden">
      {/* Immersive Main Panel */}
      <div className="flex-[3] flex flex-col relative bg-white dark:bg-slate-900 shadow-2xl overflow-hidden m-4 rounded-[3rem] border border-slate-100 dark:border-slate-800">

        {/* Background Camera Feed */}
        {isVisionActive && (
          <div className="absolute inset-0 z-0">
            <video ref={videoRef} autoPlay playsInline muted className="w-full h-full object-cover grayscale opacity-30 blur-md" />
            <div className="absolute inset-0 bg-gradient-to-b from-transparent via-slate-950/20 to-slate-950/80"></div>
          </div>
        )}

        {/* HUD Overlay */}
        <div className="z-10 p-8 flex justify-between items-center bg-white/60 dark:bg-slate-900/60 backdrop-blur-xl border-b border-slate-100 dark:border-slate-800">
          <div className="flex items-center space-x-6">
            <div className={`w-16 h-16 rounded-2xl flex items-center justify-center text-3xl shadow-2xl transition-all ${isActive ? 'bg-rose-500 text-white animate-pulse' : 'bg-slate-100 dark:bg-slate-800 text-slate-400'}`}>
              {isActive ? '🎙️' : '🤖'}
            </div>
            <div>
              <h3 className="text-2xl font-black text-slate-900 dark:text-white">Adaptia Companion</h3>
              <p className="text-[10px] font-black text-indigo-600 dark:text-indigo-400 uppercase tracking-widest">{isActive ? 'Live • Contextual Awareness Active' : 'Standby Mode'}</p>
            </div>
          </div>

          <div className="flex items-center space-x-3">
             <button 
               onClick={() => setIsVisionActive(!isVisionActive)}
               disabled={isActive}
               className={`px-6 py-3 rounded-2xl text-[10px] font-black tracking-widest transition-all shadow-lg ${isVisionActive ? 'bg-indigo-600 text-white' : 'bg-slate-100 dark:bg-slate-800 text-slate-500'}`}
             >
               {isVisionActive ? '📷 VISION ON' : '📷 VISION OFF'}
             </button>
             {isVisionActive && (
                <button 
                  onClick={() => setShowMentorView(!showMentorView)}
                  className={`px-6 py-3 rounded-2xl text-[10px] font-black tracking-widest transition-all shadow-lg ${showMentorView ? 'bg-emerald-500 text-white' : 'bg-slate-800 text-slate-400'}`}
                >
                  {showMentorView ? 'MENTOR CONNECTED' : 'SHARE VIEW'}
                </button>
             )}
          </div>
        </div>

        {/* Scrollable Conversation */}
        <div className="z-10 flex-1 overflow-y-auto p-10 space-y-6 scrollbar-hide">
          {messages.map(msg => (
            <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-in slide-in-from-bottom-4`}>
              <div className={`max-w-[80%] p-6 rounded-[2.5rem] text-lg font-medium shadow-xl border ${
                msg.role === 'user' 
                  ? 'bg-indigo-600 text-white border-indigo-400 rounded-tr-none' 
                  : 'bg-white/90 dark:bg-slate-800/90 text-slate-800 dark:text-slate-100 border-white/20 rounded-tl-none'
              }`}>
                {msg.content}
              </div>
            </div>
          ))}
          {userTranscription && <div className="text-right text-slate-400 italic font-bold text-sm px-6">Detecting: {userTranscription}...</div>}
          {aiTranscription && (
             <div className="flex justify-start animate-in fade-in">
               <div className="max-w-[80%] p-6 rounded-[2.5rem] bg-indigo-50/80 dark:bg-indigo-900/40 text-indigo-600 dark:text-indigo-400 border border-indigo-100 italic font-bold text-lg rounded-tl-none">
                 {aiTranscription}...
               </div>
             </div>
          )}
        </div>

        {/* Interaction Bar */}
        <div className="z-10 p-10 bg-white/95 dark:bg-slate-900/95 backdrop-blur-md border-t border-slate-100 dark:border-slate-800">
          <div className="flex flex-col items-center space-y-8 max-w-4xl mx-auto">
            <div className="flex w-full space-x-4">
              <input 
                type="text" 
                placeholder="Type here and press Speak to use me as your voice..." 
                value={speakForMeText}
                onChange={(e) => setSpeakForMeText(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSpeakForMe()}
                className="flex-1 bg-slate-50 dark:bg-slate-800 px-8 py-5 rounded-[2rem] border border-slate-100 dark:border-slate-700 text-lg font-bold outline-none focus:ring-4 focus:ring-indigo-500/20"
              />
              <button 
                onClick={handleSpeakForMe}
                className="bg-indigo-600 text-white px-10 rounded-[2rem] font-black text-xs uppercase tracking-[0.2em] shadow-2xl active:scale-95"
              >
                Speak
              </button>
            </div>

            <div className="flex flex-col items-center">
              <button 
                onClick={isActive ? cleanup : startSession}
                className={`w-28 h-28 rounded-full flex items-center justify-center text-4xl shadow-2xl transition-all active:scale-90 ring-8 ${isActive ? 'bg-rose-500 text-white ring-rose-500/20' : 'bg-indigo-600 text-white ring-indigo-500/20 hover:scale-105'}`}
              >
                {isActive ? '⏹️' : '🎤'}
              </button>
              <p className="mt-6 text-[11px] font-black text-slate-400 uppercase tracking-[0.5em]">{isActive ? 'Voice Interaction Live' : 'Start DNA Session'}</p>
            </div>
          </div>
        </div>
        <canvas ref={canvasRef} className="hidden" />
      </div>

      {/* Side HUD Panel */}
      <div className="xl:w-[450px] flex flex-col p-4 space-y-4 h-full">
        {isVisionActive && (
          <div className="flex-1 bg-slate-950 rounded-[3rem] overflow-hidden shadow-2xl relative border-4 border-slate-800 min-h-[300px]">
            <video ref={videoRef} autoPlay playsInline muted className="w-full h-full object-cover" />
            <div className="absolute top-6 left-6 flex items-center space-x-3">
               <div className="bg-rose-600 px-4 py-2 rounded-full text-[10px] font-black text-white flex items-center space-x-2 shadow-2xl">
                  <span className="w-2 h-2 bg-white rounded-full animate-ping"></span>
