    localStorage.setItem('adaptia_onboarded', 'true');
    localStorage.setItem('adaptia_role', role);
  };

  const renderContent = () => {
    if (userRole !== UserRole.User && activeTab !== 'dashboard' && activeTab !== 'dna') {
      return (
        <div className="flex flex-col items-center justify-center h-full min-h-[60vh] text-center space-y-6 animate-in fade-in zoom-in duration-500">
          <div className="text-8xl">🔒</div>
          <h2 className="text-4xl font-black text-slate-950">Expert Access Restricted</h2>
          <p className="text-slate-500 max-w-lg text-lg font-medium">
            As a {userRole}, your profile is currently live in the Adaptia Marketplace. 
            Use the DNA tab to manage your credentials.
          </p>
          <button 
            onClick={() => setActiveTab('dashboard')} 
            className="bg-coral text-white px-10 py-4 rounded-2xl font-black uppercase tracking-widest shadow-xl hover:scale-105 active:scale-95 transition-all"
          >
            Back to Dashboard
          </button>
        </div>
      );
    }

    switch (activeTab) {
      case 'dashboard': return <Dashboard role={userRole!} />;
      case 'dna': return <PADForm />;
      case 'map': return <MapModule />;
      case 'companion': return <AICompanion />;
      case 'career': return <CareerHub />;
      case 'social': return <SocialHub />;
      case 'shop': return <Shop />;
      default: return <Dashboard role={userRole!} />;
    }
  };

  if (!userRole) {
    return (
      <AccessibilityProvider>
        <Onboarding onComplete={handleOnboardingComplete} />
      </AccessibilityProvider>
    );
  }

  return (
    <AccessibilityProvider>
      <div className="min-h-screen flex flex-col selection:bg-coral/20 selection:text-coral bg-peach transition-colors duration-500">
        <Navigation 
          activeTab={activeTab} 
          setActiveTab={setActiveTab} 
          onEmergency={() => setShowEmergency(true)} 
          onFeedback={() => setShowFeedback(true)}
        />

        <main className="flex-1 w-full max-w-[1920px] mx-auto px-4 sm:px-8 pt-24 pb-32 flex flex-col">
          <div className="flex-1 w-full h-full">
            {renderContent()}
          </div>
        </main>

        {showEmergency && (
          <EmergencySystem onClose={() => setShowEmergency(false)} />
        )}

        {showFeedback && (
          <FeedbackSystem onClose={() => setShowFeedback(false)} />
        )}
      </div>
    </AccessibilityProvider>
  );
};

