const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const getCareerGuidance = async (pad: PAD, interests: string): Promise<CareerPath[]> => {
  // Use gemini-3-pro-preview for complex reasoning/guidance tasks
  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: `Based on this Personal Accessibility DNA (PAD): ${JSON.stringify(pad)} and user interests: "${interests}", suggest 3 career paths. 
    Focus on abilities and adaptive growth. Return a JSON array of objects with title, compatibility (0-100), description, skills (array), and remoteFriendly (boolean).`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            compatibility: { type: Type.NUMBER },
            description: { type: Type.STRING },
            skills: { 
              type: Type.ARRAY, 
              items: { type: Type.STRING } 
            },
            remoteFriendly: { type: Type.BOOLEAN }
          },
          required: ["title", "compatibility", "description", "skills", "remoteFriendly"]
        }
      }
    }
  });

  try {
    // Access .text property directly, not as a function call
    const text = response.text || "[]";
    return JSON.parse(text);
  } catch (e) {
    console.error("Failed to parse career guidance", e);
    return [];
  }
};

export const analyzeSurroundings = async (imageData: string): Promise<string> => {
  // Correct model for image tasks: gemini-2.5-flash-image
  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [
        { inlineData: { data: imageData.split(',')[1], mimeType: 'image/jpeg' } },
        { text: "Describe the immediate surroundings for a person with disabilities. Identify obstacles, signage, and accessibility features like ramps or elevators. Keep it concise." }
      ]
    }
  });
  return response.text || "No description available.";
};

export const simplifyDocument = async (text: string): Promise<string> => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Please simplify the following complex text or form content for someone with cognitive processing needs. Use clear, direct language and bullet points if necessary: \n\n${text}`,
    config: {
      systemInstruction: "You are an accessibility expert specializing in Plain Language and cognitive support."
    }
  });
  return response.text || "Simplification failed.";
};

export const getSimulationAnalysis = async (pad: PAD, location: any): Promise<string> => {
  const response = await ai.models.generateContent({
