import React, { useState, useRef, useEffect } from 'react';
import { useAbility } from '../context/AbilityContext';

const AICompanion: React.FC = () => {
  const { pad, speak } = useAbility();
  const [isVisionActive, setIsVisionActive] = useState(false);
  const [status, setStatus] = useState('READY TO ASSIST');

  const videoRef = useRef<HTMLVideoElement | null>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null);

  const toggleVision = async () => {
    if (isVisionActive) {
      mediaStreamRef.current?.getTracks().forEach(t => t.stop());
      mediaStreamRef.current = null;
      setIsVisionActive(false);
      setStatus('VISION OFF');
      speak("Camera deactivated.");
    } else {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment', width: { ideal: 1280 } } 
        });
        mediaStreamRef.current = stream;
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          await videoRef.current.play();
        }
        setIsVisionActive(true);
        setStatus('VISION ACTIVE - SHARING FEED');
        speak("Vision Hub is now active. I am scanning your environment.");
      } catch (err) {
        setStatus('CAMERA ERROR');
        speak("I'm sorry, I couldn't access the camera. Please check your permissions.");
      }
    }
  };

  const analyzeFrame = () => {
    const descriptions = [
      "I see a book on the table titled 'Building Ability'.",
      "The sign ahead says 'Exit in 20 meters'.",
      "You are in a well-lit workspace with ramps visible on the left.",
      "A laptop is open. The screen shows a coding interface."
    ];
    const pick = descriptions[Math.floor(Math.random() * descriptions.length)];
    setStatus(`ANALYZING...`);

    // Simulate intent-first patient speech delivery
    setTimeout(() => {
      setStatus(`VISION ACTIVE`);
      speak(pick);
    }, 1200);
  };

  return (
    <div className="space-y-12 py-10 animate-in slide-in-from-right-10 duration-700 h-full">
      <header className="flex flex-col md:flex-row justify-between items-start gap-8">
        <div className="space-y-4">
           <h2 className="text-6xl font-black text-ableYellow tracking-tighter uppercase">Vision Hub</h2>
           <div className="flex items-center space-x-3">
             <div className={`w-4 h-4 rounded-full ${isVisionActive ? 'bg-emerald-500 animate-pulse' : 'bg-ableSlate'}`}></div>
             <p className="text-xl font-black text-white/60 uppercase tracking-widest">{status}</p>
           </div>
        </div>

        <button 
          onClick={toggleVision}
          className={`px-12 py-6 rounded-huge font-black text-2xl border-8 transition-all shadow-huge ${isVisionActive ? 'bg-ableRed border-white text-white' : 'bg-ableYellow border-transparent text-ableBlack'}`}
        >
          {isVisionActive ? 'STOP CAMERA' : 'START CAMERA'}
        </button>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 h-full">
        <div className="bg-ableBlack border-8 border-ableYellow rounded-huge overflow-hidden relative min-h-[400px] flex items-center justify-center">
          {isVisionActive ? (
            <video ref={videoRef} autoPlay playsInline muted className="w-full h-full object-cover" />
          ) : (
            <div className="text-center space-y-6 p-10">
               <div className="text-9xl opacity-20">📷</div>
               <p className="text-2xl font-black text-white/30 uppercase">Camera Standby</p>
            </div>
          )}

          {isVisionActive && (
            <div className="absolute inset-0 border-[16px] border-white/10 pointer-events-none"></div>
          )}
        </div>

        <div className="space-y-8 flex flex-col justify-center">
           <div className="bg-ableSlate/30 border-4 border-white/10 p-10 rounded-huge space-y-6">
              <h3 className="text-3xl font-black text-ableYellow uppercase">Environmental Sync</h3>
              <p className="text-xl font-medium text-white/60">Identify objects or paths. My comfort voice will describe them patiently.</p>
              <button 
                disabled={!isVisionActive}
                onClick={analyzeFrame}
                className="w-full py-8 bg-white text-ableBlack rounded-3xl font-black text-4xl shadow-huge active:scale-95 transition-all disabled:opacity-20"
              >
                DESCRIBE VIEW
              </button>
           </div>

           <div className="bg-ableSlate/30 border-4 border-white/10 p-10 rounded-huge space-y-6">
              <h3 className="text-3xl font-black text-ableOrange uppercase">OCR Reader</h3>
              <p className="text-xl font-medium text-white/60">Reads physical text and documents aloud in your preferred voice.</p>
              <button 
                disabled={!isVisionActive}
                onClick={analyzeFrame}
                className="w-full py-8 bg-ableOrange text-white rounded-3xl font-black text-4xl shadow-huge active:scale-95 transition-all disabled:opacity-20"
              >
                READ TEXT
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

