const CircleOfCare: React.FC = () => {
  const { pad, speak } = useAbility();
  const [activeFilter, setActiveFilter] = useState<'all' | 'home' | 'pro'>('all');

  const filteredMembers = MOCK_CIRCLE.filter(m => {
    if (activeFilter === 'home') return m.role === UserRole.HomeMember;
    if (activeFilter === 'pro') return m.role === UserRole.Mentor || m.role === UserRole.Specialist;
    return true;
  });

  const handleMemberAction = (member: CircleMember) => {
    const text = member.role === UserRole.HomeMember 
      ? `Connecting you with your ${member.relationship}, ${member.name}.` 
      : `Paging ${member.name}, your ${member.specialty} guide.`;
