    const code = Math.random().toString(36).substring(2, 8).toUpperCase();
    speak(`Invitation code generated. Share the code ${code} with a family member to sync your Ability DNA.`);
    alert(`INVITE CODE: ${code}\nShare this with a Home Member.`);
