        <div className="flex flex-wrap gap-4">
          <button 
            onClick={() => setActiveFilter('all')}
            className={`px-8 py-4 rounded-2xl font-black text-xs tracking-widest border-4 transition-all ${activeFilter === 'all' ? 'bg-ableYellow text-ableBlack border-white shadow-xl' : 'bg-white/5 border-white/10 text-white opacity-60'}`}
          >
            FULL CIRCLE
          </button>
          <button 
            onClick={() => setActiveFilter('home')}
            className={`px-8 py-4 rounded-2xl font-black text-xs tracking-widest border-4 transition-all ${activeFilter === 'home' ? 'bg-ableOrange text-white border-white shadow-xl' : 'bg-white/5 border-white/10 text-white opacity-60'}`}
          >
            HOME MEMBERS
          </button>
          <button 
            onClick={() => setActiveFilter('pro')}
            className={`px-8 py-4 rounded-2xl font-black text-xs tracking-widest border-4 transition-all ${activeFilter === 'pro' ? 'bg-ableSlate text-white border-ableYellow shadow-xl' : 'bg-white/5 border-white/10 text-white opacity-60'}`}
          >
            SPECIALISTS
          </button>
        </div>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
        {/* Invite Card */}
        <button 
          onClick={generateInviteCode}
          className="bg-ableBlack border-8 border-dashed border-white/10 p-10 rounded-huge hover:border-ableYellow transition-all flex flex-col items-center justify-center text-center space-y-4 group"
        >
          <div className="text-6xl group-hover:scale-110 transition-transform">➕</div>
          <h3 className="text-2xl font-black text-white">ADD HOME MEMBER</h3>
          <p className="text-sm font-bold text-white/40 uppercase tracking-widest">Link family or friends</p>
        </button>

        {filteredMembers.map(member => (
          <div 
            key={member.id} 
            className={`bg-ableBlack border-8 p-10 rounded-huge shadow-2xl space-y-6 transition-all relative overflow-hidden ${member.role === UserRole.HomeMember ? 'border-ableOrange' : 'border-ableYellow'}`}
          >
            {member.isOnline && (
              <div className="absolute top-4 right-4 flex items-center gap-2">
                <div className="w-3 h-3 bg-emerald-500 rounded-full animate-pulse"></div>
                <span className="text-[10px] font-black text-emerald-500 uppercase tracking-tighter">Live</span>
              </div>
            )}

            <div className="flex items-center gap-6">
              <div className="w-24 h-24 bg-white/5 rounded-3xl flex items-center justify-center text-5xl shadow-inner">
                {member.avatar}
              </div>
