import React, { useState } from 'react';
import { AbilityProvider } from './context/AbilityContext';
import Navigation from './components/Navigation';
import Dashboard from './components/Dashboard';
import PADSettings from './components/PADForm'; 
import VisionAI from './components/AICompanion'; 
import CommHub from './components/SocialHub'; 
import CareerHub from './components/CareerHub';
import CircleOfCare from './components/CircleOfCare';
import EmergencySystem from './components/EmergencySystem';
import ReportIssue from './components/ReportIssue';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [showEmergency, setShowEmergency] = useState(false);
  const [showReport, setShowReport] = useState(false);

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard': return <Dashboard />;
      case 'vision': return <VisionAI />;
      case 'voice': return <CommHub />;
      case 'career': return <CareerHub />;
      case 'circle': return <CircleOfCare />;
      case 'dna': return <PADSettings />;
      default: return <Dashboard />;
    }
  };

  return (
    <AbilityProvider>
      <div className="min-h-screen flex flex-col bg-ableBlack transition-colors duration-500">
        <Navigation 
          activeTab={activeTab} 
          setActiveTab={setActiveTab} 
          onEmergency={() => setShowEmergency(true)} 
        />

        <header className="pt-24 px-6 max-w-5xl mx-auto w-full flex justify-end">
           <button 
             onClick={() => setShowReport(true)}
             className="px-6 py-3 border-4 border-ableYellow text-ableYellow font-black text-xs rounded-xl hover:bg-ableYellow hover:text-ableBlack transition-all"
           >
             REPORT BARRIER
           </button>
        </header>

        <main className="flex-1 w-full max-w-5xl mx-auto px-6 pb-40">
           {renderContent()}
        </main>

        {showEmergency && <EmergencySystem onClose={() => setShowEmergency(false)} />}
        {showReport && <ReportIssue onClose={() => setShowReport(false)} />}
      </div>
    </AbilityProvider>
  );
};

export default App;

export enum VisualAbility {
  Standard = 'standard',
  Blurry = 'blurry',
  LowContrast = 'low-contrast',
  PartialBlindness = 'partial-blindness'
}

export enum SpeechStyle {
  Standard = 'standard',
  StutterAware = 'stutter-aware',
  FrequentPauses = 'frequent-pauses',
  NonVerbal = 'non-verbal'
}

export enum VoicePreference {
  CalmFemale = 'calm-female',
  CalmMale = 'calm-male'
}

export enum UserRole {
  User = 'user',
  HomeMember = 'home-member', // Family/Friend
  Mentor = 'mentor',         // Professional Guide
  Specialist = 'specialist'  // Professional Medical
}

export enum VisionNeed {
  Standard = 'standard',
  LowVision = 'low-vision',
  Blind = 'blind'
}

export enum CognitiveMode {
  Standard = 'standard',
  Simplified = 'simplified',
  HighFocus = 'high-focus'
}

export enum HearingNeed {
  Standard = 'standard',
  HardOfHearing = 'hard-of-hearing',
  Deaf = 'deaf'
}

export enum FatigueTolerance {
  Low = 'low',
  Medium = 'medium',
  High = 'high'
}

export interface PAD {
  visual: VisualAbility;
  speech: SpeechStyle;
  voicePreference: VoicePreference;
  highContrast: boolean;
  largeText: boolean;
  primaryLanguage: string;
  vision?: VisionNeed;
  cognitive?: CognitiveMode;
  mobility?: string;
  hearing?: HearingNeed;
  signLanguagePreferred?: boolean;
}

export interface CircleMember {
  id: string;
  name: string;
  role: UserRole | string;
  avatar: string;
  specialty?: string;
  isOnline: boolean;
  relationship?: string; // e.g., "Sister", "Best Friend"
  hourlyRate?: number;    // Only for Mentors/Specialists
  needsMet: string[];    // Added for Shop marketplace features
}

export interface CareerPath {
  title: string;
  compatibility: number;
  description: string;
  skills: string[];
  visualAlternativeNeeded: boolean;
  speechSupportLevel: 'low' | 'medium' | 'high';
}

export interface LocationSimulation {
  id: string;
  name: string;
  type: string;
  baseAccessibilityScore: number;
  accessibilityFeatures: string[];
  potentialHazards: string[];
}

export interface Message {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  timestamp: number;
}

