import React, { useState, useEffect } from 'react';
import { useAbility } from '../context/AbilityContext';
import { HearingNeed } from '../types';

interface SignLanguageAvatarProps {
  message?: string;
  active?: boolean;
}

const SignLanguageAvatar: React.FC<SignLanguageAvatarProps> = ({ message, active = false }) => {
  const { pad } = useAbility();
  const [isVisible, setIsVisible] = useState(false);
  const [currentGesture, setCurrentGesture] = useState(0);

  useEffect(() => {
    if (pad.signLanguagePreferred || pad.hearing === HearingNeed.Deaf) {
      setIsVisible(true);
    }
  }, [pad]);

  // Cycle gestures when active to simulate signing
  useEffect(() => {
    if (!active) return;
    const interval = setInterval(() => {
      setCurrentGesture(prev => (prev + 1) % 4);
    }, 400);
    return () => clearInterval(interval);
  }, [active]);

  if (!isVisible && !active) return null;

  const getGesturePath = () => {
    switch (currentGesture) {
      case 0: return "M30 60 Q50 40 70 60 M40 70 Q50 85 60 70"; // Wave-like
      case 1: return "M20 50 Q50 70 80 50 M45 40 Q55 40 50 60"; // Pointing
      case 2: return "M30 40 Q50 20 70 40 M50 50 L50 90"; // High gestures
      default: return "M25 65 Q50 75 75 65 M40 50 Q50 40 60 50"; // Close signing
    }
  };

  return (
    <div className={`relative transition-all duration-500 transform ${active ? 'scale-110' : 'scale-100'}`}>
      <div className="bg-white dark:bg-slate-950 rounded-[2.5rem] shadow-2xl border-4 border-indigo-500/40 overflow-hidden w-full aspect-[3/4] flex flex-col relative group">
        <div className="absolute top-4 right-4 z-10">
          <button 
            onClick={() => setIsVisible(false)}
            className="w-8 h-8 bg-slate-100 dark:bg-slate-800 rounded-xl flex items-center justify-center text-xs opacity-0 group-hover:opacity-100 transition-all hover:bg-rose-100 hover:text-rose-600"
          >
            ✕
          </button>
        </div>

        <div className="flex-1 bg-gradient-to-b from-indigo-500/10 to-transparent dark:from-indigo-900/20 flex items-center justify-center overflow-hidden relative">
          <div className={`absolute inset-0 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-from)_0%,_transparent_70%)] from-indigo-500/10 transition-opacity ${active ? 'opacity-100' : 'opacity-0'}`}></div>

          <svg viewBox="0 0 100 120" className="w-full h-full p-4 transition-transform duration-300">
            {/* Head */}
            <circle cx="50" cy="30" r="18" fill="currentColor" className="text-indigo-600 dark:text-indigo-400" />

            {/* Body */}
            <path d="M50 48 Q50 110 50 110" stroke="currentColor" strokeWidth="12" strokeLinecap="round" className="text-indigo-600/80 dark:text-indigo-400/80" />

            {/* Arms/Hands that animate */}
            <path 
              d={active ? getGesturePath() : "M30 65 Q50 75 70 65"} 
              stroke="currentColor" 
              strokeWidth="6" 
              fill="none" 
              strokeLinecap="round" 
              className={`text-indigo-500 dark:text-indigo-300 transition-all duration-300 ${active ? 'animate-pulse' : ''}`}
            />

            {/* Decorative Pulse Ring */}
            {active && (
               <circle cx="50" cy="30" r="25" stroke="currentColor" strokeWidth="0.5" fill="none" className="text-indigo-500/30 animate-ping" />
            )}
          </svg>

          <div className="absolute bottom-4 left-0 right-0 text-center">
            <span className={`text-[9px] font-black uppercase tracking-[0.2em] px-4 py-1 rounded-full shadow-lg ${active ? 'bg-indigo-600 text-white' : 'bg-slate-200 dark:bg-slate-800 text-slate-500'}`}>
              {active ? 'Signing Live' : 'Avatar Standby'}
            </span>
          </div>
        </div>

        <div className="h-24 bg-slate-50 dark:bg-slate-900/80 p-4 flex flex-col items-center justify-center text-center border-t border-slate-100 dark:border-slate-800">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Translation Stream</p>
          <p className="text-xs leading-tight text-slate-700 dark:text-slate-300 font-bold overflow-hidden text-ellipsis line-clamp-2">
            {message ? message : "Awaiting communication input..."}
          </p>
        </div>
      </div>
    </div>
  );
};

