import React, { useState, useEffect, useCallback } from 'react';
import { useAbility } from '../context/AbilityContext';
import { GoogleGenAI } from '@google/genai';

const CommHub: React.FC = () => {
  const { pad, speak } = useAbility();
  const [speakText, setSpeakText] = useState('');
  const [isListening, setIsListening] = useState(false);
  const [transcript, setTranscript] = useState('');
  const [ifiStatus, setIfiStatus] = useState('Standby');
  const [aiResponse, setAiResponse] = useState('');

  const handleSpeak = () => {
    if (!speakText) return;
    speak(speakText);
    setSpeakText('');
  };

  const processWithAI = async (userText: string) => {
    setIfiStatus('AI Analyzing...');
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `The user says: "${userText}". 
        Context: User has ${pad.visual} vision and ${pad.speech} speech style. 
        Provide a short, empathetic, and helpful conversational response (max 2 sentences) that respects their pace.`,
        config: {
          systemInstruction: "You are ABLE, a patient AI companion for people with disabilities. Speak clearly, kindly, and focus on the user's intent."
        }
      });

      const textResponse = response.text || "I understand. How can I help further?";
      setAiResponse(textResponse);
      setIfiStatus('AI Ready');
      speak(textResponse);
    } catch (error) {
      console.error("AI Error:", error);
      setIfiStatus('Error');
      speak("I encountered a small hiccup. Could you repeat that?");
    }
  };

  const startListening = useCallback(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      alert("Voice input not supported in this browser.");
      return;
    }

    const recognition = new SpeechRecognition();
    recognition.lang = 'en-US';
    recognition.interimResults = true;
    recognition.continuous = false;

    recognition.onstart = () => {
      setIsListening(true);
      setIfiStatus('IFI™ Active Listening...');
      setTranscript('');
      setAiResponse('');
    };

    recognition.onresult = (event: any) => {
      let finalTranscript = '';
      for (let i = event.resultIndex; i < event.results.length; ++i) {
        if (event.results[i].isFinal) {
          finalTranscript += event.results[i][0].transcript;
        }
      }
      if (finalTranscript) {
        setTranscript(finalTranscript);
      }
    };

    recognition.onerror = () => {
      setIsListening(false);
      setIfiStatus('Retry Needed');
    };

    recognition.onend = () => {
      setIsListening(false);
      if (transcript) {
        processWithAI(transcript);
      } else {
        setIfiStatus('No Input Detected');
      }
    };

    recognition.start();
  }, [transcript, pad]);

  const soundboard = [
    { label: 'YES', text: "Yes, that's correct.", color: 'bg-emerald-500' },
    { label: 'NO', text: "No, thank you.", color: 'bg-ableRed' },
    { label: 'WAIT', text: "Please wait, I am finishing my thought.", color: 'bg-ableOrange' },
    { label: 'THANKS', text: "Thank you for your patience.", color: 'bg-ableYellow text-ableBlack' }
  ];

  return (
    <div className="space-y-12 py-10 animate-in slide-in-from-left-10 duration-700">
      <header className="space-y-4">
        <h2 className="text-6xl font-black text-ableYellow tracking-tighter">VOICE HUB.</h2>
        <p className="text-2xl font-bold text-white/60">Real conversation, zero pressure. IFI™ AI analyzes your intent and answers in your comfort voice.</p>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
        {/* Speak for Me */}
        <section className="bg-ableBlack border-8 border-ableYellow p-12 rounded-huge shadow-2xl space-y-10">
          <div className="space-y-2">
            <h3 className="text-4xl font-black text-ableYellow uppercase">Speak for Me</h3>
            <p className="text-xl font-medium opacity-60">Instant communication shortcuts.</p>
          </div>

          <div className="grid grid-cols-2 gap-4">
            {soundboard.map(btn => (
              <button 
                key={btn.label}
                onClick={() => speak(btn.text)}
                className={`${btn.color} py-10 rounded-3xl font-black text-3xl shadow-xl active:scale-95 transition-all text-white border-4 border-white/20`}
              >
                {btn.label}
              </button>
            ))}
          </div>

          <div className="pt-6 space-y-4">
            <input 
              type="text"
              value={speakText}
              onChange={(e) => setSpeakText(e.target.value)}
              placeholder="TYPE CUSTOM INTENT..."
              className="w-full bg-white/5 border-4 border-white/20 rounded-huge px-8 py-6 text-2xl font-black text-white outline-none focus:border-ableYellow"
            />
            <button 
              onClick={handleSpeak}
              className="w-full py-8 bg-white text-ableBlack rounded-huge font-black text-3xl shadow-huge active:scale-95 transition-all"
            >
              SPEAK AS ME
            </button>
          </div>
        </section>

        {/* AI CONVERSATION HUB */}
        <section className="bg-ableBlack border-8 border-ableOrange p-12 rounded-huge shadow-2xl flex flex-col justify-between space-y-10">
           <div className="flex justify-between items-start">
            <div className="space-y-2">
              <h3 className="text-4xl font-black text-ableOrange">AI CHAT</h3>
              <p className="text-xl font-medium opacity-60">Ask me anything, I'm listening.</p>
            </div>
            <div className="px-4 py-2 bg-ableOrange/20 border border-ableOrange/40 rounded-xl text-[10px] font-black text-ableOrange tracking-widest">
              {ifiStatus}
            </div>
          </div>

          <div className="flex-1 bg-white/5 border-4 border-white/10 rounded-3xl p-10 flex flex-col justify-center space-y-6">
            <div className="space-y-2">
              <p className="text-xs font-black text-white/20 uppercase tracking-widest">You said:</p>
              <p className="text-3xl font-black text-white leading-tight">
                {transcript || (isListening ? 'Listening...' : 'Wait for prompt...')}
              </p>
            </div>

            {aiResponse && (
              <div className="space-y-2 pt-6 border-t border-white/10">
                <p className="text-xs font-black text-ableOrange uppercase tracking-widest">ABLE responds:</p>
                <p className="text-2xl font-bold text-white/80 leading-snug animate-in fade-in slide-in-from-left-2">
                  {aiResponse}
                </p>
              </div>
            )}
          </div>

          <div className="flex flex-col items-center gap-6">
            <button 
              onClick={startListening}
              disabled={isListening}
              className={`w-32 h-32 rounded-full flex items-center justify-center text-6xl shadow-huge transition-all active:scale-90 ${isListening ? 'bg-ableRed animate-pulse shadow-ableRed/40' : 'bg-ableOrange shadow-ableOrange/40 hover:scale-105'}`}
            >
              {isListening ? '🔴' : '🎙️'}
            </button>
            <p className="text-xs font-black uppercase tracking-[0.4em] text-ableOrange">
              {isListening ? 'SPEAK NOW' : 'TAP TO CHAT WITH AI'}
            </p>
          </div>
        </section>
      </div>
    </div>
  );
};

