      [ColorPalette.Blue]: '#3B82F6'
    };

    const activeColor = paletteMap[pad.colorPalette];
    root.style.setProperty('--able-primary', activeColor);

    if (isHighContrast) {
      root.classList.add('dark');
    } else {
      root.classList.remove('dark');
    }
  }, [pad, isHighContrast]);

  const uiIntensity = pad.cognitive === CognitiveMode.HighFocus ? 'low-stim' : 'standard';

  return (
    <AbilityContext.Provider value={{ pad, updatePAD, isHighContrast, toggleHighContrast, uiIntensity, speak }}>
      <div className={`min-h-screen ${isHighContrast ? 'bg-ableBlack text-white' : 'bg-white text-ableBlack'}`}>
        <style>{`
          :root { --able-primary: #FDE047; }
          .text-ableYellow { color: var(--able-primary) !important; }
          .bg-ableYellow { background-color: var(--able-primary) !important; }
          .border-ableYellow { border-color: var(--able-primary) !important; }
          .decoration-ableYellow { text-decoration-color: var(--able-primary) !important; }
        `}</style>
        {children}
      </div>
    </AbilityContext.Provider>
  );
};

export const useAbility = () => {
  const context = useContext(AbilityContext);
  if (!context) throw new Error('useAbility must be used within AbilityProvider');
  return context;
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { useAbility } from '../context/AbilityContext';
import { GoogleGenAI } from '@google/genai';

const CommHub: React.FC = () => {
  const { pad, speak } = useAbility();
  const [speakText, setSpeakText] = useState('');
  const [isListening, setIsListening] = useState(false);
  const [transcript, setTranscript] = useState('');
  const [ifiStatus, setIfiStatus] = useState('Standby');
  const [aiResponse, setAiResponse] = useState('');
  const recognitionRef = useRef<any>(null);

  const handleSpeak = () => {
    if (!speakText) return;
    speak(speakText);
    setSpeakText('');
  };

  const processWithAI = async (userText: string) => {
    if (!userText.trim()) return;

    setIfiStatus('Analyzing Intent...');
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `User says: "${userText}". 
        Context: The user has ${pad.visual} vision and ${pad.speech} speech style. 
        Provide a very short, helpful response (max 20 words). Be humanoid and supportive.`,
        config: {
          systemInstruction: "You are ABLE, an adaptive AI assistant. You help people with disabilities navigate the world. Speak with patience and clear intent."
        }
      });

      const textResponse = response.text || "I'm here to support you. Could you tell me more?";
      setAiResponse(textResponse);
      setIfiStatus('AI Ready');
      speak(textResponse);
    } catch (error) {
      console.error("AI Error:", error);
      setIfiStatus('Sync Error');
      speak("I lost connection for a moment. Please tap and try again.");
    }
  };

  const startListening = useCallback(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      alert("Voice input not supported in this browser.");
      return;
    }

    if (recognitionRef.current) {
      recognitionRef.current.stop();
    }

    const recognition = new SpeechRecognition();
    recognition.lang = 'en-US';
    recognition.interimResults = true;
    recognition.continuous = false;
    recognitionRef.current = recognition;

    recognition.onstart = () => {
      setIsListening(true);
      setIfiStatus('Listening...');
      setTranscript('');
      setAiResponse('');
    };

    recognition.onresult = (event: any) => {
      let currentTranscript = '';
      for (let i = event.resultIndex; i < event.results.length; ++i) {
        currentTranscript += event.results[i][0].transcript;
      }
      setTranscript(currentTranscript);
    };

    recognition.onerror = (event: any) => {
      console.error("Speech Error:", event.error);
      setIsListening(false);
      setIfiStatus('Error: ' + event.error);
    };

    recognition.onend = () => {
      setIsListening(false);
      // Wait a tiny bit to ensure state transcript is updated from the last 'onresult'
      setTimeout(() => {
        setIfiStatus('Processing...');
      }, 100);
    };

    recognition.start();
  }, []);

  // Use an effect to trigger AI processing once listening stops and we have a transcript
  useEffect(() => {
    if (!isListening && transcript.trim() && ifiStatus === 'Processing...') {
      processWithAI(transcript);
    }
  }, [isListening, transcript, ifiStatus]);

  const soundboard = [
    { label: 'YES', text: "Yes, that's correct.", color: 'bg-emerald-500' },
    { label: 'NO', text: "No, thank you.", color: 'bg-ableRed' },
    { label: 'WAIT', text: "Please wait, I am finishing my thought.", color: 'bg-ableOrange' },
    { label: 'THANKS', text: "Thank you for your patience.", color: 'bg-ableYellow text-ableBlack' }
  ];

  return (
    <div className="space-y-12 py-10 animate-in slide-in-from-left-10 duration-700">
      <header className="space-y-4">
        <h2 className="text-6xl font-black text-ableYellow tracking-tighter">VOICE HUB.</h2>
        <p className="text-2xl font-bold text-white/60">Real conversation, humanoid pace. IFI™ AI hears your intent and responds instantly.</p>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
        <section className="bg-ableBlack border-8 border-ableYellow p-12 rounded-huge shadow-2xl space-y-10">
          <div className="space-y-2">
            <h3 className="text-4xl font-black text-ableYellow uppercase">Speak for Me</h3>
            <p className="text-xl font-medium opacity-60">Shortcuts for immediate communication.</p>
          </div>

          <div className="grid grid-cols-2 gap-4">
            {soundboard.map(btn => (
              <button 
                key={btn.label}
                onClick={() => speak(btn.text)}
                className={`${btn.color} py-10 rounded-3xl font-black text-3xl shadow-xl active:scale-95 transition-all text-white border-4 border-white/20 hover:brightness-110`}
              >
                {btn.label}
              </button>
            ))}
          </div>

          <div className="pt-6 space-y-4">
            <input 
              type="text"
              value={speakText}
              onChange={(e) => setSpeakText(e.target.value)}
              placeholder="TYPE YOUR MESSAGE..."
              className="w-full bg-white/5 border-4 border-white/20 rounded-huge px-8 py-6 text-2xl font-black text-white outline-none focus:border-ableYellow transition-all"
            />
            <button 
              onClick={handleSpeak}
              className="w-full py-8 bg-white text-ableBlack rounded-huge font-black text-3xl shadow-huge active:scale-95 transition-all hover:bg-ableYellow"
            >
              SPEAK AS ME
            </button>
          </div>
        </section>

        <section className="bg-ableBlack border-8 border-ableOrange p-12 rounded-huge shadow-2xl flex flex-col justify-between space-y-10">
           <div className="flex justify-between items-start">
            <div className="space-y-2">
              <h3 className="text-4xl font-black text-ableOrange">AI VOICE CHAT</h3>
              <p className="text-xl font-medium opacity-60">Patience integrated. Talk to me.</p>
            </div>
            <div className={`px-4 py-2 border-2 rounded-xl text-[10px] font-black tracking-widest transition-all ${isListening ? 'bg-ableRed border-white text-white animate-pulse' : 'bg-ableOrange/10 border-ableOrange/40 text-ableOrange'}`}>
              {ifiStatus.toUpperCase()}
            </div>
          </div>

          <div className="flex-1 bg-white/5 border-4 border-white/10 rounded-3xl p-10 flex flex-col justify-center space-y-8 min-h-[300px]">
            <div className="space-y-3">
              <p className="text-xs font-black text-white/30 uppercase tracking-widest">User Intent:</p>
              <p className={`text-3xl font-black leading-tight transition-opacity ${transcript ? 'text-white' : 'text-white/10 italic'}`}>
                {transcript || (isListening ? 'Listening...' : 'Tap microphone to start...')}
              </p>
            </div>

            {aiResponse && (
              <div className="space-y-3 pt-8 border-t-4 border-white/5 animate-in fade-in slide-in-from-bottom-4">
                <p className="text-xs font-black text-ableOrange uppercase tracking-widest">ABLE Assistant:</p>
                <p className="text-2xl font-bold text-white/90 leading-snug">
                  {aiResponse}
                </p>
              </div>
            )}
          </div>

          <div className="flex flex-col items-center gap-6">
            <button 
              onClick={startListening}
              disabled={isListening}
              className={`w-36 h-36 rounded-full flex items-center justify-center text-7xl shadow-huge transition-all active:scale-90 ${isListening ? 'bg-ableRed animate-ping scale-110 shadow-ableRed/50' : 'bg-ableOrange shadow-ableOrange/50 hover:scale-110'}`}
              aria-label="Start Voice Chat"
            >
              {isListening ? '🎙️' : '🎙️'}
            </button>
            <p className="text-xs font-black uppercase tracking-[0.5em] text-ableOrange opacity-60">
              {isListening ? 'RECORDING' : 'TAP TO BEGIN CHAT'}
            </p>
          </div>
        </section>
      </div>
    </div>
  );
};

export default CommHub;

import React, { useState, useRef, useEffect } from 'react';
import { useAbility } from '../context/AbilityContext';
import SignLanguageAvatar from './SignLanguageAvatar';
import { GoogleGenAI } from '@google/genai';

const AICompanion: React.FC = () => {
  const { pad, speak } = useAbility();
  const [isVisionActive, setIsVisionActive] = useState(false);
  const [status, setStatus] = useState('READY TO ASSIST');
  const [chatInput, setChatInput] = useState('');
  const [lastAiMessage, setLastAiMessage] = useState('');
  const [isThinking, setIsThinking] = useState(false);

  const videoRef = useRef<HTMLVideoElement | null>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null);

  const toggleVision = async () => {
    if (isVisionActive) {
      mediaStreamRef.current?.getTracks().forEach(t => t.stop());
      mediaStreamRef.current = null;
      setIsVisionActive(false);
      setStatus('VISION OFF');
      speak("Camera deactivated.");
    } else {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment', width: { ideal: 1280 } } 
        });
        mediaStreamRef.current = stream;
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          await videoRef.current.play();
        }
        setIsVisionActive(true);
        setStatus('VISION ACTIVE');
        speak("Vision Hub is active. Describe what you want me to look for.");
      } catch (err) {
        setStatus('CAMERA ERROR');
        speak("I couldn't access the camera. Check your permissions.");
      }
    }
  };

  const handleTextChat = async () => {
    if (!chatInput.trim()) return;
    setIsThinking(true);
    const userMsg = chatInput;
    setChatInput('');

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `User message: "${userMsg}". Context: User is utilizing the Vision Hub. Provide a concise, humanoid help response.`,
      });
      const resText = response.text || "I'm processing that for you.";
      setLastAiMessage(resText);
      speak(resText);
    } catch (e) {
      setLastAiMessage("I had trouble reaching my thoughts. Try again?");
    } finally {
      setIsThinking(false);
    }
  };

  const analyzeFrame = async (action: 'describe' | 'read') => {
    if (!isVisionActive) return;
    setStatus('SCANNING...');

    // In a real implementation, we'd capture a frame from the videoRef
    // For this prototype, we use the geminiService-like simulated analysis
    const descriptions = action === 'describe' ? [
      "I see a clear path ahead with a high-contrast guide on the floor.",
      "There is a door labeled 104 to your right.",
      "A laptop is open on the desk."
    ] : [
      "The text says: Caution, wet floor.",
      "The menu reads: Special of the day, Pasta Carbonara.",
      "The label identifies this as your regular medication."
    ];

    const pick = descriptions[Math.floor(Math.random() * descriptions.length)];

    setTimeout(() => {
      setStatus('ACTIVE');
      setLastAiMessage(pick);
      speak(pick);
    }, 1500);
  };

  return (
    <div className="space-y-12 py-10 animate-in slide-in-from-right-10 duration-700">
      <header className="flex flex-col md:flex-row justify-between items-start gap-8">
        <div className="space-y-4">
           <h2 className="text-6xl font-black text-ableYellow tracking-tighter uppercase">Vision Companion</h2>
           <div className="flex items-center space-x-3">
             <div className={`w-4 h-4 rounded-full ${isVisionActive ? 'bg-emerald-500 animate-pulse' : 'bg-ableSlate'}`}></div>
             <p className="text-xl font-black text-white/60 uppercase tracking-widest">{status}</p>
           </div>
        </div>

        <button 
          onClick={toggleVision}
          className={`px-12 py-6 rounded-huge font-black text-2xl border-8 transition-all shadow-huge ${isVisionActive ? 'bg-ableRed border-white text-white' : 'bg-ableYellow border-transparent text-ableBlack'}`}
        >
          {isVisionActive ? 'STOP CAMERA' : 'START CAMERA'}
        </button>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
        {/* Camera Feed */}
        <div className="lg:col-span-7 bg-ableBlack border-8 border-ableYellow rounded-huge overflow-hidden relative min-h-[500px] flex items-center justify-center shadow-2xl">
          {isVisionActive ? (
            <video ref={videoRef} autoPlay playsInline muted className="w-full h-full object-cover" />
          ) : (
            <div className="text-center space-y-6 p-10">
               <div className="text-9xl opacity-10">📷</div>
               <p className="text-2xl font-black text-white/20 uppercase tracking-widest">Camera Off</p>
            </div>
          )}

          <div className="absolute bottom-8 right-8 w-48 shadow-2xl">
             <SignLanguageAvatar message={lastAiMessage} active={!!lastAiMessage} />
          </div>
        </div>

        {/* AI Interaction Controls */}
        <div className="lg:col-span-5 space-y-8 flex flex-col justify-between">
           <div className="bg-ableSlate/30 border-4 border-white/10 p-10 rounded-huge space-y-8 shadow-xl">
              <h3 className="text-3xl font-black text-ableYellow uppercase">Direct Command</h3>
              <div className="space-y-4">
                <textarea 
                  value={chatInput}
                  onChange={(e) => setChatInput(e.target.value)}
                  placeholder="ASK ME ANYTHING..."
                  className="w-full bg-white/5 border-4 border-white/10 rounded-3xl p-6 text-xl font-bold text-white outline-none focus:border-ableYellow transition-all resize-none min-h-[120px]"
                />
                <button 
                  onClick={handleTextChat}
                  disabled={isThinking || !chatInput.trim()}
                  className="w-full py-6 bg-white text-ableBlack rounded-huge font-black text-2xl shadow-huge active:scale-95 transition-all disabled:opacity-30"
                >
                  {isThinking ? 'THINKING...' : 'SEND TO AI'}
                </button>
              </div>
           </div>

           <div className="grid grid-cols-2 gap-4">
              <button 
                disabled={!isVisionActive}
                onClick={() => analyzeFrame('describe')}
                className="py-10 bg-ableYellow text-ableBlack rounded-[2.5rem] font-black text-2xl shadow-huge active:scale-95 transition-all disabled:opacity-20 flex flex-col items-center gap-4"
              >
                <span className="text-5xl">🧭</span>
                DESCRIBE
              </button>
              <button 
                disabled={!isVisionActive}
                onClick={() => analyzeFrame('read')}
                className="py-10 bg-ableOrange text-white rounded-[2.5rem] font-black text-2xl shadow-huge active:scale-95 transition-all disabled:opacity-20 flex flex-col items-center gap-4"
              >
                <span className="text-5xl">📖</span>
                READ TEXT
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

export default AICompanion;

