import React, { useState, useRef, useEffect } from 'react';
import { useAbility } from '../context/AbilityContext';
import SignLanguageAvatar from './SignLanguageAvatar';
import { GoogleGenAI } from '@google/genai';

const AICompanion: React.FC = () => {
  const { pad, speak } = useAbility();
  const [isVisionActive, setIsVisionActive] = useState(false);
  const [status, setStatus] = useState('READY TO ASSIST');
  const [chatInput, setChatInput] = useState('');
  const [lastAiMessage, setLastAiMessage] = useState('');
  const [isThinking, setIsThinking] = useState(false);

  const videoRef = useRef<HTMLVideoElement | null>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null);

  // Stop camera when component unmounts
  useEffect(() => {
    return () => {
      mediaStreamRef.current?.getTracks().forEach(t => t.stop());
    };
  }, []);

  const toggleVision = async () => {
    if (isVisionActive) {
      mediaStreamRef.current?.getTracks().forEach(t => t.stop());
      mediaStreamRef.current = null;
      setIsVisionActive(false);
      setStatus('VISION OFF');
      speak("Camera deactivated.");
    } else {
      try {
        setStatus('INITIALIZING...');
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { 
            facingMode: 'environment', 
            width: { ideal: 1280 },
            height: { ideal: 720 }
          } 
        });
        mediaStreamRef.current = stream;

        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          // Ensure playback starts
          videoRef.current.onloadedmetadata = () => {
            videoRef.current?.play().catch(e => console.error("Play error:", e));
          };
        }

        setIsVisionActive(true);
        setStatus('VISION ACTIVE');
        speak("Vision Hub is active. I am looking through your camera now.");
      } catch (err) {
        console.error("Camera Access Error:", err);
        setStatus('CAMERA ERROR');
        speak("I couldn't access the camera. Please check permissions.");
      }
    }
  };

  const handleTextChat = async () => {
    if (!chatInput.trim()) return;
    setIsThinking(true);
    const userMsg = chatInput;
    setChatInput('');

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `User message: "${userMsg}". Context: User is utilizing the Vision Hub. Give a clear, helpful response.`,
        config: {
          systemInstruction: "You are ABLE, an accessibility companion. Respond with empathy and focus on helping the user navigate or understand their environment."
        }
      });
      const resText = response.text || "I'm processing that for you.";
      setLastAiMessage(resText);
      speak(resText);
    } catch (e) {
      setLastAiMessage("I had trouble reaching my thoughts. Try again?");
    } finally {
      setIsThinking(false);
    }
  };

  const analyzeFrame = async (action: 'describe' | 'read') => {
    if (!isVisionActive) return;
    setStatus('SCANNING...');

    // Simulate smart scanning
    const descriptions = action === 'describe' ? [
      "I see a clear path ahead. There's a slight ramp on the left.",
      "A table is directly in front of you with some objects on it.",
      "The hallway is open and well-lit."
    ] : [
      "I detect a sign that says: EMERGENCY EXIT.",
      "The text reads: PUSH TO OPEN.",
      "The label identifies this as your vitamins."
    ];

    const pick = descriptions[Math.floor(Math.random() * descriptions.length)];

    setTimeout(() => {
      setStatus('ACTIVE');
      setLastAiMessage(pick);
      speak(pick);
    }, 1200);
  };

  return (
    <div className="space-y-12 py-10 animate-in slide-in-from-right-10 duration-700 min-h-full">
      <header className="flex flex-col md:flex-row justify-between items-start gap-8">
        <div className="space-y-4">
           <h2 className="text-6xl font-black text-ableYellow tracking-tighter uppercase">Vision Hub</h2>
           <div className="flex items-center space-x-3">
             <div className={`w-4 h-4 rounded-full ${isVisionActive ? 'bg-emerald-500 animate-pulse' : 'bg-white/20'}`}></div>
             <p className="text-xl font-black text-white/60 uppercase tracking-widest">{status}</p>
           </div>
        </div>

        <button 
          onClick={toggleVision}
          className={`px-12 py-6 rounded-huge font-black text-2xl border-8 transition-all shadow-huge active:scale-95 ${isVisionActive ? 'bg-ableRed border-white text-white' : 'bg-ableYellow border-transparent text-ableBlack'}`}
        >
          {isVisionActive ? 'STOP CAMERA' : 'START CAMERA'}
        </button>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
        {/* Camera Feed Container */}
        <div className="lg:col-span-7 bg-black border-8 border-ableYellow rounded-huge overflow-hidden relative min-h-[450px] lg:min-h-[600px] flex items-center justify-center shadow-2xl group">
          {isVisionActive ? (
            <video 
              ref={videoRef} 
              autoPlay 
              playsInline 
              muted 
              className="w-full h-full object-cover scale-x-[-1]" // Mirrored for natural feel
            />
          ) : (
            <div className="text-center space-y-6 p-10">
               <div className="text-9xl opacity-20">👁️</div>
               <p className="text-2xl font-black text-white/20 uppercase tracking-widest italic">Camera stream paused</p>
            </div>
          )}

          {/* Sign Language Overlay */}
          <div className="absolute bottom-8 right-8 w-40 md:w-56 shadow-2xl transition-all group-hover:scale-105">
             <SignLanguageAvatar message={lastAiMessage} active={!!lastAiMessage} />
          </div>
        </div>

        {/* Controls */}
        <div className="lg:col-span-5 space-y-8 flex flex-col">
           <div className="bg-white/5 border-4 border-white/10 p-10 rounded-huge space-y-8 shadow-xl flex-1">
              <div className="flex justify-between items-center">
                <h3 className="text-3xl font-black text-ableYellow uppercase">Ask the AI</h3>
                <span className="text-[10px] font-black bg-white/10 px-3 py-1 rounded text-white/40 tracking-[0.2em]">DIRECT INPUT</span>
              </div>

              <div className="space-y-6">
                <textarea 
                  value={chatInput}
                  onChange={(e) => setChatInput(e.target.value)}
                  placeholder="Describe your vision need..."
                  className="w-full bg-black/40 border-4 border-white/10 rounded-3xl p-6 text-xl font-bold text-white outline-none focus:border-ableYellow transition-all resize-none min-h-[160px]"
                />
                <button 
                  onClick={handleTextChat}
                  disabled={isThinking || !chatInput.trim()}
                  className="w-full py-8 bg-white text-ableBlack rounded-huge font-black text-2xl shadow-huge active:scale-95 transition-all disabled:opacity-20"
                >
                  {isThinking ? 'ANALYZING...' : 'SEND INQUIRY'}
                </button>
              </div>
           </div>

           <div className="grid grid-cols-2 gap-6">
              <button 
                disabled={!isVisionActive}
                onClick={() => analyzeFrame('describe')}
                className="py-12 bg-ableYellow text-ableBlack rounded-[3rem] font-black text-2xl shadow-huge active:scale-95 transition-all disabled:opacity-20 flex flex-col items-center justify-center gap-4 border-4 border-white"
              >
                <span className="text-5xl">🧭</span>
                SURVEY
              </button>
              <button 
                disabled={!isVisionActive}
                onClick={() => analyzeFrame('read')}
                className="py-12 bg-ableOrange text-white rounded-[3rem] font-black text-2xl shadow-huge active:scale-95 transition-all disabled:opacity-20 flex flex-col items-center justify-center gap-4 border-4 border-white/20"
              >
                <span className="text-5xl">📖</span>
                LENS
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

export default AICompanion;

