import { GoogleGenAI, Type } from "@google/genai";
import { PAD, CareerPath } from "../types";

// Always use const ai = new GoogleGenAI({apiKey: process.env.API_KEY});
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const getCareerGuidance = async (pad: PAD, interests: string): Promise<CareerPath[]> => {
  // Use gemini-3-pro-preview for complex reasoning/guidance tasks
  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: `Based on this Personal Accessibility DNA (PAD): ${JSON.stringify(pad)} and user interests: "${interests}", suggest 3 career paths. 
    Refine the suggestions to be ability-first: explain how the user's specific perspective (from their vision and speech DNA) is a STRENGTH in these roles. 
    Keep descriptions strictly under 2 sentences. Focus on adaptive growth. 
    Return a JSON array of objects with the specified schema properties.`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            compatibility: { type: Type.NUMBER },
            description: { type: Type.STRING },
            skills: { 
              type: Type.ARRAY, 
              items: { type: Type.STRING } 
            },
            visualAlternativeNeeded: { type: Type.BOOLEAN },
            speechSupportLevel: { 
              type: Type.STRING,
              description: "Must be one of: 'low', 'medium', or 'high'."
            }
          },
          required: ["title", "compatibility", "description", "skills", "visualAlternativeNeeded", "speechSupportLevel"]
        }
      }
    }
  });

  try {
    const text = response.text || "[]";
    return JSON.parse(text);
  } catch (e) {
    console.error("Failed to parse career guidance", e);
    return [];
  }
};

export const analyzeSurroundings = async (imageData: string): Promise<string> => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        { inlineData: { data: imageData.split(',')[1], mimeType: 'image/jpeg' } },
