import React, { useState, useRef, useEffect } from 'react';
import { useAbility } from '../context/AbilityContext';
import SignLanguageAvatar from './SignLanguageAvatar';
import { GoogleGenAI } from '@google/genai';

const AICompanion: React.FC = () => {
  const { pad, speak } = useAbility();
  const [isVisionActive, setIsVisionActive] = useState(false);
  const [status, setStatus] = useState('READY');
  const [chatInput, setChatInput] = useState('');
  const [lastAiMessage, setLastAiMessage] = useState('');
  const [isThinking, setIsThinking] = useState(false);

  const videoRef = useRef<HTMLVideoElement | null>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null);

  useEffect(() => {
    return () => {
      mediaStreamRef.current?.getTracks().forEach(t => t.stop());
    };
  }, []);

  const toggleVision = async () => {
    if (isVisionActive) {
      mediaStreamRef.current?.getTracks().forEach(t => t.stop());
      mediaStreamRef.current = null;
      setIsVisionActive(false);
      setStatus('OFF');
      speak("Vision Hub deactivated.");
    } else {
      try {
        setStatus('CONNECTING...');
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { 
            facingMode: 'environment', 
            width: { ideal: 1920 },
            height: { ideal: 1080 }
          } 
        });
        mediaStreamRef.current = stream;

        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          videoRef.current.onloadedmetadata = () => {
            videoRef.current?.play().catch(e => console.error("Play error:", e));
          };
        }

        setIsVisionActive(true);
        setStatus('LIVE');
        speak("Vision Hub active. Point your camera at what you'd like me to analyze.");
      } catch (err) {
        setStatus('ERROR');
        speak("Camera access failed. Check permissions.");
      }
    }
  };

  const handleTextChat = async () => {
    if (!chatInput.trim()) return;
    setIsThinking(true);
    const userMsg = chatInput;
    setChatInput('');

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `User message: "${userMsg}". Context: Vision Hub. Respond concisely.`,
        config: {
          systemInstruction: "You are ABLE, an accessibility AI. Be humanoid, concise, and helpful."
        }
      });
      const resText = response.text || "Processed.";
      setLastAiMessage(resText);
      speak(resText);
    } catch (e) {
      setLastAiMessage("Sync failed. Try again.");
    } finally {
      setIsThinking(false);
    }
  };

  const analyzeFrame = async (action: 'describe' | 'read' | 'simplify') => {
    if (!isVisionActive) return;
    setStatus('ANALYZING...');

    // Simulations for the prototype
    const mockResponses = {
      describe: [
        "Path is clear. ADA-compliant ramp detected 10 feet ahead.",
        "Signage detected: Room 202. Accessible restroom to your left.",
        "Bright environment. Low obstacles detected."
      ],
      read: [
        "The text reads: Caution, Automated Door.",
        "The document says: Section A, Building Access protocols.",
        "Identified as: Daily prescription, take once daily."
      ],
      simplify: [
        "This form is asking for your name and contact preference.",
        "The sign basically means you should wait here for assistance.",
        "Simplified: Entry restricted to authorized personnel."
      ]
    };

    const pick = mockResponses[action][Math.floor(Math.random() * 3)];

    setTimeout(() => {
      setStatus('LIVE');
      setLastAiMessage(pick);
      speak(pick);
    }, 1000);
  };

  const replayAudio = () => {
    if (lastAiMessage) speak(lastAiMessage);
    else speak("No previous message to replay.");
  };

  return (
    <div className="space-y-12 py-10 animate-in fade-in duration-500 w-full min-h-screen">
      <header className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-8">
        <div className="space-y-2">
           <h2 className="text-6xl font-black text-ableYellow tracking-tighter uppercase leading-none">Vision Companion</h2>
           <div className="flex items-center space-x-4">
             <div className={`w-3 h-3 rounded-full ${isVisionActive ? 'bg-emerald-500 animate-pulse' : 'bg-white/10'}`}></div>
             <p className="text-xs font-black text-white/40 uppercase tracking-[0.4em]">{status}</p>
           </div>
        </div>

        <button 
          onClick={toggleVision}
          className={`px-12 py-6 rounded-huge font-black text-2xl border-4 transition-all shadow-huge active:scale-95 ${isVisionActive ? 'bg-ableRed border-white text-white' : 'bg-ableYellow border-transparent text-ableBlack'}`}
        >
          {isVisionActive ? 'DEACTIVATE' : 'ACTIVATE VISION'}
        </button>
      </header>

      <div className="grid grid-cols-1 xl:grid-cols-12 gap-10 h-full">
        {/* Main Feed */}
        <div className="xl:col-span-8 bg-black border-8 border-ableYellow rounded-huge overflow-hidden relative min-h-[500px] xl:h-[700px] shadow-2xl">
          {isVisionActive ? (
            <video 
              ref={videoRef} 
              autoPlay 
              playsInline 
              muted 
              className="w-full h-full object-cover" 
            />
          ) : (
            <div className="absolute inset-0 flex flex-col items-center justify-center space-y-8 bg-ableBlack">
               <div className="text-9xl opacity-5">👁️</div>
               <p className="text-xl font-black text-white/10 uppercase tracking-widest">Feed Standing By</p>
            </div>
          )}

          <div className="absolute bottom-8 right-8 w-48 xl:w-64 shadow-huge">
             <SignLanguageAvatar message={lastAiMessage} active={!!lastAiMessage} />
          </div>
        </div>

        {/* Action Panel */}
        <div className="xl:col-span-4 flex flex-col gap-6">
           <div className="bg-white/5 border-4 border-white/10 p-10 rounded-huge space-y-8 shadow-xl flex-1">
              <div className="flex justify-between items-center border-b-4 border-white/5 pb-4">
                <h3 className="text-2xl font-black text-ableYellow uppercase">AI Assistant</h3>
                <button 
                  onClick={replayAudio}
                  className="p-3 bg-white/10 rounded-xl hover:bg-ableYellow hover:text-ableBlack transition-all"
                  aria-label="Replay Audio"
                >
                  🔊
                </button>
              </div>

              <div className="space-y-6">
                <textarea 
                  value={chatInput}
                  onChange={(e) => setChatInput(e.target.value)}
                  placeholder="Type a request..."
                  className="w-full bg-black/40 border-4 border-white/10 rounded-3xl p-6 text-xl font-bold text-white outline-none focus:border-ableYellow transition-all resize-none min-h-[140px]"
                />
                <button 
                  onClick={handleTextChat}
                  disabled={isThinking || !chatInput.trim()}
                  className="w-full py-6 bg-white text-ableBlack rounded-huge font-black text-xl shadow-huge active:scale-95 transition-all disabled:opacity-20"
                >
                  {isThinking ? 'Thinking...' : 'Speak/Chat'}
                </button>
              </div>
           </div>

           <div className="grid grid-cols-1 gap-4">
              <button 
                disabled={!isVisionActive}
                onClick={() => analyzeFrame('describe')}
                className="py-8 bg-ableYellow text-ableBlack rounded-huge font-black text-xl shadow-huge active:scale-95 transition-all disabled:opacity-20 flex items-center justify-center gap-6"
              >
                <span className="text-3xl">🧭</span>
                DESCRIBE SCENE
              </button>
              <button 
                disabled={!isVisionActive}
                onClick={() => analyzeFrame('read')}
                className="py-8 bg-ableOrange text-white rounded-huge font-black text-xl shadow-huge active:scale-95 transition-all disabled:opacity-20 flex items-center justify-center gap-6"
              >
                <span className="text-3xl">📖</span>
                READ TEXT
              </button>
              <button 
                disabled={!isVisionActive}
                onClick={() => analyzeFrame('simplify')}
                className="py-8 bg-ableSlate text-white rounded-huge font-black text-xl shadow-huge active:scale-95 transition-all disabled:opacity-20 flex items-center justify-center gap-6 border-4 border-white/10"
              >
                <span className="text-3xl">🧩</span>
                SIMPLIFY INFO
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

export default AICompanion;

import { GoogleGenAI, Type } from "@google/genai";
import { PAD, CareerPath } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const getCareerGuidance = async (pad: PAD, interests: string): Promise<CareerPath[]> => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: `Suggest 3 career paths for a person with this Personal Accessibility DNA (PAD): ${JSON.stringify(pad)} and these interests: "${interests}". 
    CRITICAL INSTRUCTION: Your response must be "Ability-First". 
    1. Explain how their vision (${pad.visual}) or speech rhythm (${pad.speech}) is a unique professional SUPERPOWER for the role.
    2. Be extremely concise: strictly 1-2 sentences per role.
    3. Ensure direct relevance to both the interests and the PAD profile.
    Return a JSON array of objects with the specified schema properties.`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            compatibility: { type: Type.NUMBER },
            description: { type: Type.STRING },
            skills: { 
              type: Type.ARRAY, 
              items: { type: Type.STRING } 
            },
            visualAlternativeNeeded: { type: Type.BOOLEAN },
            speechSupportLevel: { 
              type: Type.STRING,
              description: "Must be 'low', 'medium', or 'high'."
            }
          },
          required: ["title", "compatibility", "description", "skills", "visualAlternativeNeeded", "speechSupportLevel"]
        }
      }
    }
  });

  try {
    const text = response.text || "[]";
    return JSON.parse(text);
  } catch (e) {
    console.error("Failed to parse career guidance", e);
    return [];
  }
};

