import React, { useState, useRef, useEffect } from 'react';
import { useAbility } from '../context/AbilityContext';
import SignLanguageAvatar from './SignLanguageAvatar';
import { GoogleGenAI } from '@google/genai';

const AICompanion: React.FC = () => {
  const { pad, speak } = useAbility();
  const [isVisionActive, setIsVisionActive] = useState(false);
  const [status, setStatus] = useState('STANDBY');
  const [chatInput, setChatInput] = useState('');
  const [lastAiMessage, setLastAiMessage] = useState('');
  const [isThinking, setIsThinking] = useState(false);

  const videoRef = useRef<HTMLVideoElement | null>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null);

  useEffect(() => {
    return () => {
      mediaStreamRef.current?.getTracks().forEach(t => t.stop());
    };
  }, []);

  const toggleVision = async () => {
    if (isVisionActive) {
      mediaStreamRef.current?.getTracks().forEach(t => t.stop());
      mediaStreamRef.current = null;
      setIsVisionActive(false);
      setStatus('OFF');
      speak("Vision Hub deactivated.");
    } else {
      try {
        setStatus('WAKING UP...');
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { 
            facingMode: 'environment', 
            width: { ideal: 1920 },
            height: { ideal: 1080 }
          } 
        });
        mediaStreamRef.current = stream;

        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          videoRef.current.onloadedmetadata = () => {
            videoRef.current?.play().catch(e => console.error("Camera playback error:", e));
          };
        }

        setIsVisionActive(true);
        setStatus('LIVE');
        speak("Vision Hub active. Point the lens at your surroundings.");
      } catch (err) {
        setStatus('ERROR');
        speak("Camera failed. Please check permissions.");
      }
    }
  };

  const handleAction = async (msg?: string) => {
    const query = msg || chatInput;
    if (!query.trim()) return;

    setIsThinking(true);
    if (!msg) setChatInput('');

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Context: Vision Hub. User query: "${query}". Provide a short, direct accessibility-focused response.`,
        config: {
          systemInstruction: "You are ABLE, a humanoid assistant. Be brief and supportive."
        }
      });
      const resText = response.text || "Synchronized.";
      setLastAiMessage(resText);
      speak(resText);
    } catch (e) {
      setLastAiMessage("Connection lost. Tap to try again.");
    } finally {
      setIsThinking(false);
    }
  };

  const runSimulation = (type: 'describe' | 'read' | 'simplify') => {
    if (!isVisionActive) return;
    setStatus('SCANNING...');

    const mocks = {
      describe: ["Open path detected. Door at 2 o'clock.", "Sign detected: Level 3 Lobby.", "Environment is quiet and well-lit."],
      read: ["Text found: 'Automatic Sliding Door'", "Warning: 'Step detected'", "Label identified as: 'Aspirin 500mg'"],
      simplify: ["This sign says wait here for help.", "The text is an instruction manual for the lift.", "Summary: Press the green button to start."]
    };

    const pick = mocks[type][Math.floor(Math.random() * 3)];
    setTimeout(() => {
      setStatus('LIVE');
      setLastAiMessage(pick);
      speak(pick);
    }, 800);
  };

  const handleSpeakInput = () => {
    if (chatInput.trim()) {
      speak(chatInput);
    }
  };

  return (
    <div className="flex flex-col space-y-8 py-6 w-full max-w-full overflow-x-hidden">
      <header className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6">
        <div className="space-y-1">
           <h2 className="text-5xl font-black text-ableYellow tracking-tighter uppercase leading-none">Vision Companion</h2>
           <div className="flex items-center space-x-3">
             <div className={`w-3 h-3 rounded-full ${isVisionActive ? 'bg-emerald-500 animate-pulse' : 'bg-white/10'}`}></div>
             <p className="text-[10px] font-black text-white/40 uppercase tracking-[0.5em]">{status}</p>
           </div>
        </div>

        <button 
          onClick={toggleVision}
          className={`px-10 py-5 rounded-huge font-black text-xl border-4 transition-all shadow-huge active:scale-95 ${isVisionActive ? 'bg-ableRed border-white text-white' : 'bg-ableYellow border-transparent text-ableBlack'}`}
        >
          {isVisionActive ? 'STOP LENS' : 'START VISION'}
        </button>
      </header>

      <div className="grid grid-cols-1 xl:grid-cols-12 gap-8 w-full">
        {/* Visual Feed Section */}
        <div className="xl:col-span-8 bg-black border-8 border-ableYellow rounded-huge overflow-hidden relative aspect-video xl:aspect-auto xl:h-[650px] shadow-2xl flex items-center justify-center">
          {isVisionActive ? (
            <video 
              ref={videoRef} 
              autoPlay 
              playsInline 
              muted 
              className="w-full h-full object-cover scale-x-[-1]" 
            />
          ) : (
            <div className="flex flex-col items-center justify-center space-y-6">
               <div className="text-8xl opacity-10">👁️</div>
               <p className="text-sm font-black text-white/20 uppercase tracking-[0.3em]">Lens Standby</p>
            </div>
          )}

          <div className="absolute bottom-6 right-6 w-40 md:w-56 shadow-huge transition-transform hover:scale-105">
             <SignLanguageAvatar message={lastAiMessage} active={!!lastAiMessage} />
          </div>
        </div>

        {/* Intelligence Controls Section */}
        <div className="xl:col-span-4 flex flex-col gap-6">
           <div className="bg-white/5 border-4 border-white/10 p-8 rounded-huge space-y-6 shadow-xl flex-1 flex flex-col justify-between">
              <div className="flex justify-between items-center border-b-2 border-white/5 pb-4">
                <h3 className="text-xl font-black text-ableYellow uppercase tracking-widest">DNA Assistant</h3>
                {lastAiMessage && (
                  <button 
                    onClick={() => speak(lastAiMessage)}
                    className="w-10 h-10 bg-white/10 rounded-xl flex items-center justify-center hover:bg-ableYellow hover:text-ableBlack transition-all"
                    title="Repeat Audio"
                  >
                    🔊
                  </button>
                )}
              </div>

              <div className="space-y-4">
                <textarea 
                  value={chatInput}
                  onChange={(e) => setChatInput(e.target.value)}
                  placeholder="Ask me to describe, read, or say something..."
                  className="w-full bg-black/40 border-4 border-white/10 rounded-2xl p-5 text-lg font-bold text-white outline-none focus:border-ableYellow transition-all resize-none h-[180px]"
                />
                <div className="grid grid-cols-2 gap-3">
                  <button 
                    onClick={() => handleAction()}
                    disabled={isThinking || !chatInput.trim()}
                    className="py-5 bg-white text-ableBlack rounded-2xl font-black text-lg shadow-huge active:scale-95 transition-all disabled:opacity-20"
                  >
                    {isThinking ? '...' : 'ANALYZE'}
                  </button>
                  <button 
                    onClick={handleSpeakInput}
                    disabled={!chatInput.trim()}
                    className="py-5 bg-ableOrange text-white rounded-2xl font-black text-lg shadow-huge active:scale-95 transition-all disabled:opacity-20 border-2 border-white/10"
                  >
                    SPEAK
                  </button>
                </div>
              </div>
           </div>

           <div className="flex flex-col gap-3">
              <button 
                disabled={!isVisionActive}
                onClick={() => runSimulation('describe')}
                className="w-full py-7 bg-ableYellow text-ableBlack rounded-huge font-black text-lg shadow-huge active:scale-95 transition-all disabled:opacity-20 flex items-center justify-center gap-4 border-4 border-white"
              >
                <span className="text-3xl">🧭</span>
                DESCRIBE SCENE
              </button>
              <button 
                disabled={!isVisionActive}
                onClick={() => runSimulation('read')}
                className="w-full py-7 bg-ableOrange text-white rounded-huge font-black text-lg shadow-huge active:scale-95 transition-all disabled:opacity-20 flex items-center justify-center gap-4 border-4 border-white/10"
              >
                <span className="text-3xl">📖</span>
                READ TEXT
              </button>
              <button 
                disabled={!isVisionActive}
                onClick={() => runSimulation('simplify')}
                className="w-full py-7 bg-ableSlate text-white rounded-huge font-black text-lg shadow-huge active:scale-95 transition-all disabled:opacity-20 flex items-center justify-center gap-4 border-4 border-white/5"
              >
                <span className="text-3xl">🧩</span>
                SIMPLIFY INFO
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

export default AICompanion;

