import React, { useState, useCallback } from 'react';
import { useAbility } from '../context/AbilityContext';

const ReportIssue: React.FC<{ onClose: () => void }> = ({ onClose }) => {
  const { speak } = useAbility();
  const [desc, setDesc] = useState('');
  const [loading, setLoading] = useState(false);
  const [done, setDone] = useState(false);
  const [isListening, setIsListening] = useState(false);

  const submit = async () => {
    if (!desc.trim()) return;
    setLoading(true);
    await new Promise(r => setTimeout(r, 1000));
    setDone(true);
    setLoading(false);
    setTimeout(onClose, 2000);
  };

  const startListening = useCallback(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      speak("Dictation is not supported in this browser.");
      return;
    }

    const recognition = new SpeechRecognition();
    recognition.lang = 'en-US';
    recognition.interimResults = false;
    recognition.maxAlternatives = 1;

    recognition.onstart = () => {
      setIsListening(true);
    };

    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setDesc(prev => prev ? `${prev} ${transcript}` : transcript);
    };

    recognition.onerror = (event: any) => {
      setIsListening(false);
      let errorMsg = "Dictation error.";
      switch(event.error) {
        case 'not-allowed': errorMsg = "Microphone access blocked."; break;
        case 'network': errorMsg = "Network connection required."; break;
        case 'no-speech': errorMsg = "No speech detected."; break;
      }
      speak(errorMsg);
    };

    recognition.onend = () => {
      setIsListening(false);
    };

    recognition.start();
  }, [speak]);

  return (
    <div className="fixed inset-0 z-[100] bg-ableBlack/95 flex items-center justify-center p-6 backdrop-blur-md">
      <div className="max-w-2xl w-full bg-ableBlack border-8 border-ableRed p-12 rounded-huge shadow-huge space-y-10 animate-in zoom-in duration-300">

        {done ? (
          <div className="text-center space-y-8 py-10">
            <div className="text-9xl animate-bounce">👍</div>
            <h2 className="text-5xl font-black text-ableYellow">REPORT SENT</h2>
            <p className="text-2xl font-bold">We are adapting the system now.</p>
          </div>
        ) : (
          <div className="space-y-10">
            <header className="flex justify-between items-start">
              <div className="space-y-2">
                <p className="text-xs font-black text-ableRed uppercase tracking-widest">System Feedback</p>
                <h2 className="text-5xl font-black text-white tracking-tighter">REPORT BARRIER.</h2>
              </div>
              <button onClick={onClose} className="text-4xl text-white/40 hover:text-white p-2">✕</button>
            </header>

            <div className="space-y-6">
              <div className="flex justify-between items-end">
                <p className="text-xl font-bold text-white/60">What hindered your ability today?</p>
                <button 
                  onClick={startListening}
                  className={`flex items-center gap-2 px-4 py-2 rounded-xl font-black text-xs border-2 transition-all ${isListening ? 'bg-ableRed border-white animate-pulse' : 'bg-white/10 border-white/20 hover:border-ableYellow text-white'}`}
                >
                  {isListening ? 'LISTENING...' : '🎙️ DICTATE'}
                </button>
              </div>
              <textarea 
                value={desc}
                onChange={(e) => setDesc(e.target.value)}
                placeholder="e.g., Font too small, AI cut me off..."
                className="w-full h-48 bg-white/5 border-4 border-white/20 rounded-3xl p-8 text-2xl font-bold text-white outline-none focus:border-ableYellow transition-all resize-none"
              />
            </div>

            <button 
              onClick={submit}
              disabled={loading || !desc.trim()}
              className="w-full py-8 bg-ableRed text-white rounded-huge font-black text-3xl shadow-2xl active:scale-95 transition-all disabled:opacity-50"
            >
              {loading ? 'SENDING...' : 'SEND REPORT'}
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

