import React, { useState, useEffect, useCallback, useRef } from 'react';
import { useAbility } from '../context/AbilityContext';
import { GoogleGenAI } from '@google/genai';

const CommHub: React.FC = () => {
  const { pad, speak } = useAbility();
  const [speakText, setSpeakText] = useState('');
  const [isListening, setIsListening] = useState(false);
  const [transcript, setTranscript] = useState('');
  const [ifiStatus, setIfiStatus] = useState('Standby');
  const [aiResponse, setAiResponse] = useState('');
  const recognitionRef = useRef<any>(null);

  const handleSpeak = () => {
    if (!speakText) return;
    speak(speakText);
    setSpeakText('');
  };

  const processWithAI = async (userText: string) => {
    if (!userText.trim()) return;

    // Easter Eggs Check
    const lowerText = userText.toLowerCase();
    if (lowerText.includes('who is lakshita')) {
      const resp = "Lakshita is my brilliant creator. She designed me to adapt to your world.";
      setAiResponse(resp);
      setIfiStatus('AI Ready');
      speak(resp);
      return;
    }
    if (lowerText.includes('who is naksh')) {
      const resp = "Naksh is my creator and the driving force behind my systems. He is my primary architect.";
      setAiResponse(resp);
      setIfiStatus('AI Ready');
      speak(resp);
      return;
    }

    setIfiStatus('Analyzing Intent...');
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `User says: "${userText}". 
        Context: The user has ${pad.visual} vision and ${pad.speech} style. 
        Provide a relevant, supportive, and humanoid response.
        CRITICAL: Your response MUST NOT exceed two concise sentences.`,
        config: {
          systemInstruction: "You are ABLE, an adaptive assistant. You help people with disabilities by listening with patience and speaking with clear intent. Always be brief, supportive, and humanoid. Limit your output to 1-2 sentences maximum."
        }
      });

      const textResponse = response.text || "I'm listening and here to help you.";
      setAiResponse(textResponse);
      setIfiStatus('AI Ready');
      speak(textResponse);
    } catch (error) {
      console.error("AI Error:", error);
      setIfiStatus('Sync Error');
      speak("I lost connection for a moment. Please tap and try again.");
    }
  };

  const startListening = useCallback(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      const msg = "Voice input is not supported in this browser.";
      speak(msg);
      alert(msg);
      return;
    }

    if (recognitionRef.current) {
      try { recognitionRef.current.stop(); } catch(e) {}
    }

    const recognition = new SpeechRecognition();
    recognition.lang = 'en-US';
    recognition.interimResults = true;
    recognition.continuous = false;
    recognitionRef.current = recognition;

    recognition.onstart = () => {
      setIsListening(true);
      setIfiStatus('Listening...');
      setTranscript('');
      setAiResponse('');
    };

    recognition.onresult = (event: any) => {
      let currentTranscript = '';
      for (let i = event.resultIndex; i < event.results.length; ++i) {
        currentTranscript += event.results[i][0].transcript;
      }
      setTranscript(currentTranscript);
    };

    recognition.onerror = (event: any) => {
      setIsListening(false);
      let errorMsg = "Speech recognition error.";

      switch(event.error) {
        case 'not-allowed':
          errorMsg = "Microphone access is blocked. Please allow it in settings.";
          break;
        case 'network':
          errorMsg = "Network error. Speech recognition requires an internet connection.";
          break;
        case 'no-speech':
          errorMsg = "I didn't hear anything. Please try again.";
          break;
        default:
          errorMsg = `Speech error: ${event.error}`;
      }

      setIfiStatus('Error');
      speak(errorMsg);
    };

    recognition.onend = () => {
      setIsListening(false);
      if (transcript.trim()) {
        setIfiStatus('Processing...');
      } else if (ifiStatus !== 'Error') {
        setIfiStatus('Standby');
      }
    };

    recognition.start();
  }, [speak, transcript, ifiStatus]);

  useEffect(() => {
    if (!isListening && transcript.trim() && ifiStatus === 'Processing...') {
      processWithAI(transcript);
    }
  }, [isListening, transcript, ifiStatus]);

  const soundboard = [
    { label: 'YES', text: "Yes, that's correct.", color: 'bg-emerald-500' },
    { label: 'NO', text: "No, thank you.", color: 'bg-ableRed' },
    { label: 'WAIT', text: "Please wait, I am finishing my thought.", color: 'bg-ableOrange' },
    { label: 'THANKS', text: "Thank you for your patience.", color: 'bg-ableYellow text-ableBlack' }
  ];

  return (
    <div className="space-y-12 py-10 animate-in slide-in-from-left-10 duration-700">
      <header className="space-y-4">
        <h2 className="text-6xl font-black text-ableYellow tracking-tighter">VOICE HUB.</h2>
        <p className="text-2xl font-bold text-white/60">Real conversation, humanoid pace. IFI™ AI hears your intent and responds instantly.</p>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
        <section className="bg-ableBlack border-8 border-ableYellow p-12 rounded-huge shadow-2xl space-y-10">
          <div className="space-y-2">
            <h3 className="text-4xl font-black text-ableYellow uppercase">Speak for Me</h3>
            <p className="text-xl font-medium opacity-60">Shortcuts for immediate communication.</p>
          </div>

          <div className="grid grid-cols-2 gap-4">
            {soundboard.map(btn => (
              <button 
                key={btn.label}
                onClick={() => speak(btn.text)}
                className={`${btn.color} py-10 rounded-3xl font-black text-3xl shadow-xl active:scale-95 transition-all text-white border-4 border-white/20 hover:brightness-110`}
              >
                {btn.label}
              </button>
            ))}
          </div>

          <div className="pt-6 space-y-4">
            <input 
              type="text"
              value={speakText}
              onChange={(e) => setSpeakText(e.target.value)}
              placeholder="TYPE YOUR MESSAGE..."
              className="w-full bg-white/5 border-4 border-white/20 rounded-huge px-8 py-6 text-2xl font-black text-white outline-none focus:border-ableYellow transition-all"
            />
            <button 
              onClick={handleSpeak}
              className="w-full py-8 bg-white text-ableBlack rounded-huge font-black text-3xl shadow-huge active:scale-95 transition-all hover:bg-ableYellow"
            >
              SPEAK AS ME
            </button>
          </div>
        </section>

        <section className="bg-ableBlack border-8 border-ableOrange p-12 rounded-huge shadow-2xl flex flex-col justify-between space-y-10">
           <div className="flex justify-between items-start">
            <div className="space-y-2">
              <h3 className="text-4xl font-black text-ableOrange">AI VOICE CHAT</h3>
              <p className="text-xl font-medium opacity-60">Patience integrated. Talk to me.</p>
            </div>
            <div className={`px-4 py-2 border-2 rounded-xl text-[10px] font-black tracking-widest transition-all ${isListening ? 'bg-ableRed border-white text-white animate-pulse' : 'bg-ableOrange/10 border-ableOrange/40 text-ableOrange'}`}>
              {ifiStatus.toUpperCase()}
            </div>
          </div>

          <div className="flex-1 bg-white/5 border-4 border-white/10 rounded-3xl p-10 flex flex-col justify-center space-y-8 min-h-[300px]">
            <div className="space-y-3">
              <p className="text-xs font-black text-white/30 uppercase tracking-widest">User Intent:</p>
              <p className={`text-3xl font-black leading-tight transition-opacity ${transcript ? 'text-white' : 'text-white/10 italic'}`}>
                {transcript || (isListening ? 'Listening...' : 'Tap microphone to start...')}
              </p>
            </div>

            {aiResponse && (
              <div className="space-y-3 pt-8 border-t-4 border-white/5 animate-in fade-in slide-in-from-bottom-4">
                <p className="text-xs font-black text-ableOrange uppercase tracking-widest">ABLE Assistant:</p>
                <p className="text-2xl font-bold text-white/90 leading-snug">
                  {aiResponse}
                </p>
              </div>
            )}
          </div>

          <div className="flex flex-col items-center gap-6">
            <button 
              onClick={startListening}
              disabled={isListening}
              className={`w-36 h-36 rounded-full flex items-center justify-center text-7xl shadow-huge transition-all active:scale-90 ${isListening ? 'bg-ableRed animate-ping scale-110 shadow-ableRed/50' : 'bg-ableOrange shadow-ableOrange/50 hover:scale-110'}`}
              aria-label="Start Voice Chat"
            >
              🎙️
            </button>
            <p className="text-xs font-black uppercase tracking-[0.5em] text-ableOrange opacity-60">
              {isListening ? 'RECORDING' : 'TAP TO BEGIN CHAT'}
            </p>
          </div>
        </section>
      </div>
    </div>
  );
};

export default CommHub;

import React, { useState, useRef, useEffect } from 'react';
import { useAbility } from '../context/AbilityContext';
import SignLanguageAvatar from './SignLanguageAvatar';
import { GoogleGenAI } from '@google/genai';

const AICompanion: React.FC = () => {
  const { pad, speak } = useAbility();
  const [isVisionActive, setIsVisionActive] = useState(false);
  const [status, setStatus] = useState('STANDBY');
  const [chatInput, setChatInput] = useState('');
  const [lastAiMessage, setLastAiMessage] = useState('');
  const [isThinking, setIsThinking] = useState(false);
  const [groundingLinks, setGroundingLinks] = useState<{title: string, uri: string}[]>([]);

  const videoRef = useRef<HTMLVideoElement | null>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null);

  // Clean up camera on unmount
  useEffect(() => {
    return () => {
      if (mediaStreamRef.current) {
        mediaStreamRef.current.getTracks().forEach(t => t.stop());
      }
    };
  }, []);

  const toggleVision = async () => {
    if (isVisionActive) {
      if (mediaStreamRef.current) {
        mediaStreamRef.current.getTracks().forEach(t => t.stop());
        mediaStreamRef.current = null;
      }
      setIsVisionActive(false);
      setStatus('OFF');
      speak("Vision Hub deactivated.");
    } else {
      try {
        setStatus('WAKING UP...');
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { 
            facingMode: 'environment', 
            width: { ideal: 1920 },
            height: { ideal: 1080 }
          },
          audio: false 
        });

        mediaStreamRef.current = stream;

        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          // Ensure playback starts immediately
          await videoRef.current.play();
        }

        setIsVisionActive(true);
        setStatus('LIVE');
        speak("Vision Hub active. Point the lens at your surroundings.");
      } catch (err) {
        console.error("Camera Error:", err);
        setStatus('ERROR');
        speak("Camera failed. Please check permissions and ensure no other app is using it.");
      }
    }
  };

  const handleAction = async (msg?: string) => {
    const query = msg || chatInput;
