      describe: ["Open path detected. Door at 2 o'clock.", "Sign detected: Level 3 Lobby.", "Environment is quiet and well-lit."],
      read: ["Text found: 'Automatic Sliding Door'", "Warning: 'Step detected'", "Label identified as: 'Aspirin 500mg'"],
      simplify: ["This sign says wait here for help.", "The text is an instruction manual for the lift.", "Summary: Press the green button to start."]
    };

    const pick = mocks[type][Math.floor(Math.random() * 3)];
    setTimeout(() => {
      setStatus('LIVE');
      setLastAiMessage(pick);
      speak(pick);
    }, 800);
  };

  const handleSpeakInput = () => {
    if (chatInput.trim()) {
      speak(chatInput);
    }
  };

  return (
    <div className="flex flex-col space-y-8 py-6 w-full max-w-full overflow-x-hidden">
      <header className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6">
        <div className="space-y-1">
           <h2 className="text-5xl font-black text-ableYellow tracking-tighter uppercase leading-none">Vision Companion</h2>
           <div className="flex items-center space-x-3">
             <div className={`w-3 h-3 rounded-full ${isVisionActive ? 'bg-emerald-500 animate-pulse' : 'bg-white/10'}`}></div>
             <p className="text-[10px] font-black text-white/40 uppercase tracking-[0.5em]">{status}</p>
           </div>
        </div>

        <button 
          onClick={toggleVision}
          className={`px-10 py-5 rounded-huge font-black text-xl border-4 transition-all shadow-huge active:scale-95 ${isVisionActive ? 'bg-ableRed border-white text-white' : 'bg-ableYellow border-transparent text-ableBlack'}`}
        >
          {isVisionActive ? 'STOP LENS' : 'START VISION'}
        </button>
      </header>

      <div className="grid grid-cols-1 xl:grid-cols-12 gap-8 w-full">
        {/* Visual Feed Section */}
        <div className="xl:col-span-8 bg-black border-8 border-ableYellow rounded-huge overflow-hidden relative aspect-video xl:aspect-auto xl:h-[650px] shadow-2xl flex items-center justify-center">
          {isVisionActive ? (
            <video 
              ref={videoRef} 
              autoPlay 
              playsInline 
              muted 
              className="w-full h-full object-cover scale-x-[-1]" 
            />
          ) : (
            <div className="flex flex-col items-center justify-center space-y-6">
               <div className="text-8xl opacity-10">👁️</div>
               <p className="text-sm font-black text-white/20 uppercase tracking-[0.3em]">Lens Standby</p>
            </div>
