import React, { useState, useEffect, useCallback, useRef } from 'react';
import { useAbility } from '../context/AbilityContext';
import { GoogleGenAI } from '@google/genai';

const CommHub: React.FC = () => {
  const { pad, speak } = useAbility();
  const [speakText, setSpeakText] = useState('');
  const [isListening, setIsListening] = useState(false);
  const [transcript, setTranscript] = useState('');
  const [ifiStatus, setIfiStatus] = useState('Standby');
  const [aiResponse, setAiResponse] = useState('');
  const [groundingLinks, setGroundingLinks] = useState<{title: string, uri: string}[]>([]);
  const [activeMedia, setActiveMedia] = useState<string | null>(null);
  const recognitionRef = useRef<any>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  const handleSpeak = () => {
    if (!speakText) return;
    speak(speakText);
    setSpeakText('');
  };

  const processWithAI = async (userText: string) => {
    if (!userText.trim()) return;

    // Easter Eggs Check
    const lowerText = userText.toLowerCase();
    if (lowerText.includes('who is lakshita')) {
      const resp = "Lakshita is my brilliant creator. She designed me to adapt to your world.";
      setAiResponse(resp);
      setIfiStatus('AI Ready');
      speak(resp);
      return;
    }
    if (lowerText.includes('who is naksh')) {
      const resp = "Naksh is my creator and the driving force behind my systems. He is my primary architect.";
      setAiResponse(resp);
      setIfiStatus('AI Ready');
      speak(resp);
      return;
    }

    setIfiStatus('Analyzing Intent...');
    setGroundingLinks([]);
    setActiveMedia(null);

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `User says: "${userText}". 
        Context: The user has ${pad.visual} vision and ${pad.speech} style. 
        If the user asks to "play a song", use Google Search to find the lyrics or an audio source. 
        Provide a relevant, supportive, and humanoid response.
        If you find lyrics, state you will recite them. If you find an audio URL (mp3/direct link), mention it.
        CRITICAL: Your response MUST NOT exceed two concise sentences.`,
        config: {
          tools: [{ googleSearch: {} }],
          systemInstruction: "You are ABLE, an adaptive assistant. You help people with disabilities. If asked for music, try to find lyrics or audio using search. Be brief, supportive, and humanoid. Limit output to 1-2 sentences."
        }
      });

      const textResponse = response.text || "I'm listening and here to help you.";
      setAiResponse(textResponse);
      setIfiStatus('AI Ready');
      speak(textResponse);

      // Extract search grounding links for music or info
      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
      if (chunks) {
        const links = chunks
          .filter(chunk => chunk.web)
          .map(chunk => ({ title: chunk.web!.title, uri: chunk.web!.uri }));
        setGroundingLinks(links);

        // Simple logic to detect "audio" links for simulation
        const possibleAudio = links.find(l => l.uri.includes('.mp3') || l.uri.includes('audio') || l.uri.includes('streaming'));
        if (possibleAudio) {
           setActiveMedia(possibleAudio.uri);
        }
      }

    } catch (error) {
      console.error("AI Error:", error);
      setIfiStatus('Sync Error');
      speak("I lost connection for a moment. Please tap and try again.");
    }
  };

  const startListening = useCallback(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      const msg = "Voice input is not supported in this browser.";
      speak(msg);
      alert(msg);
      return;
    }

    if (recognitionRef.current) {
      try { recognitionRef.current.stop(); } catch(e) {}
    }

    const recognition = new SpeechRecognition();
    recognition.lang = 'en-US';
    recognition.interimResults = true;
    recognition.continuous = false;
    recognitionRef.current = recognition;

    recognition.onstart = () => {
      setIsListening(true);
      setIfiStatus('Listening...');
      setTranscript('');
      setAiResponse('');
    };

    recognition.onresult = (event: any) => {
      let currentTranscript = '';
      for (let i = event.resultIndex; i < event.results.length; ++i) {
        currentTranscript += event.results[i][0].transcript;
      }
      setTranscript(currentTranscript);
    };

    recognition.onerror = (event: any) => {
      setIsListening(false);
      let errorMsg = "Speech recognition error.";

      switch(event.error) {
        case 'not-allowed':
          errorMsg = "Microphone access is blocked. Please allow it in settings.";
          break;
        case 'network':
          errorMsg = "Network error. Speech recognition requires an internet connection.";
          break;
        case 'no-speech':
          errorMsg = "I didn't hear anything. Please try again.";
          break;
        default:
          errorMsg = `Speech error: ${event.error}`;
      }

      setIfiStatus('Error');
      speak(errorMsg);
    };

    recognition.onend = () => {
      setIsListening(false);
      if (transcript.trim()) {
        setIfiStatus('Processing...');
      } else if (ifiStatus !== 'Error') {
        setIfiStatus('Standby');
      }
    };

    recognition.start();
  }, [speak, transcript, ifiStatus]);

  useEffect(() => {
    if (!isListening && transcript.trim() && ifiStatus === 'Processing...') {
      processWithAI(transcript);
    }
  }, [isListening, transcript, ifiStatus]);

  const soundboard = [
    { label: 'YES', text: "Yes, that's correct.", color: 'bg-emerald-500' },
    { label: 'NO', text: "No, thank you.", color: 'bg-ableRed' },
    { label: 'WAIT', text: "Please wait, I am finishing my thought.", color: 'bg-ableOrange' },
    { label: 'THANKS', text: "Thank you for your patience.", color: 'bg-ableYellow text-ableBlack' }
  ];

  const stopAudio = () => {
    if (audioRef.current) {
      audioRef.current.pause();
      setActiveMedia(null);
    }
  };

  return (
    <div className="space-y-12 py-10 animate-in slide-in-from-left-10 duration-700">
      <header className="space-y-4">
        <h2 className="text-6xl font-black text-ableYellow tracking-tighter">VOICE HUB.</h2>
        <p className="text-2xl font-bold text-white/60">Real conversation, humanoid pace. IFI™ AI hears your intent and responds instantly.</p>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
        <section className="bg-ableBlack border-8 border-ableYellow p-12 rounded-huge shadow-2xl space-y-10">
          <div className="space-y-2">
            <h3 className="text-4xl font-black text-ableYellow uppercase">Speak for Me</h3>
            <p className="text-xl font-medium opacity-60">Shortcuts for immediate communication.</p>
          </div>

          <div className="grid grid-cols-2 gap-4">
            {soundboard.map(btn => (
              <button 
                key={btn.label}
                onClick={() => speak(btn.text)}
                className={`${btn.color} py-10 rounded-3xl font-black text-3xl shadow-xl active:scale-95 transition-all text-white border-4 border-white/20 hover:brightness-110`}
              >
                {btn.label}
              </button>
            ))}
          </div>

          <div className="pt-6 space-y-4">
            <input 
              type="text"
              value={speakText}
              onChange={(e) => setSpeakText(e.target.value)}
              placeholder="TYPE YOUR MESSAGE..."
              className="w-full bg-white/5 border-4 border-white/20 rounded-huge px-8 py-6 text-2xl font-black text-white outline-none focus:border-ableYellow transition-all"
            />
            <button 
              onClick={handleSpeak}
              className="w-full py-8 bg-white text-ableBlack rounded-huge font-black text-3xl shadow-huge active:scale-95 transition-all hover:bg-ableYellow"
            >
              SPEAK AS ME
            </button>
          </div>
        </section>

        <section className="bg-ableBlack border-8 border-ableOrange p-12 rounded-huge shadow-2xl flex flex-col justify-between space-y-10">
           <div className="flex justify-between items-start">
            <div className="space-y-2">
              <h3 className="text-4xl font-black text-ableOrange uppercase">AI VOICE CHAT</h3>
              <p className="text-xl font-medium opacity-60">Patience integrated. Talk to me.</p>
            </div>
            <div className={`px-4 py-2 border-2 rounded-xl text-[10px] font-black tracking-widest transition-all ${isListening ? 'bg-ableRed border-white text-white animate-pulse' : 'bg-ableOrange/10 border-ableOrange/40 text-ableOrange'}`}>
              {ifiStatus.toUpperCase()}
            </div>
          </div>

          <div className="flex-1 bg-white/5 border-4 border-white/10 rounded-3xl p-10 flex flex-col justify-center space-y-8 min-h-[300px] overflow-hidden">
            <div className="space-y-3">
              <p className="text-xs font-black text-white/30 uppercase tracking-widest">User Intent:</p>
              <p className={`text-3xl font-black leading-tight transition-opacity ${transcript ? 'text-white' : 'text-white/10 italic'}`}>
                {transcript || (isListening ? 'Listening...' : 'Ask me to "Play a song..."')}
              </p>
            </div>

            {aiResponse && (
              <div className="space-y-3 pt-8 border-t-4 border-white/5 animate-in fade-in slide-in-from-bottom-4">
                <p className="text-xs font-black text-ableOrange uppercase tracking-widest">ABLE Assistant:</p>
                <p className="text-2xl font-bold text-white/90 leading-snug">
                  {aiResponse}
                </p>
              </div>
            )}

            {groundingLinks.length > 0 && (
              <div className="space-y-2 pt-4">
                 <p className="text-[10px] font-black text-white/40 uppercase tracking-widest">Search Result / Lyrics:</p>
                 <div className="flex flex-col gap-1">
                    {groundingLinks.slice(0, 2).map((link, i) => (
                      <a key={i} href={link.uri} target="_blank" rel="noopener noreferrer" className="text-xs font-bold text-ableOrange underline truncate">
                        {link.title}
                      </a>
                    ))}
                 </div>
              </div>
            )}

            {activeMedia && (
              <div className="pt-4 animate-bounce">
                 <button 
                  onClick={stopAudio}
                  className="px-6 py-2 bg-ableRed text-white font-black rounded-xl text-xs flex items-center gap-2"
                 >
                   ⏹ STOP PLAYBACK
                 </button>
                 <audio ref={audioRef} src={activeMedia} autoPlay hidden />
              </div>
            )}
          </div>

          <div className="flex flex-col items-center gap-6">
            <button 
              onClick={startListening}
              disabled={isListening}
              className={`w-36 h-36 rounded-full flex items-center justify-center text-7xl shadow-huge transition-all active:scale-90 ${isListening ? 'bg-ableRed animate-ping scale-110 shadow-ableRed/50' : 'bg-ableOrange shadow-ableOrange/50 hover:scale-110'}`}
              aria-label="Start Voice Chat"
            >
              🎙️
            </button>
            <p className="text-xs font-black uppercase tracking-[0.5em] text-ableOrange opacity-60">
              {isListening ? 'RECORDING' : 'TAP TO BEGIN CHAT'}
            </p>
          </div>
        </section>
      </div>
    </div>
  );
};

export default CommHub;

import React, { useState, useRef, useEffect } from 'react';
import { useAbility } from '../context/AbilityContext';
import SignLanguageAvatar from './SignLanguageAvatar';
import { GoogleGenAI } from '@google/genai';

const AICompanion: React.FC = () => {
  const { pad, speak } = useAbility();
  const [isVisionActive, setIsVisionActive] = useState(false);
  const [status, setStatus] = useState('STANDBY');
  const [chatInput, setChatInput] = useState('');
  const [lastAiMessage, setLastAiMessage] = useState('');
  const [isThinking, setIsThinking] = useState(false);
  const [groundingLinks, setGroundingLinks] = useState<{title: string, uri: string}[]>([]);

  const videoRef = useRef<HTMLVideoElement | null>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null);

  // Clean up camera on unmount
  useEffect(() => {
    return () => {
      if (mediaStreamRef.current) {
        mediaStreamRef.current.getTracks().forEach(t => t.stop());
      }
    };
  }, []);

  const toggleVision = async () => {
    if (isVisionActive) {
      if (mediaStreamRef.current) {
        mediaStreamRef.current.getTracks().forEach(t => t.stop());
        mediaStreamRef.current = null;
      }
      setIsVisionActive(false);
      setStatus('OFF');
      speak("Vision Hub deactivated.");
    } else {
      try {
        setStatus('WAKING UP...');

        // Try environment camera first, then fallback to any camera
        let stream: MediaStream;
        try {
          stream = await navigator.mediaDevices.getUserMedia({ 
            video: { 
              facingMode: { ideal: 'environment' }, 
              width: { ideal: 1920 },
              height: { ideal: 1080 }
            },
            audio: false 
          });
        } catch (e) {
          console.warn("Environment camera failed, trying default", e);
          stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: false });
        }

        mediaStreamRef.current = stream;

        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          // Ensure playback starts immediately
          videoRef.current.onloadedmetadata = () => {
            videoRef.current?.play().catch(e => console.error("Auto-play failed:", e));
          };
        }

        setIsVisionActive(true);
        setStatus('LIVE');
        speak("Vision Hub active. Point the lens at your surroundings.");
      } catch (err) {
        console.error("Camera Error:", err);
        setStatus('ERROR');
        speak("Camera failed. Please check permissions and ensure no other app is using the lens.");
      }
    }
  };

  const handleAction = async (msg?: string) => {
    const query = msg || chatInput;
    if (!query.trim()) return;

    setIsThinking(true);
    if (!msg) setChatInput('');
    setGroundingLinks([]);

    // Create fresh instance as per guidelines
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Context: Vision Hub. User query: "${query}". Provide a highly relevant, supportive response. 
        CRITICAL: Your response MUST NOT exceed two concise sentences. Use Google Search to identify objects, locations, or recent information accurately.`,
        config: {
          tools: [{ googleSearch: {} }],
          systemInstruction: "You are ABLE, a humanoid assistant for users with disabilities. Be exceptionally brief, direct, and supportive. Use clear, simple language. Never exceed two sentences."
        }
      });

      const resText = response.text || "I'm ready to help you.";
      setLastAiMessage(resText);
      speak(resText);

      // Extract search grounding links
      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
      if (chunks) {
        const links = chunks
          .filter(chunk => chunk.web)
          .map(chunk => ({ title: chunk.web!.title, uri: chunk.web!.uri }));
        setGroundingLinks(links);
      }
    } catch (e) {
      console.error("AI Error:", e);
      setLastAiMessage("Connectivity issue detected. Please tap to try again.");
      speak("Connection lost for a moment. Please try again.");
    } finally {
      setIsThinking(false);
    }
  };

  const runSimulation = (type: 'describe' | 'read' | 'simplify') => {
    if (!isVisionActive) return;
    setStatus('SCANNING...');

    const mocks = {
      describe: ["Open path detected. Door at 2 o'clock.", "Sign detected: Level 3 Lobby.", "Environment is quiet and well-lit."],
      read: ["Text found: 'Automatic Sliding Door'", "Warning: 'Step detected'", "Label identified as: 'Aspirin 500mg'"],
      simplify: ["This sign says wait here for help.", "The text is an instruction manual for the lift.", "Summary: Press the green button to start."]
    };

    const pick = mocks[type][Math.floor(Math.random() * 3)];
    setTimeout(() => {
      setStatus('LIVE');
      setLastAiMessage(pick);
      speak(pick);
    }, 800);
  };

  const handleSpeakInput = () => {
    if (chatInput.trim()) {
      speak(chatInput);
    }
  };

  return (
    <div className="flex flex-col space-y-8 py-6 w-full max-w-full overflow-x-hidden">
      <header className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6">
        <div className="space-y-1">
           <h2 className="text-5xl font-black text-ableYellow tracking-tighter uppercase leading-none">Vision Companion</h2>
           <div className="flex items-center space-x-3">
             <div className={`w-3 h-3 rounded-full ${isVisionActive ? 'bg-emerald-500 animate-pulse' : 'bg-white/10'}`}></div>
             <p className="text-[10px] font-black text-white/40 uppercase tracking-[0.5em]">{status}</p>
           </div>
        </div>

        <button 
          onClick={toggleVision}
          className={`px-10 py-5 rounded-huge font-black text-xl border-4 transition-all shadow-huge active:scale-95 ${isVisionActive ? 'bg-ableRed border-white text-white' : 'bg-ableYellow border-transparent text-ableBlack'}`}
        >
          {isVisionActive ? 'STOP LENS' : 'START VISION'}
        </button>
      </header>

      <div className="grid grid-cols-1 xl:grid-cols-12 gap-8 w-full">
        <div className="xl:col-span-8 bg-black border-8 border-ableYellow rounded-huge overflow-hidden relative aspect-video xl:aspect-auto xl:h-[650px] shadow-2xl flex items-center justify-center">
          {isVisionActive ? (
            <video 
              ref={videoRef} 
              autoPlay 
              playsInline 
              muted 
              className="w-full h-full object-cover scale-x-[-1]" 
            />
          ) : (
            <div className="flex flex-col items-center justify-center space-y-6">
               <div className="text-8xl opacity-10">👁️</div>
               <p className="text-sm font-black text-white/20 uppercase tracking-[0.3em]">Lens Standby</p>
            </div>
          )}

          <div className="absolute bottom-6 right-6 w-40 md:w-56 shadow-huge transition-transform hover:scale-105">
             <SignLanguageAvatar message={lastAiMessage} active={!!lastAiMessage} />
          </div>
        </div>

        <div className="xl:col-span-4 flex flex-col gap-6">
           <div className="bg-white/5 border-4 border-white/10 p-8 rounded-huge space-y-6 shadow-xl flex-1 flex flex-col justify-between overflow-hidden">
              <div className="flex justify-between items-center border-b-2 border-white/5 pb-4">
                <h3 className="text-xl font-black text-ableYellow uppercase tracking-widest">DNA Assistant</h3>
                {lastAiMessage && (
                  <button 
                    onClick={() => speak(lastAiMessage)}
                    className="w-10 h-10 bg-white/10 rounded-xl flex items-center justify-center hover:bg-ableYellow hover:text-ableBlack transition-all"
                    title="Repeat Audio"
                  >
                    🔊
                  </button>
                )}
              </div>

              <div className="flex-1 overflow-y-auto no-scrollbar py-4 space-y-4">
                {lastAiMessage && (
                  <div className="p-4 bg-white/5 rounded-2xl border-l-4 border-ableYellow animate-in slide-in-from-left-4">
                    <p className="text-white font-medium italic">"{lastAiMessage}"</p>
                  </div>
                )}

                {groundingLinks.length > 0 && (
                  <div className="space-y-2">
                    <p className="text-[10px] font-black text-white/40 uppercase tracking-widest">Sources Found:</p>
                    <div className="flex flex-col gap-2">
                      {groundingLinks.slice(0, 3).map((link, i) => (
                        <a 
                          key={i} 
                          href={link.uri} 
                          target="_blank" 
                          rel="noopener noreferrer" 
                          className="text-xs font-bold text-ableYellow underline truncate hover:text-white transition-colors"
                        >
                          {link.title}
                        </a>
                      ))}
                    </div>
                  </div>
                )}

                <textarea 
                  value={chatInput}
                  onChange={(e) => setChatInput(e.target.value)}
                  placeholder="Ask me to identify or describe..."
                  className="w-full bg-black/40 border-4 border-white/10 rounded-2xl p-5 text-lg font-bold text-white outline-none focus:border-ableYellow transition-all resize-none h-[120px]"
                />
              </div>

              <div className="grid grid-cols-2 gap-3 pt-4">
                <button 
                  onClick={() => handleAction()}
                  disabled={isThinking || !chatInput.trim()}
                  className="py-5 bg-white text-ableBlack rounded-2xl font-black text-lg shadow-huge active:scale-95 transition-all disabled:opacity-20"
                >
                  {isThinking ? '...' : 'ANALYZE'}
                </button>
                <button 
                  onClick={handleSpeakInput}
                  disabled={!chatInput.trim()}
                  className="py-5 bg-ableOrange text-white rounded-2xl font-black text-lg shadow-huge active:scale-95 transition-all disabled:opacity-20 border-2 border-white/10"
                >
                  SPEAK
                </button>
              </div>
           </div>

           <div className="flex flex-col gap-3">
              <button 
                disabled={!isVisionActive}
                onClick={() => runSimulation('describe')}
                className="w-full py-7 bg-ableYellow text-ableBlack rounded-huge font-black text-lg shadow-huge active:scale-95 transition-all disabled:opacity-20 flex items-center justify-center gap-4 border-4 border-white"
              >
                <span className="text-3xl">🧭</span>
                DESCRIBE SCENE
              </button>
              <button 
                disabled={!isVisionActive}
                onClick={() => runSimulation('read')}
                className="w-full py-7 bg-ableOrange text-white rounded-huge font-black text-lg shadow-huge active:scale-95 transition-all disabled:opacity-20 flex items-center justify-center gap-4 border-4 border-white/10"
              >
                <span className="text-3xl">📖</span>
                READ TEXT
              </button>
              <button 
                disabled={!isVisionActive}
                onClick={() => runSimulation('simplify')}
                className="w-full py-7 bg-ableSlate text-white rounded-huge font-black text-lg shadow-huge active:scale-95 transition-all disabled:opacity-20 flex items-center justify-center gap-4 border-4 border-white/5"
              >
                <span className="text-3xl">🧩</span>
                SIMPLIFY INFO
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

