    if (!userText.trim()) return;

    // Easter Eggs Check
    const lowerText = userText.toLowerCase();
    if (lowerText.includes('who is lakshita')) {
      const resp = "Lakshita is my brilliant creator. She designed me to adapt to your world.";
      setAiResponse(resp);
      setIfiStatus('AI Ready');
      speak(resp);
      return;
    }
    if (lowerText.includes('who is naksh')) {
      const resp = "Naksh is my primary architect and creator. He designed my synaptic core.";
      setAiResponse(resp);
      setIfiStatus('AI Ready');
      speak(resp);
      return;
    }

    setIfiStatus('Searching...');
    setGroundingLinks([]);
    setActiveMedia(null);

    // Create fresh instance for each turn
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `User says: "${userText}". 
        Context: The user has ${pad.visual} vision and ${pad.speech} style. 
        If asked to "play a song", use Google Search to find direct audio links or lyrics. 
        If audio is found, mention it. If only lyrics are found, state you will recite them.
        CRITICAL: Limit response to one or two sentences.`,
        config: {
          tools: [{ googleSearch: {} }],
          systemInstruction: "You are ABLE, an adaptive assistant. For music requests, find lyrics or audio via search. If reciting lyrics, use a humanoid, supportive tone. Be extremely brief, max 2 sentences."
        }
      });

      const textResponse = response.text || "I'm here and ready to help.";
      setAiResponse(textResponse);
      setIfiStatus('AI Ready');
      speak(textResponse);

      // Handle grounding metadata for music/info
      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
      if (chunks) {
        const links = chunks
          .filter(chunk => chunk.web)
          .map(chunk => ({ title: chunk.web!.title, uri: chunk.web!.uri }));
        setGroundingLinks(links);

        // Attempt to find playable audio if requested
        if (lowerText.includes('play') || lowerText.includes('song')) {
          const playable = links.find(l => l.uri.includes('.mp3') || l.uri.includes('audio') || l.uri.includes('streaming'));
          if (playable) {
            setActiveMedia(playable.uri);
          } else {
            // If no playable audio, the AI likely provided lyrics in textResponse or mention of them.
            // Recitation is handled by 'speak(textResponse)' above.
          }
        }
      }

    } catch (error) {
      console.error("AI Error:", error);
      setIfiStatus('Sync Error');
      speak("Connection lost for a moment. Please tap to try again.");
    }
  };

  const startListening = useCallback(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      const msg = "Voice input is not supported in this browser.";
      speak(msg);
      return;
    }

    if (recognitionRef.current) {
      try { recognitionRef.current.stop(); } catch(e) {}
    }

    const recognition = new SpeechRecognition();
    recognition.lang = 'en-US';
    recognition.interimResults = true;
    recognition.continuous = false;
    recognitionRef.current = recognition;

    recognition.onstart = () => {
      setIsListening(true);
      setIfiStatus('Listening...');
      setTranscript('');
      setAiResponse('');
    };

    recognition.onresult = (event: any) => {
      let currentTranscript = '';
      for (let i = event.resultIndex; i < event.results.length; ++i) {
        currentTranscript += event.results[i][0].transcript;
      }
      setTranscript(currentTranscript);
    };

    recognition.onerror = (event: any) => {
      setIsListening(false);
      let errorMsg = "Speech recognition error.";

      switch(event.error) {
        case 'not-allowed':
          errorMsg = "Microphone access is blocked. Please check your browser settings.";
          break;
        case 'network':
          errorMsg = "Network connection issue detected. Please check your internet.";
          break;
        case 'no-speech':
          errorMsg = "I didn't hear anything. Please try speaking again.";
          break;
        default:
          errorMsg = `Connection issue: ${event.error}`;
      }

      setIfiStatus('Error');
      speak(errorMsg);
    };

    recognition.onend = () => {
      setIsListening(false);
      if (transcript.trim() && ifiStatus !== 'Error') {
        setIfiStatus('Processing...');
      } else if (ifiStatus !== 'Error') {
        setIfiStatus('Standby');
      }
    };

    recognition.start();
  }, [speak, transcript, ifiStatus]);

  useEffect(() => {
    if (!isListening && transcript.trim() && ifiStatus === 'Processing...') {
      processWithAI(transcript);
    }
  }, [isListening, transcript, ifiStatus]);

  const soundboard = [
    { label: 'YES', text: "Yes, that is correct.", color: 'bg-emerald-500' },
    { label: 'NO', text: "No, thank you.", color: 'bg-ableRed' },
    { label: 'WAIT', text: "Please wait, I am finishing my thought.", color: 'bg-ableOrange' },
    { label: 'THANKS', text: "Thank you for your patience.", color: 'bg-ableYellow text-ableBlack' }
  ];

  const stopAudio = () => {
    if (audioRef.current) {
      audioRef.current.pause();
      setActiveMedia(null);
    }
  };

  return (
    <div className="space-y-12 py-10 animate-in slide-in-from-left-10 duration-700">
      <header className="space-y-4">
        <h2 className="text-6xl font-black text-ableYellow tracking-tighter">VOICE HUB.</h2>
        <p className="text-2xl font-bold text-white/60">Real conversation at your pace. ABLE hears your intent and responds with empathy.</p>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
        <section className="bg-ableBlack border-8 border-ableYellow p-12 rounded-huge shadow-2xl space-y-10">
          <div className="space-y-2">
            <h3 className="text-4xl font-black text-ableYellow uppercase">Speak for Me</h3>
            <p className="text-xl font-medium opacity-60">Shortcuts for immediate communication.</p>
          </div>

          <div className="grid grid-cols-2 gap-4">
            {soundboard.map(btn => (
              <button 
                key={btn.label}
                onClick={() => speak(btn.text)}
                className={`${btn.color} py-10 rounded-3xl font-black text-3xl shadow-xl active:scale-95 transition-all text-white border-4 border-white/20 hover:brightness-110`}
              >
                {btn.label}
              </button>
            ))}
          </div>

          <div className="pt-6 space-y-4">
            <input 
              type="text"
              value={speakText}
              onChange={(e) => setSpeakText(e.target.value)}
              placeholder="TYPE YOUR MESSAGE..."
              className="w-full bg-white/5 border-4 border-white/20 rounded-huge px-8 py-6 text-2xl font-black text-white outline-none focus:border-ableYellow transition-all"
            />
            <button 
              onClick={handleSpeak}
              className="w-full py-8 bg-white text-ableBlack rounded-huge font-black text-3xl shadow-huge active:scale-95 transition-all hover:bg-ableYellow"
            >
              SPEAK AS ME
            </button>
          </div>
        </section>

        <section className="bg-ableBlack border-8 border-ableOrange p-12 rounded-huge shadow-2xl flex flex-col justify-between space-y-10">
           <div className="flex justify-between items-start">
            <div className="space-y-2">
              <h3 className="text-4xl font-black text-ableOrange uppercase">AI VOICE CHAT</h3>
              <p className="text-xl font-medium opacity-60">Ask me to "Play a song..."</p>
            </div>
            <div className={`px-4 py-2 border-2 rounded-xl text-[10px] font-black tracking-widest transition-all ${isListening ? 'bg-ableRed border-white text-white animate-pulse' : 'bg-ableOrange/10 border-ableOrange/40 text-ableOrange'}`}>
              {ifiStatus.toUpperCase()}
            </div>
          </div>

          <div className="flex-1 bg-white/5 border-4 border-white/10 rounded-3xl p-10 flex flex-col justify-center space-y-8 min-h-[300px] overflow-hidden">
            <div className="space-y-3">
              <p className="text-xs font-black text-white/30 uppercase tracking-widest">User Intent:</p>
              <p className={`text-3xl font-black leading-tight transition-opacity ${transcript ? 'text-white' : 'text-white/10 italic'}`}>
                {transcript || (isListening ? 'Listening...' : 'Tap microphone to start...')}
              </p>
            </div>

            {aiResponse && (
              <div className="space-y-3 pt-8 border-t-4 border-white/5 animate-in fade-in slide-in-from-bottom-4">
                <p className="text-xs font-black text-ableOrange uppercase tracking-widest">ABLE Assistant:</p>
                <p className="text-2xl font-bold text-white/90 leading-snug">
                  {aiResponse}
                </p>
              </div>
            )}

            {groundingLinks.length > 0 && (
              <div className="space-y-2 pt-4">
                 <p className="text-[10px] font-black text-white/40 uppercase tracking-widest">Search Sources:</p>
                 <div className="flex flex-col gap-1">
                    {groundingLinks.slice(0, 2).map((link, i) => (
                      <a key={i} href={link.uri} target="_blank" rel="noopener noreferrer" className="text-xs font-bold text-ableOrange underline truncate">
                        {link.title}
                      </a>
                    ))}
                 </div>
              </div>
            )}

            {activeMedia && (
              <div className="pt-4 animate-bounce">
                 <button 
                  onClick={stopAudio}
                  className="px-6 py-2 bg-ableRed text-white font-black rounded-xl text-xs flex items-center gap-2"
                 >
                   ⏹ STOP PLAYBACK
                 </button>
                 <audio ref={audioRef} src={activeMedia} autoPlay hidden />
              </div>
            )}
          </div>

          <div className="flex flex-col items-center gap-6">
            <button 
              onClick={startListening}
              disabled={isListening}
              className={`w-36 h-36 rounded-full flex items-center justify-center text-7xl shadow-huge transition-all active:scale-90 ${isListening ? 'bg-ableRed animate-ping scale-110 shadow-ableRed/50' : 'bg-ableOrange shadow-ableOrange/50 hover:scale-110'}`}
              aria-label="Start Voice Chat"
            >
              🎙️
            </button>
            <p className="text-xs font-black uppercase tracking-[0.5em] text-ableOrange opacity-60">
              {isListening ? 'RECORDING' : 'TAP TO BEGIN CHAT'}
            </p>
          </div>
        </section>
      </div>
    </div>
  );
};

export default CommHub;

import React, { useState, useRef, useEffect } from 'react';
import { useAbility } from '../context/AbilityContext';
import SignLanguageAvatar from './SignLanguageAvatar';
import { GoogleGenAI } from '@google/genai';

const AICompanion: React.FC = () => {
  const { pad, speak } = useAbility();
  const [isVisionActive, setIsVisionActive] = useState(false);
  const [status, setStatus] = useState('STANDBY');
  const [chatInput, setChatInput] = useState('');
  const [lastAiMessage, setLastAiMessage] = useState('');
  const [isThinking, setIsThinking] = useState(false);
  const [groundingLinks, setGroundingLinks] = useState<{title: string, uri: string}[]>([]);

  const videoRef = useRef<HTMLVideoElement | null>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null);

  // Clean up camera on unmount
  useEffect(() => {
    return () => {
      if (mediaStreamRef.current) {
        mediaStreamRef.current.getTracks().forEach(t => t.stop());
      }
    };
  }, []);

  const toggleVision = async () => {
    if (isVisionActive) {
      if (mediaStreamRef.current) {
        mediaStreamRef.current.getTracks().forEach(t => t.stop());
        mediaStreamRef.current = null;
      }
      setIsVisionActive(false);
      setStatus('OFF');
      speak("Vision Hub deactivated.");
    } else {
      try {
        setStatus('WAKING UP...');

        // Robust camera constraints with fallbacks
        const constraints = {
          video: { 
            facingMode: { ideal: 'environment' }, 
            width: { ideal: 1280 },
            height: { ideal: 720 }
          },
          audio: false 
        };

        let stream: MediaStream;
        try {
          stream = await navigator.mediaDevices.getUserMedia(constraints);
        } catch (e) {
          console.warn("Ideal constraints failed, trying basic video", e);
          stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: false });
        }

        mediaStreamRef.current = stream;

        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          // Ensure playback starts
          videoRef.current.onloadedmetadata = () => {
            videoRef.current?.play().catch(e => console.error("Playback error:", e));
          };
        }

        setIsVisionActive(true);
        setStatus('LIVE');
        speak("Vision Hub active. Point the lens at your surroundings.");
      } catch (err) {
        console.error("Camera Access Error:", err);
        setStatus('PERMISSION ERROR');
        speak("I couldn't access your camera. Please check your browser permissions.");
      }
    }
  };

  const handleAction = async (msg?: string) => {
    const query = msg || chatInput;
    if (!query.trim()) return;

    setIsThinking(true);
    if (!msg) setChatInput('');
    setGroundingLinks([]);

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Context: Vision Hub. User query: "${query}". 
        Analyze the intent and provide a supportive, humanoid response. 
        CRITICAL: Limit your response to exactly one or two concise sentences. 
        Use Google Search if the user asks for identification or information about things they might be seeing.`,
        config: {
          tools: [{ googleSearch: {} }],
          systemInstruction: "You are ABLE, an adaptive AI companion for people with disabilities. You are supportive, humanoid, and extremely concise. Never exceed two sentences. Use search to be accurate."
        }
      });

      const resText = response.text || "I'm here to help you navigate.";
      setLastAiMessage(resText);
      speak(resText);

      // Extract search grounding links
      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
      if (chunks) {
        const links = chunks
          .filter(chunk => chunk.web)
          .map(chunk => ({ title: chunk.web!.title, uri: chunk.web!.uri }));
        setGroundingLinks(links);
      }
    } catch (e) {
      console.error("AI Error:", e);
      setLastAiMessage("I'm having trouble connecting to my neural core. Please try again.");
      speak("Connection issue. Please tap analyze again.");
    } finally {
      setIsThinking(false);
    }
  };

  const runSimulation = (type: 'describe' | 'read' | 'simplify') => {
    if (!isVisionActive) return;
    setStatus('SCANNING...');

    const mocks = {
      describe: ["Open path detected. Door at 2 o'clock.", "Sign detected: Level 3 Lobby.", "The area is well-lit and quiet."],
      read: ["Text found: 'Automatic Sliding Door'", "Warning: 'Caution: Low Ceiling'", "Label: 'Daily Vitamin C'"],
      simplify: ["This sign says wait here for the next available agent.", "These instructions say to push the blue handle down.", "Summary: Authorized personnel only."]
    };

    const pick = mocks[type][Math.floor(Math.random() * 3)];
    setTimeout(() => {
      setStatus('LIVE');
      setLastAiMessage(pick);
      speak(pick);
    }, 800);
  };

  return (
    <div className="flex flex-col space-y-8 py-6 w-full max-w-full overflow-x-hidden">
      <header className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6">
        <div className="space-y-1">
           <h2 className="text-5xl font-black text-ableYellow tracking-tighter uppercase leading-none italic">Vision Companion</h2>
           <div className="flex items-center space-x-3">
             <div className={`w-3 h-3 rounded-full ${isVisionActive ? 'bg-emerald-500 animate-pulse' : 'bg-white/10'}`}></div>
             <p className="text-[10px] font-black text-white/40 uppercase tracking-[0.5em]">{status}</p>
           </div>
        </div>

        <button 
          onClick={toggleVision}
          className={`px-10 py-5 rounded-huge font-black text-xl border-4 transition-all shadow-huge active:scale-95 ${isVisionActive ? 'bg-ableRed border-white text-white' : 'bg-ableYellow border-transparent text-ableBlack'}`}
        >
          {isVisionActive ? 'STOP LENS' : 'START VISION'}
        </button>
      </header>

      <div className="grid grid-cols-1 xl:grid-cols-12 gap-8 w-full">
        <div className="xl:col-span-8 bg-black border-8 border-ableYellow rounded-huge overflow-hidden relative aspect-video xl:aspect-auto xl:h-[650px] shadow-2xl flex items-center justify-center">
          {isVisionActive ? (
            <video 
              ref={videoRef} 
              autoPlay 
              playsInline 
              muted 
              className="w-full h-full object-cover scale-x-[-1]" 
            />
          ) : (
            <div className="flex flex-col items-center justify-center space-y-6">
               <div className="text-8xl opacity-10">👁️</div>
               <p className="text-sm font-black text-white/20 uppercase tracking-[0.3em]">Lens Standby</p>
            </div>
          )}

          <div className="absolute bottom-6 right-6 w-40 md:w-56 shadow-huge transition-transform hover:scale-105">
             <SignLanguageAvatar message={lastAiMessage} active={!!lastAiMessage} />
          </div>
        </div>

        <div className="xl:col-span-4 flex flex-col gap-6">
           <div className="bg-white/5 border-4 border-white/10 p-8 rounded-huge space-y-6 shadow-xl flex-1 flex flex-col justify-between overflow-hidden">
              <div className="flex justify-between items-center border-b-2 border-white/5 pb-4">
                <h3 className="text-xl font-black text-ableYellow uppercase tracking-widest">DNA Analysis</h3>
                {lastAiMessage && (
                  <button 
                    onClick={() => speak(lastAiMessage)}
                    className="w-10 h-10 bg-white/10 rounded-xl flex items-center justify-center hover:bg-ableYellow hover:text-ableBlack transition-all text-lg"
                  >
                    🔊
                  </button>
                )}
              </div>

              <div className="flex-1 overflow-y-auto no-scrollbar py-4 space-y-6">
                {lastAiMessage && (
                  <div className="p-6 bg-white/5 rounded-3xl border-l-8 border-ableYellow animate-in slide-in-from-left-4">
                    <p className="text-white text-xl font-bold leading-tight">"{lastAiMessage}"</p>
                  </div>
                )}

                {groundingLinks.length > 0 && (
                  <div className="space-y-3">
                    <p className="text-[10px] font-black text-white/40 uppercase tracking-widest">Contextual Sources:</p>
                    <div className="flex flex-col gap-2">
                      {groundingLinks.slice(0, 3).map((link, i) => (
                        <a 
                          key={i} 
                          href={link.uri} 
                          target="_blank" 
                          rel="noopener noreferrer" 
                          className="text-sm font-bold text-ableYellow underline truncate hover:text-white transition-colors block"
                        >
                          {link.title}
                        </a>
                      ))}
                    </div>
                  </div>
                )}

                <div className="space-y-4">
                  <textarea 
                    value={chatInput}
                    onChange={(e) => setChatInput(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleAction())}
                    placeholder="Ask ABLE what you see..."
                    className="w-full bg-black/40 border-4 border-white/10 rounded-2xl p-6 text-lg font-bold text-white outline-none focus:border-ableYellow transition-all resize-none h-[120px]"
                  />
                  <div className="grid grid-cols-2 gap-4">
                    <button 
                      onClick={() => handleAction()}
                      disabled={isThinking || !chatInput.trim()}
                      className="py-5 bg-white text-ableBlack rounded-2xl font-black text-xl shadow-huge active:scale-95 transition-all disabled:opacity-20"
                    >
                      {isThinking ? '...' : 'ANALYZE'}
                    </button>
                    <button 
                      onClick={() => speak(chatInput)}
                      disabled={!chatInput.trim()}
                      className="py-5 bg-ableOrange text-white rounded-2xl font-black text-xl shadow-huge active:scale-95 transition-all disabled:opacity-20 border-2 border-white/10"
                    >
                      SPEAK
                    </button>
                  </div>
                </div>
              </div>
           </div>

           <div className="grid grid-cols-1 gap-3">
              <button 
                disabled={!isVisionActive}
                onClick={() => runSimulation('describe')}
                className="w-full py-6 bg-ableYellow text-ableBlack rounded-huge font-black text-lg shadow-huge active:scale-95 transition-all disabled:opacity-20 flex items-center justify-center gap-4 border-4 border-white"
              >
                <span className="text-2xl">🧭</span>
                DESCRIBE
              </button>
              <button 
                disabled={!isVisionActive}
                onClick={() => runSimulation('read')}
                className="w-full py-6 bg-ableOrange text-white rounded-huge font-black text-lg shadow-huge active:scale-95 transition-all disabled:opacity-20 flex items-center justify-center gap-4 border-4 border-white/10"
              >
                <span className="text-2xl">📖</span>
                READ TEXT
              </button>
              <button 
                disabled={!isVisionActive}
                onClick={() => runSimulation('simplify')}
                className="w-full py-6 bg-ableSlate text-white rounded-huge font-black text-lg shadow-huge active:scale-95 transition-all disabled:opacity-20 flex items-center justify-center gap-4 border-4 border-white/5"
              >
                <span className="text-2xl">🧩</span>
                SIMPLIFY
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

export default AICompanion;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { useAbility } from '../context/AbilityContext';
import { GoogleGenAI } from '@google/genai';

const CommHub: React.FC = () => {
  const { pad, speak } = useAbility();
  const [speakText, setSpeakText] = useState('');
  const [isListening, setIsListening] = useState(false);
  const [transcript, setTranscript] = useState('');
  const [ifiStatus, setIfiStatus] = useState('Standby');
  const [aiResponse, setAiResponse] = useState('');
  const [groundingLinks, setGroundingLinks] = useState<{title: string, uri: string}[]>([]);
  const [activeMedia, setActiveMedia] = useState<string | null>(null);
  const recognitionRef = useRef<any>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  const handleSpeak = () => {
    if (!speakText) return;
    speak(speakText);
    setSpeakText('');
  };

  const processWithAI = async (userText: string) => {
    if (!userText.trim()) return;

    setIfiStatus('Synchronizing...');
    setGroundingLinks([]);
    setActiveMedia(null);

    const lowerText = userText.toLowerCase();

    // Easter Egg logic
    if (lowerText.includes('who is lakshita')) {
      const resp = "Lakshita is my brilliant creator. She built me to wait for you, always.";
      setAiResponse(resp);
      setIfiStatus('AI Ready');
      speak(resp);
      return;
    }
    if (lowerText.includes('who is naksh')) {
      const resp = "Naksh is my primary architect and creator. He designed my empathetic core.";
      setAiResponse(resp);
      setIfiStatus('AI Ready');
      speak(resp);
      return;
    }

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    try {
      const isMusicRequest = lowerText.includes('play') || lowerText.includes('song') || lowerText.includes('music');

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `User says: "${userText}". 
        Context: The user has ${pad.visual} vision and ${pad.speech} style. 
        ${isMusicRequest ? 'The user is requesting music. Use Google Search to find direct audio URLs (.mp3, .wav) or full lyrics if audio is not found.' : 'Engage in supportive, humanoid conversation.'}
        CRITICAL: Limit your response to strictly one or two concise sentences. 
        If you find lyrics, state you will recite them for them.`,
        config: {
          tools: [{ googleSearch: {} }],
          systemInstruction: "You are ABLE, an adaptive assistant. You support users with disabilities with humanoid empathy. Be extremely brief (max 2 sentences). For music, provide either audio links or recite lyrics humanely."
        }
      });

      const textResponse = response.text || "I'm listening. How can I support you?";
      setAiResponse(textResponse);
      setIfiStatus('AI Ready');
      speak(textResponse);

      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
      if (chunks) {
        const links = chunks
          .filter(chunk => chunk.web)
          .map(chunk => ({ title: chunk.web!.title, uri: chunk.web!.uri }));
        setGroundingLinks(links);

        if (isMusicRequest) {
          // Look for direct audio links in grounding or text
          const audioLink = links.find(l => 
            l.uri.endsWith('.mp3') || 
            l.uri.endsWith('.wav') || 
            l.uri.includes('audio-stream') ||
            l.uri.includes('mp3-link')
          );

          if (audioLink) {
            setActiveMedia(audioLink.uri);
          }
        }
      }

    } catch (error) {
      console.error("AI Error:", error);
      setIfiStatus('Sync Error');
      speak("My connection skipped. Please try that again.");
    }
  };

  const startListening = useCallback(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      speak("Voice input is not supported here.");
      return;
    }

    if (recognitionRef.current) {
      try { recognitionRef.current.stop(); } catch(e) {}
    }

    const recognition = new SpeechRecognition();
    recognition.lang = 'en-US';
    recognition.interimResults = true;
    recognition.continuous = false;
    recognitionRef.current = recognition;

    recognition.onstart = () => {
      setIsListening(true);
      setIfiStatus('Listening...');
      setTranscript('');
      setAiResponse('');
    };

    recognition.onresult = (event: any) => {
      let currentTranscript = '';
      for (let i = event.resultIndex; i < event.results.length; ++i) {
        currentTranscript += event.results[i][0].transcript;
      }
      setTranscript(currentTranscript);
    };

    recognition.onerror = (event: any) => {
      setIsListening(false);
      let errorMsg = "Speech error.";

      switch(event.error) {
        case 'not-allowed':
          errorMsg = "Microphone access is blocked. Check your browser settings.";
          break;
        case 'network':
          errorMsg = "Network connection issue. Please check your internet.";
          break;
        case 'no-speech':
          errorMsg = "I didn't hear anything. Let's try again.";
          break;
        default:
          errorMsg = `Interaction issue: ${event.error}`;
      }

      setIfiStatus('Error');
      speak(errorMsg);
    };

    recognition.onend = () => {
      setIsListening(false);
      if (transcript.trim() && ifiStatus !== 'Error') {
        setIfiStatus('Processing...');
      } else if (ifiStatus !== 'Error') {
        setIfiStatus('Standby');
      }
    };

    try {
      recognition.start();
    } catch (e) {
      console.error(e);
      setIfiStatus('Error');
    }
  }, [speak, transcript, ifiStatus]);

  useEffect(() => {
    if (!isListening && transcript.trim() && ifiStatus === 'Processing...') {
      processWithAI(transcript);
    }
  }, [isListening, transcript, ifiStatus]);

  const soundboard = [
    { label: 'YES', text: "Yes, that is correct.", color: 'bg-emerald-500' },
    { label: 'NO', text: "No, thank you.", color: 'bg-ableRed' },
    { label: 'WAIT', text: "Please wait, I'm thinking.", color: 'bg-ableOrange' },
    { label: 'THANKS', text: "Thank you for your help.", color: 'bg-ableYellow text-ableBlack' }
  ];

  return (
    <div className="space-y-12 py-10 animate-in slide-in-from-left-10 duration-700">
      <header className="space-y-4">
        <h2 className="text-6xl font-black text-ableYellow tracking-tighter italic">VOICE HUB.</h2>
        <p className="text-2xl font-bold text-white/60">Humanoid chat at your speed. ABLE listens for your intent, not your execution.</p>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
        <section className="bg-ableBlack border-8 border-ableYellow p-12 rounded-huge shadow-2xl space-y-10">
          <div className="space-y-2">
            <h3 className="text-4xl font-black text-ableYellow uppercase">Speak for Me</h3>
            <p className="text-xl font-medium opacity-60">Instant shortcuts for communication.</p>
          </div>

          <div className="grid grid-cols-2 gap-4">
            {soundboard.map(btn => (
              <button 
                key={btn.label}
                onClick={() => speak(btn.text)}
                className={`${btn.color} py-8 rounded-3xl font-black text-3xl shadow-xl active:scale-95 transition-all text-white border-4 border-white/20 hover:brightness-110`}
              >
                {btn.label}
              </button>
            ))}
          </div>

          <div className="pt-6 space-y-4">
            <input 
              type="text"
              value={speakText}
              onChange={(e) => setSpeakText(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSpeak()}
              placeholder="TYPE YOUR INTENT..."
              className="w-full bg-white/5 border-4 border-white/20 rounded-huge px-8 py-6 text-2xl font-black text-white outline-none focus:border-ableYellow transition-all"
            />
            <div className="grid grid-cols-2 gap-4">
              <button 
                onClick={handleSpeak}
                className="py-8 bg-white text-ableBlack rounded-huge font-black text-2xl shadow-huge active:scale-95 transition-all hover:bg-ableYellow"
              >
                SPEAK
              </button>
              <button 
                onClick={() => processWithAI(speakText)}
                className="py-8 bg-ableSlate text-white rounded-huge font-black text-2xl shadow-huge active:scale-95 transition-all border-4 border-white/10"
              >
                AI CHAT
              </button>
            </div>
          </div>
        </section>

        <section className="bg-ableBlack border-8 border-ableOrange p-12 rounded-huge shadow-2xl flex flex-col justify-between space-y-10 min-h-[600px]">
           <div className="flex justify-between items-start">
            <div className="space-y-2">
              <h3 className="text-4xl font-black text-ableOrange uppercase tracking-tighter">Synaptic Core</h3>
              <p className="text-xl font-medium opacity-60">"Play a song" or chat with me.</p>
            </div>
            <div className={`px-4 py-2 border-2 rounded-xl text-[10px] font-black tracking-widest transition-all ${isListening ? 'bg-ableRed border-white text-white animate-pulse' : 'bg-ableOrange/10 border-ableOrange/40 text-ableOrange'}`}>
              {ifiStatus.toUpperCase()}
            </div>
          </div>

          <div className="flex-1 bg-white/5 border-4 border-white/10 rounded-3xl p-10 flex flex-col justify-center space-y-8 overflow-hidden relative">
            <div className="space-y-3">
              <p className="text-xs font-black text-white/30 uppercase tracking-widest">Your Intent:</p>
              <p className={`text-3xl font-black leading-tight transition-opacity ${transcript ? 'text-white' : 'text-white/10 italic'}`}>
                {transcript || (isListening ? 'Listening...' : 'Tap to start conversation...')}
              </p>
            </div>

            {aiResponse && (
              <div className="space-y-3 pt-8 border-t-4 border-white/5 animate-in fade-in slide-in-from-bottom-4">
                <p className="text-xs font-black text-ableOrange uppercase tracking-widest">ABLE AI:</p>
                <p className="text-2xl font-bold text-white/90 leading-snug italic">
                  "{aiResponse}"
                </p>
              </div>
            )}

            {groundingLinks.length > 0 && (
              <div className="space-y-3 pt-6 border-t-4 border-white/5">
                 <p className="text-[10px] font-black text-white/40 uppercase tracking-widest">Verified Sources:</p>
                 <div className="flex flex-col gap-2">
                    {groundingLinks.slice(0, 2).map((link, i) => (
                      <a key={i} href={link.uri} target="_blank" rel="noopener noreferrer" className="text-xs font-bold text-ableOrange underline truncate block hover:text-white transition-colors">
                        {link.title}
                      </a>
                    ))}
                 </div>
              </div>
            )}

            {activeMedia && (
              <div className="absolute top-4 right-4 animate-bounce">
                 <button 
                  onClick={() => { audioRef.current?.pause(); setActiveMedia(null); }}
