import React, { useState, useRef, useEffect } from 'react';
import { useAbility } from '../context/AbilityContext';
import SignLanguageAvatar from './SignLanguageAvatar';
import { GoogleGenAI, Chat } from '@google/genai';

interface ChatMessage {
  role: 'user' | 'assistant';
  text: string;
}

const AICompanion: React.FC = () => {
  const { pad, speak } = useAbility();
  const [isVisionActive, setIsVisionActive] = useState(false);
  const [status, setStatus] = useState('STANDBY');
  const [chatInput, setChatInput] = useState('');
  const [history, setHistory] = useState<ChatMessage[]>([]);
  const [isThinking, setIsThinking] = useState(false);
  const [groundingLinks, setGroundingLinks] = useState<{title: string, uri: string}[]>([]);

  const videoRef = useRef<HTMLVideoElement | null>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null);
  const chatSessionRef = useRef<Chat | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  // Auto-scroll history
  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [history]);

  // Clean up camera on unmount
  useEffect(() => {
    return () => {
      if (mediaStreamRef.current) {
        mediaStreamRef.current.getTracks().forEach(t => t.stop());
      }
    };
  }, []);

  const initChat = () => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    chatSessionRef.current = ai.chats.create({
      model: 'gemini-3-flash-preview',
      config: {
        systemInstruction: "You are ABLE, an adaptive AI for disabled users. You are providing vision assistance. Be humanoid, concise (max 2 sentences), and use search to identify what you see. Remember previous context of the conversation.",
        tools: [{ googleSearch: {} }]
      }
    });
  };

  const toggleVision = async () => {
    if (isVisionActive) {
      if (mediaStreamRef.current) {
        mediaStreamRef.current.getTracks().forEach(t => t.stop());
        mediaStreamRef.current = null;
      }
      setIsVisionActive(false);
      setStatus('OFF');
      speak("Vision Hub deactivated.");
    } else {
      try {
        setStatus('WAKING UP...');
        if (!chatSessionRef.current) initChat();

        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment', width: 1280, height: 720 },
          audio: false 
        });

        mediaStreamRef.current = stream;
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          videoRef.current.play();
        }

        setIsVisionActive(true);
        setStatus('LIVE');
        speak("Vision Hub active. I am watching with you.");
      } catch (err) {
        console.error("Camera Error:", err);
        setStatus('ERROR');
        speak("I couldn't access the camera. Check your permissions.");
      }
    }
  };

  const handleSendMessage = async (msg?: string) => {
    const query = msg || chatInput;
    if (!query.trim()) return;

    setIsThinking(true);
    if (!msg) setChatInput('');
    setGroundingLinks([]);

    // Add user message to local history
    setHistory(prev => [...prev, { role: 'user', text: query }]);

    try {
      if (!chatSessionRef.current) initChat();

      const response = await chatSessionRef.current!.sendMessage({ message: query });
      const resText = response.text || "I'm analyzing the view.";

      setHistory(prev => [...prev, { role: 'assistant', text: resText }]);
      speak(resText);

      // Extract search grounding links
      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
      if (chunks) {
        const links = chunks
          .filter(chunk => chunk.web)
          .map(chunk => ({ title: chunk.web!.title, uri: chunk.web!.uri }));
        setGroundingLinks(links);
      }
    } catch (e) {
      console.error("AI Error:", e);
      setHistory(prev => [...prev, { role: 'assistant', text: "Connection skipped. Try again?" }]);
      speak("I lost my connection for a moment.");
    } finally {
      setIsThinking(false);
    }
  };

  const runSimulation = (type: string) => {
    const prompts = {
      describe: "Describe the scene you see through my camera.",
      read: "Read all the text and labels visible in the frame.",
      simplify: "Identify any hazards or accessibility features in view."
    };
    handleSendMessage((prompts as any)[type]);
  };

  return (
    <div className="flex flex-col space-y-8 py-6 w-full max-w-full overflow-x-hidden">
      <header className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6">
        <div className="space-y-1">
           <h2 className="text-5xl font-black text-ableYellow tracking-tighter uppercase leading-none italic">Vision Hub</h2>
           <div className="flex items-center space-x-3">
             <div className={`w-3 h-3 rounded-full ${isVisionActive ? 'bg-emerald-500 animate-pulse' : 'bg-white/10'}`}></div>
             <p className="text-[10px] font-black text-white/40 uppercase tracking-[0.5em]">{status}</p>
           </div>
        </div>

        <button 
          onClick={toggleVision}
          className={`px-10 py-5 rounded-huge font-black text-xl border-4 transition-all shadow-huge active:scale-95 ${isVisionActive ? 'bg-ableRed border-white text-white' : 'bg-ableYellow border-transparent text-ableBlack'}`}
        >
          {isVisionActive ? 'SHUT LENS' : 'OPEN VISION'}
        </button>
      </header>

      <div className="grid grid-cols-1 xl:grid-cols-12 gap-8 w-full">
        {/* Camera Feed */}
        <div className="xl:col-span-7 bg-black border-8 border-ableYellow rounded-huge overflow-hidden relative aspect-video shadow-2xl flex items-center justify-center">
          {isVisionActive ? (
            <video ref={videoRef} autoPlay playsInline muted className="w-full h-full object-cover scale-x-[-1]" />
          ) : (
            <div className="text-center space-y-4 opacity-20">
              <div className="text-9xl">👁️</div>
              <p className="font-black uppercase tracking-[0.5em]">Standby</p>
            </div>
          )}

          <div className="absolute bottom-6 right-6 w-40 md:w-56 shadow-huge">
             <SignLanguageAvatar 
               message={history[history.length-1]?.role === 'assistant' ? history[history.length-1].text : ''} 
               active={isThinking || (history[history.length-1]?.role === 'assistant')} 
             />
          </div>
        </div>

        {/* Chat Conversation */}
        <div className="xl:col-span-5 flex flex-col gap-6">
           <div className="bg-white/5 border-4 border-white/10 p-8 rounded-huge shadow-xl h-[550px] flex flex-col">
              <h3 className="text-xl font-black text-ableYellow uppercase tracking-widest border-b-2 border-white/5 pb-4 mb-4">Chat History</h3>

              <div ref={scrollRef} className="flex-1 overflow-y-auto no-scrollbar space-y-4 pr-2">
                {history.length === 0 && (
                  <p className="text-white/20 italic text-center py-20">No conversation yet. Open Vision to begin.</p>
                )}
                {history.map((msg, i) => (
                  <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-in slide-in-from-bottom-2`}>
                    <div className={`max-w-[85%] p-4 rounded-3xl font-bold text-lg ${msg.role === 'user' ? 'bg-white/10 text-white rounded-tr-none' : 'bg-ableYellow text-ableBlack rounded-tl-none shadow-lg'}`}>
                      {msg.text}
                    </div>
                  </div>
                ))}
                {isThinking && (
                  <div className="flex justify-start animate-pulse">
                    <div className="bg-white/10 text-white/40 p-4 rounded-3xl font-black italic">Thinking...</div>
                  </div>
                )}
              </div>

              <div className="mt-6 space-y-4">
                <div className="flex gap-2">
                  <input 
                    value={chatInput}
                    onChange={(e) => setChatInput(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
                    placeholder="Describe this for me..."
                    className="flex-1 bg-black/40 border-4 border-white/10 rounded-2xl p-4 text-white font-bold outline-none focus:border-ableYellow transition-all"
                  />
                  <button 
                    onClick={() => handleSendMessage()}
                    disabled={isThinking || !chatInput.trim()}
                    className="px-6 bg-white text-ableBlack rounded-2xl font-black disabled:opacity-20"
                  >
                    SEND
                  </button>
                </div>

                <div className="grid grid-cols-3 gap-2">
                  <button onClick={() => runSimulation('describe')} className="py-3 bg-ableSlate/20 text-xs font-black rounded-xl border border-white/10 hover:border-ableYellow">DESCRIBE</button>
                  <button onClick={() => runSimulation('read')} className="py-3 bg-ableSlate/20 text-xs font-black rounded-xl border border-white/10 hover:border-ableYellow">READ</button>
                  <button onClick={() => runSimulation('simplify')} className="py-3 bg-ableSlate/20 text-xs font-black rounded-xl border border-white/10 hover:border-ableYellow">HAZARDS</button>
                </div>
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

export default AICompanion;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { useAbility } from '../context/AbilityContext';
