        </section>

        {/* Conversational Hub */}
        <section className="lg:col-span-8 bg-ableBlack border-8 border-ableOrange p-10 rounded-huge shadow-2xl flex flex-col min-h-[600px]">
           <div className="flex justify-between items-center mb-8">
            <h3 className="text-4xl font-black text-ableOrange uppercase tracking-tighter italic">Conversation</h3>
            <div className={`px-4 py-1 border-2 rounded-xl text-[10px] font-black tracking-widest ${isListening ? 'bg-ableRed border-white animate-pulse' : 'bg-ableOrange/10 border-ableOrange'}`}>
              {ifiStatus.toUpperCase()}
            </div>
          </div>

          <div ref={scrollRef} className="flex-1 bg-white/5 border-4 border-white/10 rounded-3xl p-8 overflow-y-auto no-scrollbar space-y-6 relative mb-8">
            {history.length === 0 && (
              <div className="h-full flex flex-col items-center justify-center opacity-10">
                <div className="text-9xl">🎙️</div>
                <p className="font-black uppercase tracking-[0.4em]">Tap Mic to Speak</p>
              </div>
            )}
            {history.map((msg, i) => (
              <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[80%] p-6 rounded-3xl font-bold text-2xl leading-tight ${msg.role === 'user' ? 'bg-white/10 text-white rounded-tr-none border-2 border-white/10' : 'bg-ableOrange text-white rounded-tl-none shadow-xl italic'}`}>
                  {msg.text}
                </div>
              </div>
            ))}
            {isThinking && (
              <div className="flex justify-start">
                <div className="bg-white/5 text-white/40 p-6 rounded-3xl italic animate-pulse">Syncing thoughts...</div>
              </div>
            )}
          </div>

          {activeMedia && (
            <div className="bg-emerald-500 text-white p-4 rounded-3xl mb-4 flex justify-between items-center animate-bounce">
              <span className="font-black tracking-widest text-xs">AUDIO STREAM ACTIVE</span>
              <button onClick={() => setActiveMedia(null)} className="font-black underline">STOP</button>
              <audio ref={audioRef} src={activeMedia} autoPlay hidden />
            </div>
          )}

          <div className="flex flex-col items-center gap-4">
            <button 
              onClick={startListening}
              disabled={isListening || isThinking}
              className={`w-32 h-32 rounded-full flex items-center justify-center text-6xl shadow-huge transition-all active:scale-90 ${isListening ? 'bg-ableRed animate-ping' : 'bg-ableOrange hover:scale-105'}`}
            >
              🎙️
            </button>
            <p className="text-xs font-black uppercase tracking-[0.5em] text-ableOrange opacity-60">
              {isListening ? 'RECEIVING VOICE' : 'TAP TO START CHAT'}
            </p>
          </div>
        </section>
      </div>
    </div>
  );
};

