import React, { createContext, useContext, useState, useEffect, ReactNode, useCallback, useRef } from 'react';
import { PAD, VisualAbility, SpeechStyle, VisionNeed, CognitiveMode, VoicePreference, ColorPalette } from '../types';
import { DEFAULT_PAD } from '../constants';

interface AbilityContextType {
  pad: PAD;
  updatePAD: (updates: Partial<PAD>) => void;
  isHighContrast: boolean;
  toggleHighContrast: () => void;
  uiIntensity: 'standard' | 'low-stim';
  speak: (text: string) => void;
}

const AbilityContext = createContext<AbilityContextType | undefined>(undefined);

export const AbilityProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [pad, setPad] = useState<PAD>(DEFAULT_PAD);
  const [isHighContrast, setIsHighContrast] = useState(true);
  const [voices, setVoices] = useState<SpeechSynthesisVoice[]>([]);
  const synthRef = useRef<SpeechSynthesis | null>(null);

  useEffect(() => {
    if (typeof window !== 'undefined') {
      synthRef.current = window.speechSynthesis;
      const updateVoices = () => {
        const availableVoices = window.speechSynthesis.getVoices();
        setVoices(availableVoices);
      };
      updateVoices();
      window.speechSynthesis.onvoiceschanged = updateVoices;
    }
  }, []);

  const updatePAD = (updates: Partial<PAD>) => {
    setPad(prev => ({ ...prev, ...updates }));
  };

  const toggleHighContrast = () => setIsHighContrast(!isHighContrast);

  const speak = useCallback((text: string) => {
    if (!synthRef.current) return;
    synthRef.current.cancel();

    const utterance = new SpeechSynthesisUtterance(text);
    const isFemale = pad.voicePreference === VoicePreference.CalmFemale;

    // Refined humanoid profiles for better enunciation and natural pacing
    // Now utilizing pad.speechRate for fine-tuned control
    if (isFemale) {
      utterance.pitch = 1.05; 
      utterance.rate = pad.speechRate;
    } else {
      utterance.pitch = 0.90; 
      utterance.rate = pad.speechRate;
    }

    utterance.volume = 1.0;

    if (voices.length > 0) {
      const preferredVoice = voices.find(v => {
        const name = v.name.toLowerCase();
        const isEn = v.lang.startsWith('en');
        if (isFemale) {
          return isEn && (name.includes('female') || name.includes('samantha') || name.includes('victoria') || name.includes('zira') || name.includes('google us english'));
        } else {
          return isEn && (name.includes('male') || name.includes('david') || name.includes('alex') || name.includes('microsoft david') || name.includes('google uk english male'));
        }
      }) || voices.find(v => v.lang.startsWith('en'));

      if (preferredVoice) {
        utterance.voice = preferredVoice;
      }
    }

    synthRef.current.speak(utterance);
  }, [pad.voicePreference, pad.speechRate, voices]);

  useEffect(() => {
    const root = document.documentElement;
    if (pad.visual === VisualAbility.PartialBlindness || pad.largeText || pad.vision === VisionNeed.LowVision) {
      root.style.fontSize = '125%';
    } else {
      root.style.fontSize = '100%';
    }

    const paletteMap: Record<ColorPalette, string> = {
      [ColorPalette.Yellow]: '#FDE047',
      [ColorPalette.Orange]: '#F97316',
      [ColorPalette.Red]: '#EF4444',
      [ColorPalette.Blue]: '#3B82F6'
    };

    const activeColor = paletteMap[pad.colorPalette];
    root.style.setProperty('--able-primary', activeColor);

    if (isHighContrast) {
      root.classList.add('dark');
    } else {
      root.classList.remove('dark');
    }
  }, [pad, isHighContrast]);

  const uiIntensity = pad.cognitive === CognitiveMode.HighFocus ? 'low-stim' : 'standard';

  return (
    <AbilityContext.Provider value={{ pad, updatePAD, isHighContrast, toggleHighContrast, uiIntensity, speak }}>
      <div className={`min-h-screen ${isHighContrast ? 'bg-ableBlack text-white' : 'bg-white text-ableBlack'}`}>
        <style>{`
          :root { --able-primary: #FDE047; }
          .text-ableYellow { color: var(--able-primary) !important; }
          .bg-ableYellow { background-color: var(--able-primary) !important; }
          .border-ableYellow { border-color: var(--able-primary) !important; }
          .decoration-ableYellow { text-decoration-color: var(--able-primary) !important; }
        `}</style>
        {children}
      </div>
    </AbilityContext.Provider>
  );
};

export const useAbility = () => {
  const context = useContext(AbilityContext);
  if (!context) throw new Error('useAbility must be used within AbilityProvider');
  return context;
};

import React, { useEffect, useState, useCallback } from 'react';
import { useAbility } from '../context/AbilityContext';
import { APP_NAME } from '../constants';
import Logo from './Logo';

interface NavigationProps {
  activeTab: string;
  setActiveTab: (tab: string) => void;
  onEmergency: () => void;
}

const Navigation: React.FC<NavigationProps> = ({ activeTab, setActiveTab, onEmergency }) => {
  const { toggleHighContrast, isHighContrast, speak } = useAbility();
  const [isListening, setIsListening] = useState(false);

  const tabs = [
    { id: 'dashboard', label: 'HOME', icon: '🏠' },
    { id: 'vision', label: 'VISION', icon: '👁️' },
    { id: 'voice', label: 'VOICE', icon: '🎙️' },
    { id: 'circle', label: 'CIRCLE', icon: '🫂' },
    { id: 'career', label: 'GROWTH', icon: '📈' },
    { id: 'dna', label: 'DNA', icon: '🧬' }
  ];

  const handleVoiceCommand = useCallback((command: string) => {
    const cmd = command.toLowerCase();
    const tabMatch = tabs.find(t => cmd.includes(t.label.toLowerCase()) || cmd.includes(t.id.toLowerCase()));

    if (tabMatch) {
      setActiveTab(tabMatch.id);
      speak(`Navigating to ${tabMatch.label}`);
    } else if (cmd.includes('emergency') || cmd.includes('help') || cmd.includes('sos')) {
      onEmergency();
    } else if (cmd.includes('contrast') || cmd.includes('theme') || cmd.includes('mode')) {
      toggleHighContrast();
    }
  }, [tabs, setActiveTab, speak, onEmergency, toggleHighContrast]);

  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) return;

    const recognition = new SpeechRecognition();
    recognition.continuous = true;
    recognition.interimResults = false;
    recognition.lang = 'en-US';

    recognition.onresult = (event: any) => {
      const transcript = event.results[event.results.length - 1][0].transcript;
      handleVoiceCommand(transcript);
    };

    recognition.onstart = () => setIsListening(true);
    recognition.onend = () => setIsListening(false);

    // Initial start
    try {
      recognition.start();
    } catch (e) {
      console.warn("Speech recognition already started or failed.");
    }

    return () => {
      recognition.stop();
    };
  }, [handleVoiceCommand]);

  return (
    <>
      <div className="fixed top-0 left-0 right-0 z-50 p-4 flex justify-between items-center bg-ableBlack/90 backdrop-blur-xl border-b-4 border-ableYellow">
        <div className="flex items-center space-x-4">
          <div className="w-12 h-12 bg-white rounded-xl flex items-center justify-center shadow-lg shadow-ableYellow/20 p-1">
            <Logo />
          </div>
          <div className="flex flex-col">
            <span className="text-3xl font-black tracking-tighter text-ableYellow leading-none">{APP_NAME}</span>
            <div className="flex items-center gap-2">
              <div className={`w-2 h-2 rounded-full ${isListening ? 'bg-emerald-500 animate-pulse' : 'bg-white/20'}`}></div>
              <span className="text-[8px] font-black uppercase tracking-widest text-white/40">Voice Navigation Active</span>
            </div>
          </div>
        </div>

        <div className="flex items-center space-x-4">
          <button 
            onClick={toggleHighContrast}
            className="w-14 h-14 bg-white/10 rounded-2xl flex items-center justify-center border-4 border-white/20 transition-all active:scale-95"
          >
            {isHighContrast ? '☀️' : '🌙'}
          </button>
          <button 
            onClick={onEmergency}
            className="bg-ableRed text-white h-14 px-8 rounded-2xl font-black shadow-2xl border-4 border-white active:scale-90 transition-all text-xl"
          >
            SOS
          </button>
        </div>
      </div>

      <nav className="fixed bottom-0 left-0 right-0 z-50 p-4 bg-ableBlack border-t-8 border-ableYellow">
        <div className="max-w-4xl mx-auto flex items-center justify-between gap-2 overflow-x-auto no-scrollbar">
          {tabs.map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`flex flex-col items-center justify-center gap-1 transition-all flex-1 py-4 rounded-3xl border-4 min-w-[70px] ${
                activeTab === tab.id 
                  ? 'bg-ableYellow text-ableBlack border-white scale-110 shadow-2xl z-10' 
                  : 'bg-ableSlate text-white border-transparent opacity-60'
              }`}
            >
              <span className="text-3xl">{tab.icon}</span>
              <span className="text-[10px] font-black tracking-widest">{tab.label}</span>
            </button>
          ))}
        </div>
      </nav>
    </>
  );
};

