interface EmergencySystemProps {
  onClose: () => void;
}

const EmergencySystem: React.FC<EmergencySystemProps> = ({ onClose }) => {
  const { pad, speak } = useAbility();
  const [locationSent, setLocationSent] = useState(false);
  const [coords, setCoords] = useState<{lat: number, lng: number} | null>(null);
  const [showHelperView, setShowHelperView] = useState(false);
  const [isSilent, setIsSilent] = useState(false);
  const [status, setStatus] = useState('Broadcasting SOS...');
  const [callingIndex, setCallingIndex] = useState<number | null>(null);

  useEffect(() => {
    if (navigator.geolocation) {
      // Real-time watch position for actual "working" GPS
      const watchId = navigator.geolocation.watchPosition(
        (pos) => {
          setCoords({ lat: pos.coords.latitude, lng: pos.coords.longitude });
          setLocationSent(true);
          setStatus('GPS ACTIVE: BROADCASTING REAL-TIME');
        },
        () => {
          setLocationSent(true);
          setStatus('Location estimated via Network.');
        },
        { enableHighAccuracy: true, maximumAge: 0, timeout: 5000 }
      );
      return () => navigator.geolocation.clearWatch(watchId);
    }
  }, []);

  const handleSilentToggle = () => {
    setIsSilent(!isSilent);
    if (!isSilent) {
      console.log("Stealth SOS activated.");
    } else {
      speak("Silent mode deactivated. Standard emergency protocol active.");
    }
  };

  const initiateCall = (index: number) => {
    const contact = pad.emergencyContacts[index];
    setCallingIndex(index);
    speak(`Initiating emergency contact with ${contact.name} at ${contact.phone.split('').join(' ')}`);

    // Simulate connection for hackathon app
    setTimeout(() => {
      setCallingIndex(null);
      speak(`Connected to ${contact.name}. Broadcast sharing your ability DNA and GPS location now.`);
    }, 3000);
  };

  return (
    <div 
      className={`fixed inset-0 z-[200] transition-all duration-700 flex items-center justify-center p-0 sm:p-4 overflow-hidden ${
        isSilent ? 'bg-black' : 'bg-ableRed/98 backdrop-blur-2xl'
