    >
      <div 
        className={`w-full h-full sm:h-auto sm:max-w-6xl sm:rounded-huge shadow-2xl border-0 sm:border-8 flex flex-col relative transition-all duration-500 ${
          isSilent ? 'bg-black border-white/5' : 'bg-ableBlack border-white'
        }`}
      >
        {/* Stealth Overlay for Silent Mode */}
        {isSilent && (
          <div className="absolute inset-0 bg-black z-0 flex flex-col items-center justify-center p-10 opacity-20 pointer-events-none">
             <div className="text-[12vw] font-black uppercase tracking-[1em] text-white/5 whitespace-nowrap rotate-12">STEALTH SOS</div>
