import React, { useState, useCallback } from 'react';
import { useAbility } from '../context/AbilityContext';
import { VisualAbility, SpeechStyle, VoicePreference, ColorPalette, CognitiveMode } from '../types';

const PADForm: React.FC = () => {
  const { pad, updatePAD, speak } = useAbility();
  const [newContactName, setNewContactName] = useState('');
  const [newContactPhone, setNewContactPhone] = useState('');
  const [isDictating, setIsDictating] = useState<string | null>(null);

  const handleVoiceTest = (pref: VoicePreference) => {
    updatePAD({ voicePreference: pref });
    const text = pref === VoicePreference.CalmFemale 
      ? "Voice switched to calm female. I will speak at your chosen rate." 
      : "Voice switched to calm male. I will speak at your chosen rate.";
    setTimeout(() => speak(text), 150);
  };

  const startDictation = useCallback((target: 'name' | 'phone') => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      speak("Dictation is not supported in this browser.");
      return;
    }

    const recognition = new SpeechRecognition();
    recognition.lang = 'en-US';
    recognition.onstart = () => setIsDictating(target);
    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      if (target === 'name') setNewContactName(transcript);
      if (target === 'phone') setNewContactPhone(transcript.replace(/\s/g, ''));
    };
    recognition.onend = () => setIsDictating(null);
    recognition.start();
  }, [speak]);

  const addEmergencyContact = () => {
    if (!newContactName || !newContactPhone) return;
    const updated = [...pad.emergencyContacts, { name: newContactName, phone: newContactPhone }];
    updatePAD({ emergencyContacts: updated });
    setNewContactName('');
    setNewContactPhone('');
    speak(`Added ${newContactName} as an emergency contact.`);
  };

  const removeEmergencyContact = (idx: number) => {
    const updated = pad.emergencyContacts.filter((_, i) => i !== idx);
    updatePAD({ emergencyContacts: updated });
    speak("Contact removed.");
  };

  return (
    <div className="max-w-4xl mx-auto space-y-12 py-10 animate-in fade-in duration-700 pb-32">
      <header className="space-y-4">
        <h2 className="text-6xl font-black text-ableYellow tracking-tighter uppercase italic">Ability DNA.</h2>
        <p className="text-2xl font-bold text-white/60">Your unique interaction blueprint. Fine-tune it here.</p>
      </header>

      <div className="space-y-12">
        {/* Visual Section */}
        <section className="space-y-6">
          <h3 className="text-xs font-black text-ableOrange uppercase tracking-[0.4em]">Visual Perspective</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {[
              { id: VisualAbility.Standard, label: 'STANDARD' },
              { id: VisualAbility.Blurry, label: 'BLURRY VISION' },
              { id: VisualAbility.LowContrast, label: 'LOW CONTRAST' },
              { id: VisualAbility.PartialBlindness, label: 'PARTIAL BLINDNESS' }
            ].map(v => (
              <button
                key={v.id}
                onClick={() => updatePAD({ visual: v.id })}
                className={`p-8 rounded-[2.5rem] border-4 transition-all text-2xl font-black text-left flex justify-between items-center ${
                  pad.visual === v.id 
                    ? 'bg-ableYellow text-ableBlack border-white shadow-huge' 
                    : 'bg-white/5 text-white border-white/10 hover:border-ableYellow/40'
                }`}
              >
                <span>{v.label}</span>
                {pad.visual === v.id && <span>🎯</span>}
              </button>
            ))}
          </div>
        </section>

        {/* Cognitive Mode Section */}
        <section className="space-y-6">
          <h3 className="text-xs font-black text-ableOrange uppercase tracking-[0.4em]">Cognitive Flow</h3>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {[
              { id: CognitiveMode.Standard, label: 'STANDARD', desc: 'Full information density.' },
              { id: CognitiveMode.Simplified, label: 'SIMPLIFIED', desc: 'Core features only.' },
              { id: CognitiveMode.HighFocus, label: 'HIGH FOCUS', desc: 'Zero stim distractions.' }
            ].map(m => (
              <button
                key={m.id}
                onClick={() => updatePAD({ cognitive: m.id })}
                className={`p-6 rounded-3xl border-4 transition-all text-left flex flex-col gap-2 ${
                  pad.cognitive === m.id 
                    ? 'bg-ableYellow text-ableBlack border-white shadow-xl' 
                    : 'bg-white/5 text-white border-white/10 hover:border-ableYellow/20'
                }`}
              >
                <span className="text-xl font-black">{m.label}</span>
                <span className={`text-[10px] font-bold uppercase tracking-widest ${pad.cognitive === m.id ? 'opacity-60' : 'opacity-30'}`}>{m.desc}</span>
              </button>
            ))}
          </div>
        </section>

        {/* Speech Rate Slider */}
        <section className="bg-ableBlack border-8 border-ableYellow p-10 rounded-huge space-y-8 shadow-2xl">
          <div className="flex justify-between items-center">
            <h3 className="text-2xl font-black text-ableYellow uppercase italic">Speech Pace</h3>
            <span className="text-4xl font-black text-white">{Math.round(pad.speechRate * 100)}%</span>
          </div>
          <div className="space-y-4">
            <input 
              type="range"
              min="0.5"
              max="1.5"
              step="0.05"
              value={pad.speechRate}
              onChange={(e) => updatePAD({ speechRate: parseFloat(e.target.value) })}
              className="w-full h-4 bg-white/10 rounded-full appearance-none cursor-pointer accent-ableYellow"
            />
            <div className="flex justify-between text-[10px] font-black uppercase text-white/30 tracking-widest">
              <span>Deliberate</span>
              <span>Standard</span>
              <span>Rapid</span>
            </div>
          </div>
          <button 
            onClick={() => speak("This is a test of your current speaking rate. Does it feel comfortable?")}
            className="w-full py-4 bg-white/5 border-2 border-white/10 rounded-2xl text-xs font-black tracking-widest hover:border-ableYellow transition-all"
          >
            TEST RATE
          </button>
        </section>

        {/* Emergency Contacts Management */}
        <section className="bg-ableBlack border-8 border-ableRed p-10 rounded-huge space-y-8 shadow-2xl">
          <h3 className="text-2xl font-black text-ableRed uppercase italic">Safety Circle</h3>
          <div className="space-y-4">
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="relative group">
                <input 
                  value={newContactName}
                  onChange={e => setNewContactName(e.target.value)}
