                  className="w-full bg-white/5 border-4 border-white/10 rounded-2xl px-6 py-4 pr-16 text-white font-black focus:border-ableRed outline-none"
                />
                <button 
                  onClick={() => startDictation('name')}
                  className={`absolute right-4 top-1/2 -translate-y-1/2 w-10 h-10 rounded-xl flex items-center justify-center transition-all ${isDictating === 'name' ? 'bg-ableRed animate-pulse' : 'bg-white/10 hover:bg-white/20'}`}
                >
                  🎙️
                </button>
              </div>
              <div className="relative group">
                <input 
                  value={newContactPhone}
                  onChange={e => setNewContactPhone(e.target.value)}
                  placeholder="PHONE NUMBER"
                  className="w-full bg-white/5 border-4 border-white/10 rounded-2xl px-6 py-4 pr-16 text-white font-black focus:border-ableRed outline-none"
                />
                <button 
                  onClick={() => startDictation('phone')}
                  className={`absolute right-4 top-1/2 -translate-y-1/2 w-10 h-10 rounded-xl flex items-center justify-center transition-all ${isDictating === 'phone' ? 'bg-ableRed animate-pulse' : 'bg-white/10 hover:bg-white/20'}`}
                >
                  🎙️
                </button>
              </div>
            </div>
            <button 
              onClick={addEmergencyContact}
              className="w-full py-6 bg-ableRed text-white rounded-2xl font-black text-xl shadow-xl active:scale-95"
