  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [history]);

  const initChat = () => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    chatSessionRef.current = ai.chats.create({
      model: 'gemini-3-flash-preview',
      config: {
        systemInstruction: `You are ABLE, an empathetic AI companion for disabled users.
        User PAD: Visual: ${pad.visual}, Speech: ${pad.speech}.
        Be conversational and supportive. If asked for music, use Google Search to find sources or lyrics.
        If reciting lyrics, use a humanoid tone. Keep all replies strictly under 3 sentences.`,
        tools: [{ googleSearch: {} }]
      }
    });
  };

  const startFieldDictation = useCallback(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      speak("Speech recognition is not supported in this browser.");
      return;
    }

    const recognition = new SpeechRecognition();
    recognition.lang = 'en-US';
    recognition.onstart = () => setIsDictatingField(true);
    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setChatInput(prev => prev ? `${prev} ${transcript}` : transcript);
    };
    recognition.onend = () => setIsDictatingField(false);
    recognition.start();
  }, [speak]);

  const handleSendMessage = async (userText: string) => {
    if (!userText.trim()) return;

    setIsThinking(true);
    setIfiStatus('Synchronizing...');
    setHistory(prev => [...prev, { role: 'user', text: userText }]);
    setChatInput('');
    setActiveMedia(null);

    // Easter Eggs
    const lower = userText.toLowerCase();
    if (lower.includes('who is lakshita') || lower.includes('who is naksh')) {
      const resp = lower.includes('lakshita') 
        ? "Lakshita is my brilliant creator. She built me with empathy for your needs." 
        : "Naksh is my primary architect. He designed the synaptic logic that drives my empathy.";
      setHistory(prev => [...prev, { role: 'assistant', text: resp }]);
      speak(resp);
      setIsThinking(false);
      setIfiStatus('AI Ready');
      return;
    }

    try {
      if (!chatSessionRef.current) initChat();

      const response = await chatSessionRef.current!.sendMessage({ message: userText });
      const resText = response.text || "I'm listening and ready to help.";

      setHistory(prev => [...prev, { role: 'assistant', text: resText }]);
      speak(resText);
      setIfiStatus('AI Ready');

      // Check for music links in grounding
      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
      if (chunks) {
        const audioLink = chunks.find(c => c.web && (
          c.web.uri.endsWith('.mp3') || 
          c.web.uri.includes('audio-stream') || 
          c.web.uri.includes('streaming-link')
        ));
        if (audioLink) setActiveMedia(audioLink.web!.uri);
      }

    } catch (error) {
      console.error("AI Error:", error);
      setIfiStatus('Sync Error');
      speak("My connection skipped. Please try again.");
    } finally {
      setIsThinking(false);
    }
  };

  const startListening = useCallback(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      speak("Voice input is not supported here.");
      return;
    }

    if (recognitionRef.current) {
      try { recognitionRef.current.stop(); } catch(e) {}
    }

    const recognition = new SpeechRecognition();
    recognition.lang = 'en-US';
    recognition.interimResults = true;
    recognition.continuous = false;
    recognitionRef.current = recognition;

    recognition.onstart = () => {
      setIsListening(true);
      setIfiStatus('Listening...');
      setTranscript('');
    };

    recognition.onresult = (event: any) => {
      let currentTranscript = '';
      for (let i = event.resultIndex; i < event.results.length; ++i) {
        currentTranscript += event.results[i][0].transcript;
      }
      setTranscript(currentTranscript);
    };

    recognition.onerror = (event: any) => {
      setIsListening(false);
      let errorMsg = "Speech error.";
      switch(event.error) {
        case 'not-allowed': errorMsg = "Microphone blocked."; break;
        case 'network': errorMsg = "Network connection issue."; break;
        case 'no-speech': errorMsg = "I didn't hear anything."; break;
      }
      setIfiStatus('Error');
      speak(errorMsg);
    };

    recognition.onend = () => {
      setIsListening(false);
      if (transcript.trim()) {
        handleSendMessage(transcript);
      } else {
        setIfiStatus('Standby');
      }
    };

    recognition.start();
  }, [speak, transcript]);

  const soundboard = [
    { label: 'YES', text: "Yes, that is correct.", color: 'bg-emerald-500' },
    { label: 'NO', text: "No, thank you.", color: 'bg-ableRed' },
    { label: 'WAIT', text: "Please wait, I am finishing a thought.", color: 'bg-ableOrange' },
    { label: 'THANKS', text: "Thank you for your help.", color: 'bg-ableYellow text-ableBlack' }
  ];

  return (
    <div className="space-y-12 py-10 animate-in slide-in-from-left-10 duration-700">
      <header className="space-y-4">
        <h2 className="text-6xl font-black text-ableYellow tracking-tighter italic">Voice Hub.</h2>
        <p className="text-2xl font-bold text-white/60">A real conversation at your own speed. Talk to ABLE.</p>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
        {/* Soundboard & Quick Actions */}
        <section className="lg:col-span-4 bg-ableBlack border-8 border-ableYellow p-8 rounded-huge shadow-2xl space-y-8">
          <h3 className="text-3xl font-black text-ableYellow uppercase">Direct Intent</h3>
          <div className="grid grid-cols-2 gap-3">
            {soundboard.map(btn => (
              <button 
                key={btn.label}
                onClick={() => speak(btn.text)}
                className={`${btn.color} py-8 rounded-3xl font-black text-2xl shadow-xl active:scale-95 transition-all text-white border-2 border-white/20`}
              >
                {btn.label}
              </button>
            ))}
          </div>

          <div className="pt-6 space-y-4 border-t-2 border-white/5">
            <div className="relative">
              <input 
                value={chatInput}
                onChange={(e) => setChatInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSendMessage(chatInput)}
                placeholder="TYPE YOUR MESSAGE..."
                className="w-full bg-white/5 border-4 border-white/20 rounded-huge px-6 py-5 pr-16 text-xl font-black text-white outline-none focus:border-ableYellow"
              />
              <button 
                onClick={startFieldDictation}
                className={`absolute right-4 top-1/2 -translate-y-1/2 w-10 h-10 rounded-xl flex items-center justify-center transition-all ${isDictatingField ? 'bg-ableYellow animate-pulse' : 'bg-white/10 hover:bg-white/20'}`}
                title="Dictate message"
              >
                🎙️
              </button>
            </div>
            <button 
              onClick={() => handleSendMessage(chatInput)}
              className="w-full py-6 bg-white text-ableBlack rounded-huge font-black text-2xl shadow-huge active:scale-95"
            >
              SEND TEXT
            </button>
          </div>
        </section>

        {/* Conversational Hub */}
        <section className="lg:col-span-8 bg-ableBlack border-8 border-ableOrange p-10 rounded-huge shadow-2xl flex flex-col min-h-[600px]">
           <div className="flex justify-between items-center mb-8">
            <h3 className="text-4xl font-black text-ableOrange uppercase tracking-tighter italic">Conversation</h3>
            <div className={`px-4 py-1 border-2 rounded-xl text-[10px] font-black tracking-widest ${isListening ? 'bg-ableRed border-white animate-pulse' : 'bg-ableOrange/10 border-ableOrange'}`}>
              {ifiStatus.toUpperCase()}
            </div>
          </div>

          <div ref={scrollRef} className="flex-1 bg-white/5 border-4 border-white/10 rounded-3xl p-8 overflow-y-auto no-scrollbar space-y-6 relative mb-8">
            {history.length === 0 && (
              <div className="h-full flex flex-col items-center justify-center opacity-10">
                <div className="text-9xl">🎙️</div>
                <p className="font-black uppercase tracking-[0.4em]">Tap Mic to Speak</p>
              </div>
            )}
            {history.map((msg, i) => (
              <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[80%] p-6 rounded-3xl font-bold text-2xl leading-tight ${msg.role === 'user' ? 'bg-white/10 text-white rounded-tr-none border-2 border-white/10' : 'bg-ableOrange text-white rounded-tl-none shadow-xl italic'}`}>
                  {msg.text}
                </div>
              </div>
            ))}
            {isThinking && (
              <div className="flex justify-start">
                <div className="bg-white/5 text-white/40 p-6 rounded-3xl italic animate-pulse">Syncing thoughts...</div>
              </div>
            )}
          </div>

          {activeMedia && (
            <div className="bg-emerald-500 text-white p-4 rounded-3xl mb-4 flex justify-between items-center animate-bounce">
              <span className="font-black tracking-widest text-xs">AUDIO STREAM ACTIVE</span>
              <button onClick={() => setActiveMedia(null)} className="font-black underline">STOP</button>
              <audio ref={audioRef} src={activeMedia} autoPlay hidden />
            </div>
          )}

          <div className="flex flex-col items-center gap-4">
            <button 
              onClick={startListening}
              disabled={isListening || isThinking}
              className={`w-32 h-32 rounded-full flex items-center justify-center text-6xl shadow-huge transition-all active:scale-90 ${isListening ? 'bg-ableRed animate-ping' : 'bg-ableOrange hover:scale-105'}`}
            >
              🎙️
            </button>
            <p className="text-xs font-black uppercase tracking-[0.5em] text-ableOrange opacity-60">
              {isListening ? 'RECEIVING VOICE' : 'TAP TO START CHAT'}
            </p>
          </div>
        </section>
      </div>
    </div>
  );
};

