import React, { createContext, useContext, useState, useEffect, ReactNode, useCallback, useRef } from 'react';
import { PAD, VisualAbility, SpeechStyle, VisionNeed, CognitiveMode, VoicePreference, ColorPalette } from '../types';
import { DEFAULT_PAD } from '../constants';

interface AbilityContextType {
  pad: PAD;
  updatePAD: (updates: Partial<PAD>) => void;
  isHighContrast: boolean;
  toggleHighContrast: () => void;
  uiIntensity: 'standard' | 'simplified' | 'high-focus';
  speak: (text: string) => void;
}

const AbilityContext = createContext<AbilityContextType | undefined>(undefined);

export const AbilityProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [pad, setPad] = useState<PAD>(DEFAULT_PAD);
  const [isHighContrast, setIsHighContrast] = useState(true);
  const [voices, setVoices] = useState<SpeechSynthesisVoice[]>([]);
  const synthRef = useRef<SpeechSynthesis | null>(null);

  useEffect(() => {
    if (typeof window !== 'undefined') {
      synthRef.current = window.speechSynthesis;
      const updateVoices = () => {
        const availableVoices = window.speechSynthesis.getVoices();
        setVoices(availableVoices);
      };
      updateVoices();
      window.speechSynthesis.onvoiceschanged = updateVoices;
    }
  }, []);

  const updatePAD = (updates: Partial<PAD>) => {
    setPad(prev => ({ ...prev, ...updates }));
  };

  const toggleHighContrast = () => setIsHighContrast(!isHighContrast);

  const speak = useCallback((text: string) => {
    if (!synthRef.current) return;
    synthRef.current.cancel();

    const utterance = new SpeechSynthesisUtterance(text);
    const isFemale = pad.voicePreference === VoicePreference.CalmFemale;

    utterance.rate = pad.speechRate;
    utterance.pitch = isFemale ? 1.1 : 0.9;
    utterance.volume = 1.0;

    if (voices.length > 0) {
      const preferredVoice = voices.find(v => {
        const name = v.name.toLowerCase();
        const isEn = v.lang.startsWith('en');
        if (isFemale) {
          return isEn && (name.includes('female') || name.includes('samantha') || name.includes('google us english'));
        } else {
          return isEn && (name.includes('male') || name.includes('david') || name.includes('google uk english male'));
        }
      }) || voices.find(v => v.lang.startsWith('en'));

      if (preferredVoice) {
        utterance.voice = preferredVoice;
      }
    }

    synthRef.current.speak(utterance);
  }, [pad.voicePreference, pad.speechRate, voices]);

  useEffect(() => {
    const root = document.documentElement;
    // Handle Visual Sizing
    if (pad.visual === VisualAbility.PartialBlindness || pad.vision === VisionNeed.LowVision) {
      root.style.fontSize = '125%';
    } else {
      root.style.fontSize = '100%';
    }

    // Handle Color Palette
    const paletteMap: Record<ColorPalette, string> = {
      [ColorPalette.Yellow]: '#FDE047',
      [ColorPalette.Orange]: '#F97316',
      [ColorPalette.Red]: '#EF4444',
      [ColorPalette.Blue]: '#3B82F6'
    };
    root.style.setProperty('--able-primary', paletteMap[pad.colorPalette] || '#FDE047');

    // Handle Dark/High Contrast Mode
    if (isHighContrast) {
      root.classList.add('dark');
    } else {
      root.classList.remove('dark');
    }

    // Handle Cognitive Mode UI Effects
    if (pad.cognitive === CognitiveMode.HighFocus) {
      root.classList.add('high-focus');
    } else {
      root.classList.remove('high-focus');
    }
  }, [pad, isHighContrast]);

  const uiIntensity = 
    pad.cognitive === CognitiveMode.Simplified ? 'simplified' : 
    pad.cognitive === CognitiveMode.HighFocus ? 'high-focus' : 'standard';

  return (
    <AbilityContext.Provider value={{ pad, updatePAD, isHighContrast, toggleHighContrast, uiIntensity, speak }}>
      <div className={`min-h-screen transition-all duration-500 ${isHighContrast ? 'bg-ableBlack text-white' : 'bg-white text-ableBlack'}`}>
        <style>{`
          :root { --able-primary: #FDE047; }
          .text-ableYellow { color: var(--able-primary) !important; }
          .bg-ableYellow { background-color: var(--able-primary) !important; }
          .border-ableYellow { border-color: var(--able-primary) !important; }

          /* High Focus adjustments: Hide unnecessary decorations */
          .high-focus .animate-pulse-slow,
          .high-focus .animate-shimmer,
          .high-focus .animate-synapse {
            animation: none !important;
          }
          .high-focus .shadow-glow,
          .high-focus .shadow-huge {
            box-shadow: none !important;
          }
        `}</style>
        {children}
      </div>
    </AbilityContext.Provider>
  );
};

export const useAbility = () => {
  const context = useContext(AbilityContext);
  if (!context) throw new Error('useAbility must be used within AbilityProvider');
  return context;
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { useAbility } from '../context/AbilityContext';
import SignLanguageAvatar from './SignLanguageAvatar';
import { GoogleGenAI, Chat } from '@google/genai';

interface ChatMessage {
  role: 'user' | 'assistant';
  text: string;
}

const AICompanion: React.FC = () => {
  const { pad, speak, uiIntensity } = useAbility();
  const [isVisionActive, setIsVisionActive] = useState(false);
  const [status, setStatus] = useState('STANDBY');
  const [chatInput, setChatInput] = useState('');
  const [history, setHistory] = useState<ChatMessage[]>([]);
  const [isThinking, setIsThinking] = useState(false);
  const [isDictating, setIsDictating] = useState(false);
  const [isLiveAnalyzing, setIsLiveAnalyzing] = useState(false);
  const [activeMedia, setActiveMedia] = useState<{ url: string, type: 'audio' | 'lyrics' } | null>(null);

  const videoRef = useRef<HTMLVideoElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null);
  const chatSessionRef = useRef<Chat | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const analyzeIntervalRef = useRef<number | null>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [history]);

  useEffect(() => {
    return () => {
      if (mediaStreamRef.current) {
        mediaStreamRef.current.getTracks().forEach(t => t.stop());
      }
      if (analyzeIntervalRef.current) window.clearInterval(analyzeIntervalRef.current);
    };
  }, []);

  const initChat = () => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    chatSessionRef.current = ai.chats.create({
      model: 'gemini-3-flash-preview',
      config: {
        systemInstruction: "You are ABLE, an adaptive AI. You provide humanoid, supportive vision assistance. CRITICAL: Keep every response strictly under 2 sentences. If asked to play a song, search for it using Google Search. If you find a streaming link, mention it. If not, recite the most meaningful 2 sentences of the lyrics.",
        tools: [{ googleSearch: {} }]
      }
    });
  };

  const startDictation = useCallback(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      speak("Speech recognition unavailable.");
      return;
    }
    const recognition = new SpeechRecognition();
    recognition.lang = 'en-US';
    recognition.onstart = () => setIsDictating(true);
    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setChatInput(prev => prev ? `${prev} ${transcript}` : transcript);
    };
    recognition.onend = () => setIsDictating(false);
    recognition.start();
  }, [speak]);

  const captureFrame = () => {
    if (!videoRef.current || !canvasRef.current) return null;
    const canvas = canvasRef.current;
    const video = videoRef.current;
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext('2d');
    if (!ctx) return null;
    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
    return canvas.toDataURL('image/jpeg', 0.6);
  };

  const handleSendMessage = async (msg?: string) => {
    const query = msg || chatInput;
    if (!query.trim()) return;

    setIsThinking(true);
    if (!msg) setChatInput('');
    setActiveMedia(null);

    setHistory(prev => [...prev, { role: 'user', text: query }]);

    try {
      if (!chatSessionRef.current) initChat();

      const frame = captureFrame();
      const parts: any[] = [{ text: query }];
      if (frame) {
        parts.push({
          inlineData: { data: frame.split(',')[1], mimeType: 'image/jpeg' }
        });
      }

      const response = await chatSessionRef.current!.sendMessage({ message: query });
      const resText = response.text || "I'm analyzing that now.";

      setHistory(prev => [...prev, { role: 'assistant', text: resText }]);
      speak(resText);

      // Check for music links or lyrics in grounding
      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
      if (chunks) {
        const musicLink = chunks.find(c => c.web && (c.web.uri.includes('spotify') || c.web.uri.includes('youtube') || c.web.uri.includes('audio')));
        if (musicLink) {
          setActiveMedia({ url: musicLink.web!.uri, type: 'audio' });
        }
      }
    } catch (e) {
      setHistory(prev => [...prev, { role: 'assistant', text: "Connection issues. Let's try again." }]);
      speak("I lost connection for a second.");
    } finally {
      setIsThinking(false);
    }
  };

  const toggleVision = async () => {
    if (isVisionActive) {
      if (mediaStreamRef.current) {
        mediaStreamRef.current.getTracks().forEach(t => t.stop());
        mediaStreamRef.current = null;
      }
      if (analyzeIntervalRef.current) {
        window.clearInterval(analyzeIntervalRef.current);
        analyzeIntervalRef.current = null;
      }
      setIsVisionActive(false);
      setIsLiveAnalyzing(false);
      setStatus('OFF');
      speak("Vision Hub closed.");
    } else {
      try {
        setStatus('WAKING UP...');
        if (!chatSessionRef.current) initChat();

        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 720 } },
          audio: false 
        });

        mediaStreamRef.current = stream;
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          videoRef.current.onloadedmetadata = () => {
            videoRef.current?.play().catch(e => console.error("Video play failed", e));
            setStatus('LIVE');
          };
        }

        setIsVisionActive(true);
        speak("Vision Hub is active.");
      } catch (err) {
        setStatus('ERROR');
        speak("Camera access denied.");
      }
    }
  };

  const toggleLiveAnalysis = () => {
    if (isLiveAnalyzing) {
      if (analyzeIntervalRef.current) window.clearInterval(analyzeIntervalRef.current);
      analyzeIntervalRef.current = null;
      setIsLiveAnalyzing(false);
      speak("Live tracking paused.");
    } else if (isVisionActive) {
      setIsLiveAnalyzing(true);
      speak("Real-time analysis active. I will update you automatically.");
      analyzeIntervalRef.current = window.setInterval(() => {
        if (!isThinking) handleSendMessage("Briefly describe what has changed in view.");
      }, 10000);
    }
  };

  return (
    <div className={`flex flex-col space-y-8 py-6 w-full ${uiIntensity === 'simplified' ? 'max-w-2xl mx-auto' : 'max-w-full'}`}>
      <canvas ref={canvasRef} className="hidden" />
      <header className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6">
        <div className="space-y-1">
           <h2 className="text-5xl font-black text-ableYellow tracking-tighter uppercase leading-none italic">Vision Hub</h2>
           <div className="flex items-center space-x-3">
             <div className={`w-3 h-3 rounded-full ${isVisionActive ? 'bg-emerald-500 animate-pulse' : 'bg-white/10'}`}></div>
             <p className="text-[10px] font-black text-white/40 uppercase tracking-[0.5em]">{status}</p>
           </div>
        </div>

        <div className="flex gap-4">
          <button 
            onClick={toggleLiveAnalysis}
            disabled={!isVisionActive}
            className={`px-6 py-4 rounded-2xl font-black text-xs border-4 transition-all shadow-huge disabled:opacity-20 ${isLiveAnalyzing ? 'bg-emerald-500 border-white text-white' : 'bg-white/5 border-white/10 text-white/40'}`}
          >
            {isLiveAnalyzing ? 'LIVE: ON' : 'TRACKING: OFF'}
          </button>
          <button 
            onClick={toggleVision}
            className={`px-10 py-5 rounded-huge font-black text-xl border-4 transition-all shadow-huge active:scale-95 ${isVisionActive ? 'bg-ableRed border-white text-white' : 'bg-ableYellow border-transparent text-ableBlack'}`}
          >
            {isVisionActive ? 'SHUT LENS' : 'OPEN VISION'}
          </button>
        </div>
      </header>

      <div className={`grid grid-cols-1 ${uiIntensity === 'simplified' ? '' : 'xl:grid-cols-12'} gap-8 w-full`}>
        <div className={`xl:col-span-7 bg-black border-8 border-ableYellow rounded-huge overflow-hidden relative aspect-video shadow-2xl flex items-center justify-center transition-all ${isVisionActive ? 'opacity-100' : 'opacity-40'}`}>
          <video ref={videoRef} autoPlay playsInline muted className="w-full h-full object-cover" />
          {!isVisionActive && (
            <div className="absolute inset-0 flex items-center justify-center bg-black/80">
              <div className="text-center space-y-4">
                <div className="text-9xl">👁️</div>
                <p className="font-black uppercase tracking-[0.5em] text-white/20">Standby</p>
              </div>
            </div>
          )}
          <div className="absolute bottom-6 right-6 w-32 md:w-48 shadow-huge pointer-events-none">
             <SignLanguageAvatar 
               message={history[history.length-1]?.role === 'assistant' ? history[history.length-1].text : ''} 
               active={isThinking || history[history.length-1]?.role === 'assistant'} 
             />
          </div>
        </div>

        <div className={`xl:col-span-5 flex flex-col gap-6 ${uiIntensity === 'simplified' ? 'order-first' : ''}`}>
           <div className="bg-white/5 border-4 border-white/10 p-8 rounded-huge shadow-xl h-[500px] flex flex-col">
              <div ref={scrollRef} className="flex-1 overflow-y-auto no-scrollbar space-y-4 pr-2">
                {history.length === 0 && <p className="text-white/20 italic text-center py-20">I am ready to see and listen.</p>}
                {history.map((msg, i) => (
                  <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-in slide-in-from-bottom-2`}>
                    <div className={`max-w-[85%] p-4 rounded-3xl font-bold text-lg ${msg.role === 'user' ? 'bg-white/10 text-white' : 'bg-ableYellow text-ableBlack shadow-lg'}`}>
                      {msg.text}
                    </div>
                  </div>
                ))}
              </div>

              {activeMedia && (
                <div className="mt-4 p-4 bg-emerald-500 rounded-2xl animate-in zoom-in">
                  <p className="text-[10px] font-black uppercase text-white mb-2">FOUND STREAMING LINK</p>
                  <a href={activeMedia.url} target="_blank" rel="noopener noreferrer" className="text-white underline font-bold break-all">{activeMedia.url}</a>
                </div>
              )}

              <div className="mt-6 space-y-4">
                <div className="flex gap-2">
                  <div className="flex-1 relative">
                    <input 
                      value={chatInput}
                      onChange={(e) => setChatInput(e.target.value)}
                      onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
                      placeholder="Talk to ABLE..."
                      className="w-full bg-black/40 border-4 border-white/10 rounded-2xl p-4 pr-16 text-white font-bold outline-none focus:border-ableYellow"
                    />
                    <button onClick={startDictation} className={`absolute right-4 top-1/2 -translate-y-1/2 w-10 h-10 rounded-xl flex items-center justify-center ${isDictating ? 'bg-ableRed animate-pulse text-white' : 'bg-white/10 text-white/60'}`}>🎙️</button>
                  </div>
                  <button onClick={() => handleSendMessage()} disabled={isThinking || !chatInput.trim()} className="px-6 bg-white text-ableBlack rounded-2xl font-black disabled:opacity-20 transition-all">SEND</button>
                </div>
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

