export function encode(bytes: Uint8Array): string {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

export function decode(base64: string): Uint8Array {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

export function createBlob(data: Float32Array): { data: string; mimeType: string } {
  const l = data.length;
  const int16 = new Int16Array(l);
  for (let i = 0; i < l; i++) {
    int16[i] = data[i] * 32768;
  }
  return {
    data: encode(new Uint8Array(int16.buffer)),
    mimeType: 'audio/pcm;rate=16000',
  };
}

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { useAbility } from '../context/AbilityContext';
import { GoogleGenAI, Modality, LiveServerMessage } from '@google/genai';
import { encode, decode, decodeAudioData, createBlob } from '../services/audioService';

interface ChatMessage {
  role: 'user' | 'assistant';
  text: string;
}

const CommHub: React.FC = () => {
  const { pad, speak } = useAbility();
  const [isLiveActive, setIsLiveActive] = useState(false);
  const [isDictatingField, setIsDictatingField] = useState(false);
  const [ifiStatus, setIfiStatus] = useState('Standby');
  const [history, setHistory] = useState<ChatMessage[]>([]);
  const [chatInput, setChatInput] = useState('');
  const [isThinking, setIsThinking] = useState(false);

  const audioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const sessionRef = useRef<any>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const currentOutputTranscriptionRef = useRef('');
  const currentInputTranscriptionRef = useRef('');

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [history]);

  const stopLiveSession = useCallback(() => {
    if (sessionRef.current) {
      sessionRef.current.close();
      sessionRef.current = null;
    }
    if (audioContextRef.current) {
      audioContextRef.current.close();
      audioContextRef.current = null;
    }
    if (outputAudioContextRef.current) {
      outputAudioContextRef.current.close();
      outputAudioContextRef.current = null;
    }
    for (const source of sourcesRef.current) {
      source.stop();
    }
    sourcesRef.current.clear();
    setIsLiveActive(false);
    setIfiStatus('Standby');
  }, []);

  const startLiveSession = useCallback(async () => {
    try {
      setIfiStatus('Connecting...');
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setIsLiveActive(true);
            setIfiStatus('Live Duplex');
            speak("Live voice active. I am listening.");

            const source = audioContextRef.current!.createMediaStreamSource(stream);
            const scriptProcessor = audioContextRef.current!.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBlob = createBlob(inputData);
              sessionPromise.then(session => {
                session.sendRealtimeInput({ media: pcmBlob });
              });
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(audioContextRef.current!.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            // Handle Transcription
            if (message.serverContent?.outputTranscription) {
              currentOutputTranscriptionRef.current += message.serverContent.outputTranscription.text;
            } else if (message.serverContent?.inputTranscription) {
              currentInputTranscriptionRef.current += message.serverContent.inputTranscription.text;
            }

            if (message.serverContent?.turnComplete) {
              const userText = currentInputTranscriptionRef.current;
              const assistantText = currentOutputTranscriptionRef.current;
              if (userText || assistantText) {
                setHistory(prev => [
                  ...prev, 
                  ...(userText ? [{ role: 'user' as const, text: userText }] : []),
                  ...(assistantText ? [{ role: 'assistant' as const, text: assistantText }] : [])
                ]);
              }
              currentInputTranscriptionRef.current = '';
              currentOutputTranscriptionRef.current = '';
            }

            // Handle Audio
            const audioData = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audioData && outputAudioContextRef.current) {
              const ctx = outputAudioContextRef.current;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const buffer = await decodeAudioData(decode(audioData), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = buffer;
              source.connect(ctx.destination);
              source.addEventListener('ended', () => sourcesRef.current.delete(source));
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              sourcesRef.current.add(source);
            }

            if (message.serverContent?.interrupted) {
              for (const s of sourcesRef.current) s.stop();
              sourcesRef.current.clear();
              nextStartTimeRef.current = 0;
            }
          },
          onerror: (e) => {
            console.error("Live Error:", e);
            setIfiStatus('Connection Error');
            stopLiveSession();
          },
          onclose: () => {
            setIfiStatus('Standby');
            setIsLiveActive(false);
          }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: pad.voicePreference === 'calm-female' ? 'Kore' : 'Zephyr' } },
          },
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          systemInstruction: `You are ABLE, an empathetic AI. Keep responses under 2 sentences. User has visual need: ${pad.visual}.`
        }
      });

      sessionRef.current = await sessionPromise;
    } catch (e) {
      console.error("Failed to start live session:", e);
      setIfiStatus('Mic Error');
      speak("I couldn't access the microphone. Please check permissions.");
    }
  }, [pad, speak, stopLiveSession]);

  const startFieldDictation = useCallback(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      speak("Dictation unavailable.");
      return;
    }
    const recognition = new SpeechRecognition();
    recognition.lang = 'en-US';
    recognition.onstart = () => setIsDictatingField(true);
    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setChatInput(prev => prev ? `${prev} ${transcript}` : transcript);
    };
    recognition.onend = () => setIsDictatingField(false);
    recognition.start();
  }, [speak]);

  const handleManualSend = async () => {
    if (!chatInput.trim()) return;
    setHistory(prev => [...prev, { role: 'user', text: chatInput }]);
    setChatInput('');
    setIsThinking(true);
    // For manual text, we still use standard generateContent to keep it simple but synced
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      const res = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: chatInput,
        config: { systemInstruction: "Humanoid, concise (max 2 sentences)." }
      });
      const txt = res.text || "...";
      setHistory(prev => [...prev, { role: 'assistant', text: txt }]);
      speak(txt);
    } catch(e) {
      console.error(e);
    } finally {
      setIsThinking(false);
    }
  };

  const soundboard = [
    { label: 'YES', text: "Yes, that is correct.", color: 'bg-emerald-500' },
    { label: 'NO', text: "No, thank you.", color: 'bg-ableRed' },
    { label: 'WAIT', text: "Please wait, I am finishing a thought.", color: 'bg-ableOrange' },
    { label: 'THANKS', text: "Thank you for your help.", color: 'bg-ableYellow text-ableBlack' }
  ];

  return (
    <div className="space-y-12 py-10 animate-in slide-in-from-left-10 duration-700">
      <header className="space-y-4">
        <h2 className="text-6xl font-black text-ableYellow tracking-tighter italic">Voice Hub.</h2>
        <p className="text-2xl font-bold text-white/60">Real-time duplex conversation. ABLE is always listening.</p>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
        <section className="lg:col-span-4 bg-ableBlack border-8 border-ableYellow p-8 rounded-huge shadow-2xl space-y-8">
          <h3 className="text-3xl font-black text-ableYellow uppercase">Direct Intent</h3>
          <div className="grid grid-cols-2 gap-3">
            {soundboard.map(btn => (
              <button 
                key={btn.label}
                onClick={() => speak(btn.text)}
                className={`${btn.color} py-8 rounded-3xl font-black text-2xl shadow-xl active:scale-95 transition-all text-white border-2 border-white/20`}
              >
                {btn.label}
              </button>
            ))}
          </div>

          <div className="pt-6 space-y-4 border-t-2 border-white/5">
            <div className="relative">
              <input 
                value={chatInput}
                onChange={(e) => setChatInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleManualSend()}
                placeholder="TYPE MESSAGE..."
                className="w-full bg-white/5 border-4 border-white/20 rounded-huge px-6 py-5 pr-16 text-xl font-black text-white outline-none focus:border-ableYellow"
              />
              <button onClick={startFieldDictation} className={`absolute right-4 top-1/2 -translate-y-1/2 w-10 h-10 rounded-xl flex items-center justify-center ${isDictatingField ? 'bg-ableYellow animate-pulse' : 'bg-white/10'}`}>🎙️</button>
            </div>
            <button onClick={handleManualSend} className="w-full py-6 bg-white text-ableBlack rounded-huge font-black text-2xl active:scale-95">SEND TEXT</button>
          </div>
        </section>

        <section className="lg:col-span-8 bg-ableBlack border-8 border-ableOrange p-10 rounded-huge shadow-2xl flex flex-col min-h-[600px]">
           <div className="flex justify-between items-center mb-8">
            <h3 className="text-4xl font-black text-ableOrange uppercase tracking-tighter italic">Conversation</h3>
            <div className={`px-4 py-1 border-2 rounded-xl text-[10px] font-black tracking-widest ${isLiveActive ? 'bg-emerald-500 border-white animate-pulse' : 'bg-ableOrange/10 border-ableOrange'}`}>
              {ifiStatus.toUpperCase()}
            </div>
          </div>

          <div ref={scrollRef} className="flex-1 bg-white/5 border-4 border-white/10 rounded-3xl p-8 overflow-y-auto no-scrollbar space-y-6 mb-8">
            {history.length === 0 && (
              <div className="h-full flex flex-col items-center justify-center opacity-10">
                <div className="text-9xl">🎙️</div>
                <p className="font-black uppercase tracking-[0.4em]">Mic Active for Live Chat</p>
              </div>
            )}
            {history.map((msg, i) => (
              <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[80%] p-6 rounded-3xl font-bold text-2xl leading-tight ${msg.role === 'user' ? 'bg-white/10 text-white border-2 border-white/10' : 'bg-ableOrange text-white shadow-xl italic'}`}>
                  {msg.text}
                </div>
              </div>
            ))}
            {isThinking && <div className="bg-white/5 text-white/40 p-4 rounded-3xl italic animate-pulse">Syncing...</div>}
          </div>

          <div className="flex flex-col items-center gap-4">
            <button 
              onClick={isLiveActive ? stopLiveSession : startLiveSession}
              className={`w-32 h-32 rounded-full flex items-center justify-center text-6xl shadow-huge transition-all active:scale-90 ${isLiveActive ? 'bg-ableRed animate-pulse' : 'bg-ableOrange hover:scale-105'}`}
            >
              {isLiveActive ? '⏹' : '🎙️'}
            </button>
            <p className="text-xs font-black uppercase tracking-[0.5em] text-ableOrange opacity-60">
              {isLiveActive ? 'LIVE CONVERSATION ACTIVE' : 'START REAL-TIME CHAT'}
            </p>
          </div>
        </section>
      </div>
    </div>
  );
};

export default CommHub;

