  const frameIntervalRef = useRef<number | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [history]);

  useEffect(() => {
    return () => {
      stopLiveSession();
      if (mediaStreamRef.current) mediaStreamRef.current.getTracks().forEach(t => t.stop());
    };
  }, []);

  const stopLiveSession = useCallback(() => {
    if (sessionRef.current) sessionRef.current.close();
    sessionRef.current = null;
    if (frameIntervalRef.current) window.clearInterval(frameIntervalRef.current);
    frameIntervalRef.current = null;
    if (inputAudioContextRef.current) inputAudioContextRef.current.close();
    if (outputAudioContextRef.current) outputAudioContextRef.current.close();
    setIsLiveActive(false);
    setStatus('STANDBY');
  }, []);

  const startLiveSession = useCallback(async () => {
    try {
      setStatus('CONNECTING...');
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

      const audioStream = await navigator.mediaDevices.getUserMedia({ audio: true });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setIsLiveActive(true);
            setStatus('LIVE DUPLEX');

            // Audio Stream
            const source = inputAudioContextRef.current!.createMediaStreamSource(audioStream);
            const scriptProcessor = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              sessionPromise.then(s => s.sendRealtimeInput({ media: createBlob(inputData) }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputAudioContextRef.current!.destination);

            // Video Frame Stream
            frameIntervalRef.current = window.setInterval(() => {
              if (videoRef.current && canvasRef.current) {
                const canvas = canvasRef.current;
                const video = videoRef.current;
                canvas.width = 640;
                canvas.height = 480;
                canvas.getContext('2d')?.drawImage(video, 0, 0, 640, 480);
                canvas.toBlob((blob) => {
                  if (blob) {
                    const reader = new FileReader();
                    reader.onloadend = () => {
                      const base64 = (reader.result as string).split(',')[1];
                      sessionPromise.then(s => s.sendRealtimeInput({ media: { data: base64, mimeType: 'image/jpeg' } }));
                    };
                    reader.readAsDataURL(blob);
                  }
                }, 'image/jpeg', 0.5);
              }
            }, 1000); // 1 frame per second for context
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.serverContent?.modelTurn) {
              const audio = message.serverContent.modelTurn.parts[0]?.inlineData?.data;
              if (audio && outputAudioContextRef.current) {
                const ctx = outputAudioContextRef.current;
                nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
                const buffer = await decodeAudioData(decode(audio), ctx, 24000, 1);
                const source = ctx.createBufferSource();
                source.buffer = buffer;
                source.connect(ctx.destination);
                source.start(nextStartTimeRef.current);
                nextStartTimeRef.current += buffer.duration;
              }
            }
            if (message.serverContent?.outputTranscription) {
              setHistory(prev => [...prev, { role: 'assistant', text: message.serverContent!.outputTranscription!.text }]);
            }
            if (message.serverContent?.inputTranscription) {
              setHistory(prev => [...prev, { role: 'user', text: message.serverContent!.inputTranscription!.text }]);
            }
          },
          onerror: (e) => stopLiveSession(),
          onclose: () => setIsLiveActive(false),
        },
        config: {
          responseModalities: [Modality.AUDIO],
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          systemInstruction: "You are ABLE. Humanoid vision assistant. Be extremely concise."
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (e) {
      setStatus('ERROR');
      console.error(e);
    }
  }, [stopLiveSession]);

  const toggleVision = async () => {
    if (isVisionActive) {
      stopLiveSession();
      if (mediaStreamRef.current) mediaStreamRef.current.getTracks().forEach(t => t.stop());
      setIsVisionActive(false);
      setStatus('OFF');
    } else {
      try {
        setStatus('WAKING UP...');
        const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
        mediaStreamRef.current = stream;
        if (videoRef.current) videoRef.current.srcObject = stream;
        setIsVisionActive(true);
        startLiveSession();
      } catch (err) {
        setStatus('ERROR');
      }
    }
  };

  return (
    <div className={`flex flex-col space-y-8 py-6 w-full ${uiIntensity === 'simplified' ? 'max-w-2xl mx-auto' : 'max-w-full'}`}>
      <canvas ref={canvasRef} className="hidden" />
      <header className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6">
        <div className="space-y-1">
           <h2 className="text-5xl font-black text-ableYellow tracking-tighter uppercase leading-none italic">Vision Hub</h2>
           <div className="flex items-center space-x-3">
             <div className={`w-3 h-3 rounded-full ${isVisionActive ? 'bg-emerald-500 animate-pulse' : 'bg-white/10'}`}></div>
             <p className="text-[10px] font-black text-white/40 uppercase tracking-[0.5em]">{status}</p>
           </div>
        </div>

        <button onClick={toggleVision} className={`px-10 py-5 rounded-huge font-black text-xl border-4 transition-all shadow-huge ${isVisionActive ? 'bg-ableRed border-white text-white' : 'bg-ableYellow text-ableBlack'}`}>
          {isVisionActive ? 'STOP LIVE AI' : 'START LIVE AI'}
        </button>
      </header>

      <div className={`grid grid-cols-1 ${uiIntensity === 'simplified' ? '' : 'xl:grid-cols-12'} gap-8 w-full`}>
        <div className="xl:col-span-7 bg-black border-8 border-ableYellow rounded-huge overflow-hidden relative aspect-video shadow-2xl flex items-center justify-center">
          <video ref={videoRef} autoPlay playsInline muted className="w-full h-full object-cover" />
          {!isVisionActive && <div className="absolute inset-0 bg-black/80 flex items-center justify-center text-white/20 font-black uppercase text-4xl">Eye Standby</div>}
          <div className="absolute bottom-6 right-6 w-32 md:w-48 shadow-huge">
             <SignLanguageAvatar message={history[history.length-1]?.text} active={isLiveActive} />
          </div>
        </div>

        <div className="xl:col-span-5 flex flex-col gap-6">
           <div className="bg-white/5 border-4 border-white/10 p-8 rounded-huge shadow-xl h-[500px] flex flex-col overflow-hidden">
              <div ref={scrollRef} className="flex-1 overflow-y-auto no-scrollbar space-y-4">
                {history.map((msg, i) => (
                  <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                    <div className={`max-w-[85%] p-4 rounded-3xl font-bold ${msg.role === 'user' ? 'bg-white/10 text-white' : 'bg-ableYellow text-ableBlack'}`}>
                      {msg.text}
                    </div>
                  </div>
                ))}
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

