import React, { useState, useEffect, useCallback, useRef } from 'react';
import { useAbility } from '../context/AbilityContext';
import { GoogleGenAI, Modality, LiveServerMessage } from '@google/genai';
import { encode, decode, decodeAudioData, createBlob } from '../services/audioService';

interface ChatMessage {
  role: 'user' | 'assistant';
  text: string;
}

const CommHub: React.FC = () => {
  const { pad, speak } = useAbility();
  const [isLiveActive, setIsLiveActive] = useState(false);
  const [ifiStatus, setIfiStatus] = useState('Standby');
  const [history, setHistory] = useState<ChatMessage[]>([]);
  const [chatInput, setChatInput] = useState('');
  const [isThinking, setIsThinking] = useState(false);

  const audioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const sessionRef = useRef<any>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const currentOutputTranscriptionRef = useRef('');
  const currentInputTranscriptionRef = useRef('');

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [history]);

  const stopLiveSession = useCallback(() => {
    if (sessionRef.current) {
      sessionRef.current.close();
      sessionRef.current = null;
    }
    if (audioContextRef.current) {
      audioContextRef.current.close();
      audioContextRef.current = null;
    }
    if (outputAudioContextRef.current) {
      outputAudioContextRef.current.close();
      outputAudioContextRef.current = null;
    }
    for (const source of sourcesRef.current) {
      try { source.stop(); } catch(e) {}
    }
    sourcesRef.current.clear();
    setIsLiveActive(false);
    setIfiStatus('Standby');
  }, []);

  const startLiveSession = useCallback(async () => {
    try {
      setIfiStatus('Connecting...');
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setIsLiveActive(true);
            setIfiStatus('Listening...');

            const source = audioContextRef.current!.createMediaStreamSource(stream);
            const scriptProcessor = audioContextRef.current!.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBlob = createBlob(inputData);
              sessionPromise.then(session => {
                session.sendRealtimeInput({ media: pcmBlob });
              });
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(audioContextRef.current!.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.serverContent?.outputTranscription) {
              currentOutputTranscriptionRef.current += message.serverContent.outputTranscription.text;
            } else if (message.serverContent?.inputTranscription) {
              currentInputTranscriptionRef.current += message.serverContent.inputTranscription.text;
            }

            if (message.serverContent?.turnComplete) {
              const userText = currentInputTranscriptionRef.current;
              const assistantText = currentOutputTranscriptionRef.current;

              if (userText || assistantText) {
                setHistory(prev => [
                  ...prev, 
                  ...(userText ? [{ role: 'user' as const, text: userText }] : []),
                  ...(assistantText ? [{ role: 'assistant' as const, text: assistantText }] : [])
                ]);
              }

              currentInputTranscriptionRef.current = '';
              currentOutputTranscriptionRef.current = '';

              // Stop mic after turn is complete as per user request
              stopLiveSession();
              setIfiStatus('Turn Complete - Mic Off');
            }

            const audioData = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audioData && outputAudioContextRef.current) {
              const ctx = outputAudioContextRef.current;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const buffer = await decodeAudioData(decode(audioData), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = buffer;
              source.connect(ctx.destination);
              source.addEventListener('ended', () => sourcesRef.current.delete(source));
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              sourcesRef.current.add(source);
            }
          },
          onerror: (e) => stopLiveSession(),
          onclose: () => setIsLiveActive(false)
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: pad.voicePreference === 'calm-female' ? 'Kore' : 'Zephyr' } },
          },
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          systemInstruction: `You are ABLE, an empathetic AI. Be concise. Respond within 2 sentences.`
        }
      });

      sessionRef.current = await sessionPromise;
    } catch (e) {
      setIfiStatus('Mic Error');
      speak("Mic access denied.");
    }
  }, [pad.voicePreference, speak, stopLiveSession]);

  const handleManualSend = async () => {
    if (!chatInput.trim()) return;
    setHistory(prev => [...prev, { role: 'user', text: chatInput }]);
    setChatInput('');
    setIsThinking(true);
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      const res = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: chatInput,
        config: { systemInstruction: "Humanoid, concise (max 2 sentences)." }
      });
      const txt = res.text || "...";
      setHistory(prev => [...prev, { role: 'assistant', text: txt }]);
      speak(txt);
    } catch(e) { console.error(e); }
    finally { setIsThinking(false); }
  };

  return (
    <div className="space-y-12 py-10 animate-in slide-in-from-left-10 duration-700">
      <header className="space-y-4">
        <h2 className="text-6xl font-black text-ableYellow tracking-tighter italic">Voice Hub.</h2>
