                            <p className="text-sm font-bold opacity-40">{alertedContacts.has(i) ? 'DATA TRANSMITTED' : 'TAP TO ALERT'}</p>
                          </div>
                          <span className={`text-4xl ${alertedContacts.has(i) ? 'animate-bounce' : ''}`}>
                            {alertedContacts.has(i) ? '🛰️' : '📞'}
