            className={`w-16 h-16 rounded-2xl flex items-center justify-center border-4 transition-all hover:scale-105 active:scale-90 ${isHighContrast ? 'bg-ableYellow border-white text-ableBlack shadow-glow' : 'bg-white/5 border-white/10 text-white'}`}
