import React, { useState, useRef, useEffect, useCallback } from 'react';
import { useAbility } from '../context/AbilityContext';
import SignLanguageAvatar from './SignLanguageAvatar';
import { GoogleGenAI, Modality, LiveServerMessage } from '@google/genai';
import { encode, decode, decodeAudioData, createBlob } from '../services/audioService';

interface ChatMessage {
  role: 'user' | 'assistant';
  text: string;
}

const AICompanion: React.FC = () => {
  const { pad, speak, uiIntensity } = useAbility();
  const [isVisionActive, setIsVisionActive] = useState(false);
  const [status, setStatus] = useState('STANDBY');
  const [history, setHistory] = useState<ChatMessage[]>([]);
  const [isLiveActive, setIsLiveActive] = useState(false);

  // Real-time transcription state
  const [currentInputText, setCurrentInputText] = useState('');
  const [currentOutputText, setCurrentOutputText] = useState('');

  const videoRef = useRef<HTMLVideoElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null);
  const sessionRef = useRef<any>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const frameIntervalRef = useRef<number | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  // Refs for accumulation to avoid state lag in callbacks
  const accumulatedInputRef = useRef('');
  const accumulatedOutputRef = useRef('');

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [history, currentInputText, currentOutputText]);

  const stopLiveSession = useCallback(() => {
    if (sessionRef.current) {
      try { sessionRef.current.close(); } catch(e) {}
      sessionRef.current = null;
    }
    if (frameIntervalRef.current) window.clearInterval(frameIntervalRef.current);
    frameIntervalRef.current = null;

    if (inputAudioContextRef.current) {
      try { inputAudioContextRef.current.close(); } catch(e) {}
      inputAudioContextRef.current = null;
    }
    if (outputAudioContextRef.current) {
      try { outputAudioContextRef.current.close(); } catch(e) {}
      outputAudioContextRef.current = null;
    }

    sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
    sourcesRef.current.clear();

    setIsLiveActive(false);
    setStatus('STANDBY');
    setCurrentInputText('');
    setCurrentOutputText('');
    accumulatedInputRef.current = '';
    accumulatedOutputRef.current = '';
  }, []);

  const startLiveSession = useCallback(async () => {
    try {
      setStatus('CONNECTING...');
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

      const audioStream = await navigator.mediaDevices.getUserMedia({ audio: true });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setIsLiveActive(true);
            setStatus('EYES + EARS ACTIVE');

            // Audio Input Stream
            const source = inputAudioContextRef.current!.createMediaStreamSource(audioStream);
            const scriptProcessor = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              sessionPromise.then(s => s.sendRealtimeInput({ media: createBlob(inputData) }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputAudioContextRef.current!.destination);

            // Visual Frame Stream (Context for AI)
            frameIntervalRef.current = window.setInterval(() => {
              if (videoRef.current && canvasRef.current && canvasRef.current.getContext('2d')) {
                const canvas = canvasRef.current;
                const video = videoRef.current;
                canvas.width = 480; // Lower resolution for streaming speed
                canvas.height = 360;
                canvas.getContext('2d')?.drawImage(video, 0, 0, 480, 360);
                canvas.toBlob((blob) => {
                  if (blob) {
                    const reader = new FileReader();
                    reader.onloadend = () => {
                      const base64 = (reader.result as string).split(',')[1];
                      sessionPromise.then(s => s.sendRealtimeInput({ 
                        media: { data: base64, mimeType: 'image/jpeg' } 
                      }));
                    };
                    reader.readAsDataURL(blob);
                  }
                }, 'image/jpeg', 0.4);
              }
            }, 2000); // 1 frame every 2 seconds is enough for steady analysis
          },
          onmessage: async (message: LiveServerMessage) => {
            // Audio Output Playback
            if (message.serverContent?.modelTurn) {
              const audio = message.serverContent.modelTurn.parts[0]?.inlineData?.data;
              if (audio && outputAudioContextRef.current) {
                const ctx = outputAudioContextRef.current;
                nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
                const buffer = await decodeAudioData(decode(audio), ctx, 24000, 1);
                const source = ctx.createBufferSource();
                source.buffer = buffer;
                source.connect(ctx.destination);
                source.addEventListener('ended', () => sourcesRef.current.delete(source));
                source.start(nextStartTimeRef.current);
                nextStartTimeRef.current += buffer.duration;
                sourcesRef.current.add(source);
              }
            }

            // Real-time Transcription Accumulation
            if (message.serverContent?.inputTranscription) {
              accumulatedInputRef.current += message.serverContent.inputTranscription.text;
              setCurrentInputText(accumulatedInputRef.current);
            }
            if (message.serverContent?.outputTranscription) {
              accumulatedOutputRef.current += message.serverContent.outputTranscription.text;
              setCurrentOutputText(accumulatedOutputRef.current);
            }

            // Interrupt logic
            if (message.serverContent?.interrupted) {
              sourcesRef.current.forEach(s => s.stop());
              sourcesRef.current.clear();
              nextStartTimeRef.current = 0;
            }

            // End of Turn Logic
            if (message.serverContent?.turnComplete) {
              const finalInput = accumulatedInputRef.current;
              const finalOutput = accumulatedOutputRef.current;

              if (finalInput || finalOutput) {
                setHistory(prev => [
                  ...prev,
                  ...(finalInput ? [{ role: 'user' as const, text: finalInput }] : []),
                  ...(finalOutput ? [{ role: 'assistant' as const, text: finalOutput }] : [])
                ]);
              }

              // Reset accumulators for next time
              accumulatedInputRef.current = '';
              accumulatedOutputRef.current = '';
              setCurrentInputText('');
              setCurrentOutputText('');

              // Stop session automatically to allow user to process answer
              stopLiveSession();
              setStatus('ANSWER COMPLETE - MIC STOPPED');
            }
          },
          onerror: (e) => {
            console.error("Live API Error:", e);
            stopLiveSession();
          },
          onclose: () => setIsLiveActive(false),
        },
        config: {
          responseModalities: [Modality.AUDIO],
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          speechConfig: {
            voiceConfig: { 
              prebuiltVoiceConfig: { 
                voiceName: pad.voicePreference === 'calm-female' ? 'Kore' : 'Zephyr' 
              } 
            },
          },
          systemInstruction: `You are ABLE, a humanoid supportive AI assistant for users with accessibility needs. 
          Current Vision Context: ${pad.visual}.
          STRICT RULES:
          1. Be extremely humanoid and supportive. 
          2. Every response MUST be maximum TWO sentences.
          3. Do NOT interrupt the user. Be patient with pauses or stutters; wait for them to finish naturally.
          4. Vary your greetings and responses to stay non-repetitive.
          5. Use the visual stream to provide helpful, direct feedback about what you see.`
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (e) {
      setStatus('ERROR');
      console.error(e);
      speak("Connection error. Please try again.");
    }
  }, [pad, stopLiveSession, speak]);

  const toggleVision = async () => {
    if (isVisionActive) {
      stopLiveSession();
      if (mediaStreamRef.current) mediaStreamRef.current.getTracks().forEach(t => t.stop());
      mediaStreamRef.current = null;
      setIsVisionActive(false);
      setStatus('OFF');
    } else {
      try {
        setStatus('WAKING UP...');
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 720 } } 
        });
        mediaStreamRef.current = stream;
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          videoRef.current.onloadedmetadata = () => {
            videoRef.current?.play();
            setIsVisionActive(true);
            startLiveSession();
          };
        }
      } catch (err) {
        setStatus('CAMERA ERROR');
        speak("Camera access failed. Check permissions.");
      }
    }
  };

  return (
    <div className={`flex flex-col space-y-8 py-6 w-full ${uiIntensity === 'simplified' ? 'max-w-2xl mx-auto' : 'max-w-full'}`}>
      <canvas ref={canvasRef} className="hidden" />

      <header className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6">
        <div className="space-y-1">
           <h2 className="text-5xl font-black text-ableYellow tracking-tighter uppercase leading-none italic">Vision Hub</h2>
           <div className="flex items-center space-x-3">
             <div className={`w-3 h-3 rounded-full ${isVisionActive ? 'bg-emerald-500 animate-pulse' : 'bg-white/10'}`}></div>
             <p className="text-[10px] font-black uppercase tracking-[0.5em] text-white/40">{status}</p>
           </div>
        </div>

        <button 
          onClick={toggleVision} 
          className={`px-10 py-5 rounded-huge font-black text-xl border-4 transition-all shadow-huge active:scale-95 ${isVisionActive ? 'bg-ableRed border-white text-white' : 'bg-ableYellow border-transparent text-ableBlack'}`}
        >
          {isVisionActive ? 'STOP LIVE AI' : 'START LIVE AI'}
        </button>
      </header>

      <div className={`grid grid-cols-1 ${uiIntensity === 'simplified' ? '' : 'xl:grid-cols-12'} gap-8 w-full h-[600px]`}>
        {/* Visual Feed */}
        <div className="xl:col-span-7 bg-black border-8 border-ableYellow rounded-huge overflow-hidden relative shadow-2xl flex items-center justify-center group">
          <video 
            ref={videoRef} 
            autoPlay 
            playsInline 
            muted 
            className={`w-full h-full object-cover transition-opacity duration-1000 ${isVisionActive ? 'opacity-100' : 'opacity-20'}`} 
          />
          {!isVisionActive && (
            <div className="absolute inset-0 flex flex-col items-center justify-center text-white/20 gap-4">
              <span className="text-9xl">👁️</span>
              <span className="font-black uppercase tracking-widest text-xl">LENS CLOSED</span>
            </div>
          )}

          <div className="absolute bottom-6 right-6 w-32 md:w-48 shadow-huge pointer-events-none">
             <SignLanguageAvatar 
               message={currentOutputText || history[history.length-1]?.text} 
               active={isLiveActive || !!currentOutputText} 
             />
          </div>
        </div>

        {/* Dynamic Communication Log */}
        <div className="xl:col-span-5 flex flex-col h-full">
           <div className="bg-white/5 border-4 border-white/10 p-8 rounded-huge shadow-xl flex-1 flex flex-col overflow-hidden">
              <h3 className="text-xs font-black text-white/30 uppercase tracking-[0.4em] mb-6">Interaction Stream</h3>

              <div ref={scrollRef} className="flex-1 overflow-y-auto no-scrollbar space-y-6 pr-2">
                {history.length === 0 && !currentInputText && !currentOutputText && (
                  <div className="h-full flex flex-col items-center justify-center opacity-10 text-center">
                    <p className="font-black uppercase tracking-widest text-sm">Waiting for live data sync...</p>
                  </div>
                )}

                {history.map((msg, i) => (
                  <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-in slide-in-from-bottom-2`}>
                    <div className={`max-w-[90%] p-5 rounded-3xl font-bold text-lg leading-snug ${msg.role === 'user' ? 'bg-white/10 text-white' : 'bg-ableYellow text-ableBlack shadow-lg'}`}>
                      {msg.text}
                    </div>
                  </div>
                ))}

                {/* Real-time Partial Transcriptions */}
                {currentInputText && (
                  <div className="flex justify-end opacity-60">
                    <div className="max-w-[90%] p-5 rounded-3xl font-bold text-lg bg-white/5 text-white border-2 border-dashed border-white/20 italic">
                      {currentInputText}...
                    </div>
                  </div>
                )}
                {currentOutputText && (
                  <div className="flex justify-start">
                    <div className="max-w-[90%] p-5 rounded-3xl font-bold text-lg bg-ableYellow text-ableBlack shadow-xl animate-pulse">
                      {currentOutputText}
                    </div>
                  </div>
                )}
              </div>

              {/* Status Footer */}
              <div className="mt-6 pt-6 border-t-2 border-white/5 flex justify-between items-center">
                <div className="flex items-center gap-3">
                  <div className={`w-3 h-3 rounded-full ${isLiveActive ? 'bg-emerald-500 animate-ping' : 'bg-white/10'}`}></div>
                  <span className="text-[10px] font-black text-white/40 uppercase tracking-widest">
                    {isLiveActive ? 'MIC OPEN: LISTENING' : 'MIC CLOSED: TAP TO TALK'}
                  </span>
                </div>
                {isLiveActive && (
                  <button 
                    onClick={stopLiveSession}
                    className="text-[10px] font-black text-ableRed uppercase tracking-widest border-b border-ableRed pb-1"
                  >
                    FORCE MUTE
                  </button>
                )}
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

