          5. Maintain an empathetic, humanoid tone at all times.`
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (e) {
      setStatus('ERROR');
      console.error(e);
      speak("System sync failed. Please try again.");
    }
  }, [pad, stopLiveSession, speak]);

  const toggleVision = async () => {
    if (isVisionActive) {
      stopLiveSession(true);
      if (mediaStreamRef.current) mediaStreamRef.current.getTracks().forEach(t => t.stop());
      mediaStreamRef.current = null;
      setIsVisionActive(false);
    } else {
      try {
        setStatus('WAKING UP...');
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 720 } } 
        });
        mediaStreamRef.current = stream;
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          videoRef.current.onloadedmetadata = () => {
            videoRef.current?.play();
            setIsVisionActive(true);
            startLiveSession();
          };
        }
      } catch (err) {
        setStatus('EYE ERROR');
        speak("Camera access failed.");
      }
    }
  };

  return (
    <div className={`flex flex-col space-y-8 py-6 w-full ${uiIntensity === 'simplified' ? 'max-w-3xl mx-auto' : 'max-w-full'}`}>
      <canvas ref={canvasRef} className="hidden" />

