           </div>
        </div>

        <button 
          onClick={toggleVision} 
          className={`px-12 py-6 rounded-huge font-black text-2xl border-4 transition-all shadow-huge active:scale-95 ${isVisionActive ? 'bg-ableRed border-white text-white' : 'bg-ableYellow border-transparent text-ableBlack'}`}
        >
          {isVisionActive ? 'END SESSION' : 'START LIVE AI'}
        </button>
      </header>

      <div className={`grid grid-cols-1 ${uiIntensity === 'simplified' ? '' : 'xl:grid-cols-12'} gap-10 w-full h-[650px]`}>
        {/* Visual Engine */}
        <div className="xl:col-span-7 bg-black border-8 border-ableYellow rounded-huge overflow-hidden relative shadow-2xl flex items-center justify-center">
          <video 
