import React, { useState, useRef, useEffect, useCallback } from 'react';
import { useAbility } from '../context/AbilityContext';
import SignLanguageAvatar from './SignLanguageAvatar';
import { GoogleGenAI, Modality, LiveServerMessage } from '@google/genai';
import { encode, decode, decodeAudioData, createBlob } from '../services/audioService';

interface ChatMessage {
  role: 'user' | 'assistant';
  text: string;
}

const AICompanion: React.FC = () => {
  const { pad, speak, uiIntensity } = useAbility();
  const [isVisionActive, setIsVisionActive] = useState(false);
  const [status, setStatus] = useState('STANDBY');
  const [history, setHistory] = useState<ChatMessage[]>([]);
  const [isLiveActive, setIsLiveActive] = useState(false);
  const [isThinking, setIsThinking] = useState(false);

  const [currentInputText, setCurrentInputText] = useState('');
  const [currentOutputText, setCurrentOutputText] = useState('');

  const videoRef = useRef<HTMLVideoElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null);
  const sessionRef = useRef<any>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const frameIntervalRef = useRef<number | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  const accumulatedInputRef = useRef('');
  const accumulatedOutputRef = useRef('');

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [history, currentInputText, currentOutputText]);

  const stopLiveSession = useCallback((force = false) => {
    if (sessionRef.current) {
      try { sessionRef.current.close(); } catch(e) {}
      sessionRef.current = null;
    }
    if (frameIntervalRef.current) window.clearInterval(frameIntervalRef.current);
    frameIntervalRef.current = null;

    if (inputAudioContextRef.current) {
      try { inputAudioContextRef.current.close(); } catch(e) {}
      inputAudioContextRef.current = null;
    }

    if (force && outputAudioContextRef.current) {
      try { outputAudioContextRef.current.close(); } catch(e) {}
      outputAudioContextRef.current = null;
      sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
      sourcesRef.current.clear();
    }

    setIsLiveActive(false);
    setIsThinking(false);
    setStatus('STANDBY');
    setCurrentInputText('');
    setCurrentOutputText('');
    accumulatedInputRef.current = '';
    accumulatedOutputRef.current = '';
  }, []);

  const startLiveSession = useCallback(async () => {
    try {
      setStatus('CONNECTING...');
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

      const audioStream = await navigator.mediaDevices.getUserMedia({ audio: true });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setIsLiveActive(true);
            setStatus('LISTENING');

            const source = inputAudioContextRef.current!.createMediaStreamSource(audioStream);
            const scriptProcessor = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              sessionPromise.then(s => s.sendRealtimeInput({ media: createBlob(inputData) }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputAudioContextRef.current!.destination);

            frameIntervalRef.current = window.setInterval(() => {
              if (videoRef.current && canvasRef.current) {
                const canvas = canvasRef.current;
                const video = videoRef.current;
                canvas.width = 640;
                canvas.height = 480;
                const ctx = canvas.getContext('2d');
                if (ctx) {
                  ctx.drawImage(video, 0, 0, 640, 480);
                  canvas.toBlob((blob) => {
                    if (blob) {
                      const reader = new FileReader();
                      reader.onloadend = () => {
                        const base64 = (reader.result as string).split(',')[1];
                        sessionPromise.then(s => s.sendRealtimeInput({ media: { data: base64, mimeType: 'image/jpeg' } }));
                      };
                      reader.readAsDataURL(blob);
                    }
                  }, 'image/jpeg', 0.5);
                }
              }
            }, 1000);
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.serverContent?.modelTurn) {
              setIsThinking(false);
              const audio = message.serverContent.modelTurn.parts[0]?.inlineData?.data;
              if (audio && outputAudioContextRef.current) {
                const ctx = outputAudioContextRef.current;
                nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
                const buffer = await decodeAudioData(decode(audio), ctx, 24000, 1);
                const source = ctx.createBufferSource();
                source.buffer = buffer;
                source.connect(ctx.destination);
                source.addEventListener('ended', () => sourcesRef.current.delete(source));
                source.start(nextStartTimeRef.current);
                nextStartTimeRef.current += buffer.duration;
                sourcesRef.current.add(source);
              }
            }

            if (message.serverContent?.inputTranscription) {
              accumulatedInputRef.current += message.serverContent.inputTranscription.text;
              setCurrentInputText(accumulatedInputRef.current);
              setIsThinking(true);
              setStatus('PROCESSING...');
            }
            if (message.serverContent?.outputTranscription) {
              accumulatedOutputRef.current += message.serverContent.outputTranscription.text;
              setCurrentOutputText(accumulatedOutputRef.current);
            }

            if (message.serverContent?.interrupted) {
              sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
              sourcesRef.current.clear();
              nextStartTimeRef.current = 0;
            }

            if (message.serverContent?.turnComplete) {
              const finalInput = accumulatedInputRef.current;
              const finalOutput = accumulatedOutputRef.current;
              if (finalInput || finalOutput) {
                setHistory(prev => [
                  ...prev,
                  ...(finalInput ? [{ role: 'user' as const, text: finalInput }] : []),
                  ...(finalOutput ? [{ role: 'assistant' as const, text: finalOutput }] : [])
                ]);
              }
              accumulatedInputRef.current = '';
              accumulatedOutputRef.current = '';
              setCurrentInputText('');
              setCurrentOutputText('');

              setTimeout(() => {
                stopLiveSession();
                setStatus('TURN COMPLETE');
              }, 1500);
            }
          },
          onerror: (e) => stopLiveSession(true),
          onclose: () => setIsLiveActive(false),
        },
        config: {
          responseModalities: [Modality.AUDIO],
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: pad.voicePreference === 'calm-female' ? 'Kore' : 'Zephyr' } },
          },
          systemInstruction: `You are ABLE, an empathetic, humanoid assistant. 
          The user has visual profile: ${pad.visual}.
          RULES:
          1. MAX 2 SENTENCES per response. 
          2. Be warm, supportive, and humanoid. Avoid robotic generic phrases.
          3. Wait patiently for user speech; do not interrupt pauses or stutters.
          4. Use visual grounding from the camera to provide helpful context.
          5. Clear enunciation is vital for the user.`
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (e) {
      setStatus('ERROR');
      speak("System sync failed.");
    }
  }, [pad, stopLiveSession, speak]);

  const toggleVision = async () => {
    if (isVisionActive) {
      stopLiveSession(true);
      if (mediaStreamRef.current) mediaStreamRef.current.getTracks().forEach(t => t.stop());
      mediaStreamRef.current = null;
      setIsVisionActive(false);
    } else {
      try {
        setStatus('WAKING UP...');
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment', width: { ideal: 1280 } } 
        });
        mediaStreamRef.current = stream;
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          videoRef.current.play();
          setIsVisionActive(true);
          startLiveSession();
        }
      } catch (err) {
        setStatus('LENS ERROR');
      }
    }
  };

  return (
    <div className={`flex flex-col space-y-8 py-6 w-full ${uiIntensity === 'simplified' ? 'max-w-3xl mx-auto' : 'max-w-full'}`}>
      <canvas ref={canvasRef} className="hidden" />
      <header className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6">
        <div className="space-y-1">
           <h2 className="text-5xl font-black text-ableYellow tracking-tighter uppercase italic">Vision Hub</h2>
           <div className="flex items-center space-x-3">
             <div className={`w-3 h-3 rounded-full ${isLiveActive ? 'bg-emerald-500 animate-pulse' : 'bg-white/10'}`}></div>
             <p className="text-[10px] font-black uppercase tracking-[0.5em] text-white/40">{status}</p>
           </div>
        </div>
        <button onClick={toggleVision} className={`px-12 py-6 rounded-huge font-black text-2xl border-4 transition-all shadow-huge ${isVisionActive ? 'bg-ableRed border-white text-white' : 'bg-ableYellow border-transparent text-ableBlack'}`}>
          {isVisionActive ? 'STOP LIVE AI' : 'START LIVE AI'}
        </button>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-10 w-full h-[600px]">
        <div className="lg:col-span-7 bg-black border-8 border-ableYellow rounded-huge overflow-hidden relative shadow-2xl flex items-center justify-center">
          <video ref={videoRef} autoPlay playsInline muted className={`w-full h-full object-cover transition-opacity ${isVisionActive ? 'opacity-100' : 'opacity-20'}`} />
          {!isVisionActive && <span className="absolute text-9xl text-white/5">👁️</span>}
          <div className="absolute bottom-6 right-6 w-32 md:w-48 shadow-huge">
             <SignLanguageAvatar message={currentOutputText || history[history.length-1]?.text} active={isLiveActive || !!currentOutputText} />
          </div>
          {isThinking && (
            <div className="absolute top-6 left-6 flex items-center gap-3 bg-black/60 px-4 py-2 rounded-xl border border-white/20">
              <div className="w-2 h-2 bg-ableYellow rounded-full animate-ping"></div>
              <span className="text-[10px] font-black text-white uppercase tracking-widest">Analyzing...</span>
            </div>
          )}
        </div>

        <div className="lg:col-span-5 flex flex-col h-full space-y-4">
           <div className="bg-white/5 border-4 border-white/10 p-8 rounded-huge shadow-xl flex-1 flex flex-col overflow-hidden">
              <div ref={scrollRef} className="flex-1 overflow-y-auto no-scrollbar space-y-6">
                {history.map((msg, i) => (
                  <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                    <div className={`max-w-[90%] p-4 rounded-3xl font-bold text-lg ${msg.role === 'user' ? 'bg-white/10 text-white' : 'bg-ableYellow text-ableBlack'}`}>
                      {msg.text}
                    </div>
                  </div>
                ))}
                {currentInputText && <div className="flex justify-end opacity-40"><div className="bg-white/5 p-4 rounded-3xl italic">{currentInputText}...</div></div>}
                {currentOutputText && <div className="flex justify-start"><div className="bg-ableYellow text-ableBlack p-4 rounded-3xl shadow-xl">{currentOutputText}</div></div>}
              </div>
              {!isLiveActive && isVisionActive && (
                <button onClick={startLiveSession} className="mt-4 py-4 bg-white/10 text-white rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-white/20 transition-all">Reconnect Mic</button>
              )}
           </div>
        </div>
      </div>
    </div>
  );
};

