import React, { useEffect, useState, useCallback } from 'react';
import { useAbility } from '../context/AbilityContext';
import { APP_NAME } from '../constants';
import Logo from './Logo';

interface NavigationProps {
  activeTab: string;
  setActiveTab: (tab: string) => void;
  onEmergency: () => void;
}

const Navigation: React.FC<NavigationProps> = ({ activeTab, setActiveTab, onEmergency }) => {
  const { toggleHighContrast, isHighContrast, speak, logout, user } = useAbility();
  const [isListening, setIsListening] = useState(false);

  const tabs = [
    { id: 'dashboard', label: 'HOME', icon: '🏠' },
    { id: 'vision', label: 'VISION', icon: '👁️' },
    { id: 'voice', label: 'VOICE', icon: '🎙️' },
    { id: 'market', label: 'MARKET', icon: '🛒' },
    { id: 'career', label: 'GROWTH', icon: '📈' },
    { id: 'dna', label: 'DNA', icon: '🧬' },
    { id: 'info', label: 'INFO', icon: 'ℹ️' }
  ];

  const handleVoiceCommand = useCallback((command: string) => {
    const cmd = command.toLowerCase();
    const tabMatch = tabs.find(t => 
      cmd.includes(`go to ${t.label.toLowerCase()}`) || 
      cmd.includes(`open ${t.label.toLowerCase()}`) ||
      (cmd.includes(t.label.toLowerCase()) && cmd.split(' ').length < 3)
    );

    if (tabMatch) {
      setActiveTab(tabMatch.id);
      speak(`Opening ${tabMatch.label}`);
    } else if (cmd.includes('emergency') || cmd.includes('sos')) {
      onEmergency();
    } else if (cmd.includes('logout') || cmd.includes('sign out')) {
      logout();
    }
  }, [tabs, setActiveTab, speak, onEmergency, logout]);

  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) return;
    const recognition = new SpeechRecognition();
    recognition.continuous = true;
    recognition.onresult = (e: any) => handleVoiceCommand(e.results[e.results.length - 1][0].transcript);
    recognition.onstart = () => setIsListening(true);
    recognition.onend = () => setIsListening(false);
    try { recognition.start(); } catch (e) {}
    return () => recognition.stop();
  }, [handleVoiceCommand]);

  return (
    <>
      <div className="fixed top-0 left-0 right-0 z-[60] h-24 flex justify-between items-center px-6 md:px-10 bg-ableBlack border-b-4 border-ableYellow/20 shadow-2xl">
        <div className="flex items-center space-x-6">
          <div className="w-12 h-12 bg-white rounded-xl flex items-center justify-center shadow-glow p-1">
            <Logo />
          </div>
          <div className="flex flex-col">
            <span className="text-3xl font-black tracking-tighter text-ableYellow leading-none italic uppercase">ABLE</span>
            <span className="text-[8px] font-black text-white/30 tracking-widest uppercase">{user?.role} Mode</span>
          </div>
        </div>

        <div className="flex items-center space-x-4">
          <button onClick={toggleHighContrast} className={`w-14 h-14 rounded-2xl flex items-center justify-center border-4 transition-all ${isHighContrast ? 'bg-ableYellow border-white text-ableBlack' : 'bg-white/5 border-white/10 text-white'}`}>
            <span className="text-xl">{isHighContrast ? '☀️' : '🌙'}</span>
          </button>
          <button onClick={onEmergency} className="bg-ableRed text-white h-14 px-8 rounded-2xl font-black shadow-huge text-xl border-4 border-white/20">SOS</button>
          <button onClick={logout} className="w-14 h-14 rounded-2xl bg-white/5 border-4 border-white/10 flex items-center justify-center text-white/40 hover:text-white transition-all">🚪</button>
        </div>
      </div>

      <nav className="fixed bottom-0 left-0 right-0 z-[60] h-32 flex items-center justify-center px-4 bg-ableBlack border-t-8 border-ableYellow/10">
        <div className="w-full max-w-5xl flex items-center justify-between gap-1 overflow-x-auto no-scrollbar py-2">
          {tabs.map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`flex flex-col items-center justify-center gap-1 transition-all flex-1 py-4 px-1 rounded-huge border-4 min-w-[75px] ${
                activeTab === tab.id 
                  ? 'bg-ableYellow text-ableBlack border-white scale-110 shadow-glow' 
                  : 'bg-white/5 text-white/60 border-transparent hover:bg-white/10'
              }`}
            >
              <span className="text-2xl">{tab.icon}</span>
              <span className="text-[8px] font-black tracking-widest uppercase">{tab.label}</span>
            </button>
          ))}
        </div>
      </nav>
    </>
  );
};

