            if (message.serverContent?.outputTranscription) {
              accumulatedOutputRef.current += message.serverContent.outputTranscription.text;
              setCurrentOutputText(accumulatedOutputRef.current);
            }

            if (message.serverContent?.interrupted) {
              sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
              sourcesRef.current.clear();
              nextStartTimeRef.current = 0;
            }

            if (message.serverContent?.turnComplete) {
              const finalInput = accumulatedInputRef.current;
              const finalOutput = accumulatedOutputRef.current;
              if (finalInput || finalOutput) {
                setHistory(prev => [
                  ...prev,
                  ...(finalInput ? [{ role: 'user' as const, text: finalInput }] : []),
                  ...(finalOutput ? [{ role: 'assistant' as const, text: finalOutput }] : [])
                ]);
              }
              accumulatedInputRef.current = '';
              accumulatedOutputRef.current = '';
              setCurrentInputText('');
              setCurrentOutputText('');

              setTimeout(() => {
                stopLiveSession();
                setStatus('TURN COMPLETE');
              }, 1500);
            }
          },
          onerror: (e) => stopLiveSession(true),
          onclose: () => setIsLiveActive(false),
        },
        config: {
          responseModalities: [Modality.AUDIO],
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          speechConfig: {
            voiceConfig: { 
              prebuiltVoiceConfig: { 
                voiceName: pad.voicePreference === 'calm-female' ? 'Kore' : 'Zephyr' 
              } 
            },
          },
          systemInstruction: `You are ABLE, an empathetic, humanoid companion.
          STRICT RULES:
          1. MAXIMUM TWO SENTENCES per response.
          2. ALWAYS vary your responses. NEVER start twice in a row with the same phrase (e.g., "I see", "I understand").
          3. Be humanoid and warm, not a sterile assistant. Use conversational filler words occasionally if it feels natural.
          4. Wait patiently for user speech; do not interrupt pauses or stutters.
          5. Use the visual context from the camera frames to provide helpful, direct feedback about surroundings.
          6. Your goal is to help the user feel independent and supported.`
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (e) {
      setStatus('ERROR');
      speak("System sync failed.");
    }
  }, [pad, stopLiveSession, speak]);

  const toggleVision = async () => {
    if (isVisionActive) {
      stopLiveSession(true);
      if (mediaStreamRef.current) mediaStreamRef.current.getTracks().forEach(t => t.stop());
      mediaStreamRef.current = null;
      setIsVisionActive(false);
    } else {
      try {
        setStatus('WAKING UP...');
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment', width: { ideal: 1280 } } 
        });
        mediaStreamRef.current = stream;
