          <div className="max-w-xl mx-auto space-y-8 bg-white/5 border-4 border-white/10 p-12 rounded-huge">
            <p className="text-xl font-bold text-center text-white/60 italic">Enter the unique sync code provided by your mentee's specialist.</p>
            <input type="text" placeholder="CODE-2025" className="w-full bg-black/40 border-4 border-white/10 rounded-2xl px-8 py-6 text-3xl font-black text-center text-emerald-500 uppercase outline-none focus:border-emerald-500 transition-all" />
            <button className="w-full py-6 bg-emerald-500 text-white rounded-3xl font-black text-2xl shadow-huge active:scale-95 transition-all" onClick={() => speak("Verifying sync code.")}>ESTABLISH CONNECTION</button>
          </div>
        </div>
      );
    default: return <Dashboard />;
  }
};

const AppContent: React.FC = () => {
  const { isLoggedIn, user } = useAbility();
  const [activeTab, setActiveTab] = useState('dashboard');
  const [showEmergency, setShowEmergency] = useState(false);
  const [showReport, setShowReport] = useState(false);

  if (!isLoggedIn) return <AuthFlow />;

  const renderContent = () => {
    if (user?.role === UserRole.Specialist) return <SpecialistPortal tab={activeTab} />;
    if (user?.role === UserRole.Mentor) return <MentorPortal tab={activeTab} />;

    switch (activeTab) {
      case 'dashboard': return <Dashboard />;
      case 'vision': return <VisionAI />;
      case 'voice': return <CommHub />;
      case 'market': return <Shop />;
      case 'career': return <CareerHub />;
      case 'dna': return <PADSettings />;
      case 'info': return <InfoPage />;
      default: return <Dashboard />;
    }
  };

  return (
    <div className={`h-[100dvh] w-full flex flex-col bg-ableBlack overflow-hidden relative ${user?.role === UserRole.Specialist ? 'selection:bg-blue-500' : user?.role === UserRole.Mentor ? 'selection:bg-emerald-500' : 'selection:bg-ableYellow'}`}>
      <Navigation 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        onEmergency={() => setShowEmergency(true)} 
      />

      <div className="flex-1 flex flex-col w-full overflow-hidden pt-24 pb-32">
        <main className="flex-1 overflow-y-auto overflow-x-hidden no-scrollbar px-4 md:px-10">
          <div className="max-w-7xl mx-auto py-8">
            <header className="flex justify-between items-center mb-12">
               <div className="flex items-center gap-4 bg-white/5 px-6 py-3 rounded-2xl border border-white/10 backdrop-blur-md">
                 <div className={`w-3 h-3 rounded-full animate-pulse ${user?.role === UserRole.Specialist ? 'bg-blue-500' : user?.role === UserRole.Mentor ? 'bg-emerald-500' : 'bg-ableYellow'}`}></div>
                 <span className="text-[10px] font-black text-white/40 uppercase tracking-widest">{user?.name} // {user?.role.replace('-', ' ')}</span>
               </div>
               <button 
                 onClick={() => setShowReport(true)}
                 className="group relative px-6 py-3 overflow-hidden rounded-full border-2 border-white/20 text-white/40 font-black text-[10px] tracking-[0.2em] transition-all hover:border-ableRed hover:text-ableRed active:scale-95 uppercase"
               >
                 REPORT FRICTION
               </button>
            </header>

            <div className="animate-in fade-in slide-in-from-bottom-6 duration-700">
              {renderContent()}
            </div>
          </div>
        </main>
      </div>

      {showEmergency && <EmergencySystem onClose={() => setShowEmergency(false)} />}
      {showReport && <ReportIssue onClose={() => setShowReport(false)} />}

      <div className="fixed inset-0 pointer-events-none z-[-1] opacity-[0.03]">
        <div className={`absolute inset-0 animate-pulse-slow ${user?.role === UserRole.Specialist ? 'bg-[radial-gradient(circle_at_50%_50%,_#3B82F6_0%,_transparent_70%)]' : user?.role === UserRole.Mentor ? 'bg-[radial-gradient(circle_at_50%_50%,_#10B981_0%,_transparent_70%)]' : 'bg-[radial-gradient(circle_at_50%_50%,_var(--able-primary)_0%,_transparent_70%)]'}`}></div>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  return (
    <AbilityProvider>
      <AppContent />
    </AbilityProvider>
  );
};

export default App;
